window.JASTROW_CHUNKS[3]={"1200":{"h":"אִיזְמֵיל","r":"A01200","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (זמל √<span dir=\"rtl\">מל</span>; cmp. b. h. <span dir=\"rtl\">סמל</span>; cmp. <a href=\"#\" data-headword=\"*אִיזְגָּרָא\">אִיזְגָּרָא</a>) <i>cutting tool, knife</i>, esp. <i>surgeon’s knife</i>. <span class=\"citation\">Targ. Job XVI, 9</span>; a. e.—<span class=\"citation\">Ḥull. 31ᵃ</span> <span dir=\"rtl\">א׳ שיש לו קרנים</span> a knife which has hornlike projections as ornaments. <span class=\"citation\">Y. Sabb. XIX, beg. 16ᵈ</span> <span dir=\"rtl\">אנשון מייתי או׳</span> they had forgotten to bring the knife (for circumcision). <span class=\"citation\">Ex. R. s. 26</span> man <span dir=\"rtl\">מכה באי׳ וכ׳</span> wounds with a knife (operating) and heals &amp;c. Pl. Chald. <span dir=\"rtl\">אִזְמֵלַיָּיא</span>; <span dir=\"rtl\">אִזְמַלְוָון</span> (f.). <span class=\"citation\">Targ. Is. XLIV, 13</span>. <span class=\"citation\">Targ. Josh. V, 2</span>.</div>","alt":["אִיזְמֵל","אִזְ׳","(אוּזְמֵל)"]},"1201":{"h":"איזמר","r":"A01201","html":"<div class=\"sense\">, <span class=\"citation\">Y. Shebi. IV, 35ᵃ</span>, v. <a href=\"#\" data-headword=\"זָמַר I\"><span dir=\"rtl\">זְמַר</span> I</a></div>","alt":[]},"1202":{"h":"אִיזְקָפָה","r":"A01202","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְקוּפָה\">אִסְקוּפָה</a></div>","alt":["(איזקפא)"]},"1203":{"h":"אִיזְתַּוְודָּא","r":"A01203","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיזְמֵיל\">אִזְ׳</a></div>","alt":[]},"1204":{"h":"אִיחוּי","r":"A01204","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אחי\">אחי</a>, Pi.) <i>the act of stitching together seam</i>, esp. with ref. to the rent of garments in mourning. <span class=\"citation\">Y. M. Kat. III, 83ᵇ</span> top; a. e.—<span class=\"citation\">M. Kat. 26ᵇ</span> א׳ אלכסנדרי Alexandrian (invisible) seam.</div>","alt":[]},"1205":{"h":"אִיחוּר","r":"A01205","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אחר</span>, Pi.) <i>delay, detention</i>. <span class=\"citation\">Y. Meg. III, 74ᵇ</span> top.</div>","alt":[]},"1206":{"h":"אִיחוּרָא","r":"A01206","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ps. LXXXIX, 52</span>, const. <a href=\"#\" data-headword=\"אִיחוּר\">אִיחוּר</a>.</div>","alt":[]},"1207":{"h":"*אִיחֲטָא","r":"A01207","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Ithp. of <a href=\"#\" data-headword=\"חִטָּא I\">חטא</a>) <i>one in the habit of sinning</i>. <span class=\"citation\">Y. Taan. I, 64ᵃ</span> top <span dir=\"rtl\">הוה א׳ בלישניה</span> was foul-mouthed; v. <span class=\"citation\">Arakh. 15ᵇ</span></div>","alt":[]},"1208":{"h":"אִיטָא","r":"A01208","html":"<div class=\"sense\"> (ἦτα) <i>the letter</i> (η) of the Greek Alphabet, the numerical value of which is <i>eight;</i> used in the way of a phonetic play (ἤτω, or ἰτά as though an adj. verbale of ἰέναι) to indicate <i>going</i> or <i>death</i>. <span class=\"citation\">Gen. R. s. 14</span>, beg. (proving that a seven months’ child can live, while an eight months’ child cannot) <span dir=\"rtl\">מדידכון אנא ממטי איט&quot;א אוכ&quot;טא</span>, <span dir=\"rtl\">לכון זיט&quot;א אפ&quot;טא</span> from your own (Greek) language I will prove it to you, ‘<i>Live</i> (ζήτω) <i>seven, Go, eight</i>’ (ζ = ἕπτα, η = ὄκτω). Y. Yeb. IV, 5ᵈ top; Tanḥ. B’midbar 18 (corr. acc.); Ibid. (ed. Buber) 21.</div>","alt":["אִיטָה I"]},"1209":{"h":"אִיטָאלְיָא","r":"A01209","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיטַלְיָא\">אִיטַלְיָא</a></div>","alt":[]},"1210":{"h":"אִיטָה I","r":"A01210","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אִיטָא\">אִיטָא</a></div>","alt":[]},"1211":{"h":"*אִיטָה II","r":"A01211","html":"<div class=\"sense\"> (Syr. <a href=\"#\" data-headword=\"אִיטָא\">איטא</a>, εἶτα) <i>and so</i> (indignantly). <span class=\"citation\">Y. Snh. I, 18ᵈ</span> top <span dir=\"rtl\">א׳ עבדתני וכ׳</span> how thou hast been the cause of my putting rabbis to shame!</div>","alt":[]},"1212":{"h":"אִיטִימוֹס","r":"A01212","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֱטִימוֹס\">אֱטִימוֹס</a></div>","alt":[]},"1213":{"h":"איטימיסייה","r":"A01213","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אֱטִימַ׳</span></div>","alt":[]},"1214":{"h":"אִיטְלוּלָא","r":"A01214","html":"<div class=\"sense\"> v. <span dir=\"rtl\">אִטְל׳</span></div>","alt":[]},"1215":{"h":"אִיטַלְיָא","r":"A01215","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Italy</i>, esp. the southern part of the peninsula, called Magna Graecia. <span class=\"citation\">Meg. 6ᵇ</span> ed. Ven. (omitt. in later ed.) <span dir=\"rtl\">א׳ של יון זה כרך גדול של רומי וכ׳</span> (Ms. M. <span dir=\"rtl\">שברומי</span> v. Rabb. D. S. a. l.) Greek Italy, that means the great city of Rome &amp;c. <span class=\"citation\">Gen. R. s. 37</span> beg. <span class=\"citation\">Gen. R. s. 67</span> <span dir=\"rtl\">איטאליה</span>.—<span class=\"citation\">Targ. Ezek. XXVII, 7</span>; a. e.—<span class=\"citation\">Targ. I Chr. I, 7</span> <a href=\"#\" data-headword=\"אִטַלְיָא\">אִיטַלְיוֹן</a>.</div>","alt":["אִיטַלְיָה"]},"1216":{"h":"אִיטְלֵיז","r":"A01216","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַטְלֵיז\">אַטְלֵיז</a></div>","alt":["אִיטְלֵיס"]},"1217":{"h":"אִיטְלִיסִית","r":"A01217","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַטְלֵיז\">אַטְלֵיז</a>) <i>station.</i> Pl. <a href=\"#\" data-headword=\"אִיטְלִיסִית\">אִיטְלִיסִיֹּות</a>. Tanḥ. Masé 11; ib. (ed. Buber <span dir=\"rtl\">אִיטְלֵסִיֹּות</span>); v. <a href=\"#\" data-headword=\"אִסְטַלִּי\">אִסְטַלִּי</a>.</div>","alt":[]},"1218":{"h":"אִיטַלָּקוּתָא","r":"A01218","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִטְלָקוּתא\">אַטְלָקוּתָא</a></div>","alt":[]},"1219":{"h":"אִיטַלְקִי","r":"A01219","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִיטַלְיָא\">אִיטַלְיָא</a>) <i>Italian.</i> <span class=\"citation\">Kidd. I, 1</span> איסר הא׳ <i>As Italicus</i>, Italian as. <span class=\"citation\">Snh. VIII, 2</span> באיטלקי Y. ed. (Bab. <span dir=\"rtl\">הא׳</span>, corr. acc.); <span class=\"citation\">Lev. R. s. 37</span> <span dir=\"rtl\">באיטלקית</span> in Italian measure. Y. Sabb. XVIII, beg. 16ᶜ; a. e.</div>","alt":["אִיטַלְקִית"]},"1220":{"h":"איטם","r":"A01220","html":"<div class=\"sense\"> <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"עוּר I\">(העיר</a>), <span dir=\"rtl\">דא׳</span> read <span dir=\"rtl\">דְּאִיטָא</span> v. <a href=\"#\" data-headword=\"דְּיֵיטָא\">דְּיִיטִי</a></div>","alt":[]},"1221":{"h":"אִיטְמָא","r":"A01221","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָטַם\">אטם</a>) </div><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"אַטְמָא\">אַטְמָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>obstruction, dam</i>. <span class=\"citation\">Kidd. 70ᵇ</span></div>","alt":[]},"1222":{"h":"אִיטְמוֹן","r":"A01222","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Itmon</i>, surname of the angel Gabriel (<i>coverer of sin</i>). <span class=\"citation\">Snh. 44ᵇ</span>; v. <a href=\"#\" data-headword=\"אָטַם\">אָטַם</a>.</div>","alt":[]},"1223":{"h":"אִיטָּן","r":"A01223","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אטט</span>; cmp. <a href=\"#\" data-headword=\"חֲטַט I\">חטט</a>, a. <span dir=\"rtl\">אָטָט</span>) <i>calamus</i>, a reed used for writing (cmp. b. h. <a href=\"#\" data-headword=\"עֵט\">עֵט</a>). <span class=\"citation\">Tosef. Kil. III, 14</span> Var. ed. Zuck. (text <a href=\"#\" data-headword=\"אוטם\">אוטם</a>, prob. <span dir=\"rtl\">אִיטִּים</span>). <span class=\"citation\">Y. Kil. V, end, 30ᵃ</span> <a href=\"#\" data-headword=\"חִיטִּין\">חִיטִּין</a>. V. <a href=\"#\" data-headword=\"הִיטְּנֵי\">הִיטְּנֵי</a>.</div>","alt":[]},"1224":{"h":"*אִיטְּנִי","r":"A01224","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אִיטָּן\">foreg.</a>) <i>pencil, tube</i>. <span class=\"citation\">Sot. 48ᵇ</span> <span dir=\"rtl\">א׳ של אבר</span> (<span class=\"citation\">Y. Sot. IX, 24ᵇ</span> bot. a. Ar. <a href=\"#\" data-headword=\"טְנִי\">טני</a>) a leaden tube (Rashi = <a href=\"#\" data-headword=\"גּוּבְתָּא\">גּוּבְתָּא</a>). V. <a href=\"#\" data-headword=\"טְנִי\">טְנִי</a>.</div>","alt":[]},"1225":{"h":"אִיטֵּר","r":"A01225","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אִטֵּר\">אִטֵּר</a></div>","alt":[]},"1226":{"h":"אִיטְרָא","r":"A01226","html":"<div class=\"sense\"> <span class=\"citation\">B. Mets. 39ᵇ</span>; <span class=\"citation\">B. Bath. 29ᵇ</span> Ms. M., v. <a href=\"#\" data-headword=\"עִיטְרָא\">עִיטְרָא</a></div>","alt":[]},"1227":{"h":"אִיטְרוֹן","r":"A01227","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">נ־טר</span>, cmp. <a href=\"#\" data-headword=\"טוּרָנָא\">טוּרָנָא</a>) <i>watchman, officer</i>. <span class=\"citation\">Targ. Is. IX, 13</span>; <span class=\"citation\">XIX, 15</span>.</div>","alt":["אִטְרוּן"]},"1228":{"h":"איטרטלין","r":"A01228","html":"<div class=\"sense\"> read <span dir=\"rtl\">אִיסְטְרַטִּילָטִין</span>, v. <a href=\"#\" data-headword=\"אִסְטְרָטִילָטָא\">אִסְטְרַטִּילָטָא</a></div>","alt":[]},"1229":{"h":"אֵיי","r":"A01229","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵי III\"><span dir=\"rtl\">אֵי</span> III</a></div>","alt":[]},"1230":{"h":"אַיְיבוּ","r":"A01230","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִבּוּ\">אִבּוּ</a></div>","alt":[]},"1231":{"h":"אַיְידָא","r":"A01231","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵידֵין\">אֵידֵין</a></div>","alt":["אַיְידִי"]},"1232":{"h":"אַיְידֵי","r":"A01232","html":"<div class=\"sense\"> (contr. of <span dir=\"rtl\">על ידי</span>; v. <a href=\"#\" data-headword=\"אַ־\">אַ־</a>) </div><div class=\"sense\"><b>1)</b> <i>by the way of, through</i>. <span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">א׳ פומיה</span> through his mouth.—<span class=\"citation\">Naz. 2ᵃ</span> <span dir=\"rtl\">א׳ בהמה</span> through the instrumentality of the animal; a. fr.</div><div class=\"sense\"><b>—2)</b>  (conj.) <i>because, since as</i>. <span dir=\"rtl\">א׳ דתני … תני נמי</span> as the compiler had to state this, he incidentally mentions also the other. <span class=\"citation\">Kidd. 65ᵃ</span>; a. fr.</div>","alt":[]},"1233":{"h":"אייזן","r":"A01233","html":"<div class=\"sense\"> <span class=\"citation\">Snh. 106ᵃ</span>, v. <a href=\"#\" data-headword=\"זְנֵי\">זְנֵי</a></div>","alt":[]},"1234":{"h":"אַיְיכַל","r":"A01234","html":"<div class=\"sense\"> Af. of <a href=\"#\" data-headword=\"אֲכַל\">אֲכַל</a>.</div>","alt":[]},"1235":{"h":"אייל","r":"A01235","html":"<div class=\"sense\"> &amp;c., v. <span dir=\"rtl\">איל׳</span></div>","alt":["איילא"]},"1236":{"h":"אַיְילֵן","r":"A01236","html":"<div class=\"sense\"> (= <span dir=\"rtl\">אי הלין</span>) <i>where are those?, which?</i>. <span class=\"citation\">Y. Ber. II, 5ᵇ</span> <span dir=\"rtl\">א׳ רבנן</span> which rabbis?</div>","alt":[]},"1237":{"h":"אִיֵּים","r":"A01237","html":"<div class=\"sense\">, Pi. of <a href=\"#\" data-headword=\"אָיַם\">אָיַם</a>.</div>","alt":[]},"1238":{"h":"אִיֵּין","r":"A01238","html":"<div class=\"sense\">, Pi. of <a href=\"#\" data-headword=\"אָיַן\">אָיַן</a>.</div>","alt":[]},"1239":{"h":"אֵיינוֹי","r":"A01239","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"הַיְינוּ\">הֵיינוּ</a>) <i>is it he?</i> <span class=\"citation\">Cant. R. to V, 16</span> <span dir=\"rtl\">א׳ בריך</span> is this thy son?</div>","alt":[]},"1240":{"h":"איינטבלינית","r":"A01240","html":"<div class=\"sense\"> read <a href=\"#\" data-headword=\"*אִסְפְּלָנִית\">אִסְפְּלָנִית</a>.</div>","alt":["איינטפ׳"]},"1241":{"h":"*איינים","r":"A01241","html":"<div class=\"sense\"> Y. Dem. VII, 26ᵇ, R. S. to <span class=\"citation\">Dem. VII, 3</span> <span dir=\"rtl\">אטימויי׳</span>, <a href=\"#\" data-headword=\"אֱטִימוֹס\">אטימוס</a>, prob. <span dir=\"rtl\">אֲטוֹנוֹס</span> m. (ἄτονος) <i>languid, feeble</i>.</div>","alt":["אייניס"]},"1242":{"h":"אִיָּיר","r":"A01242","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוֹר\">אור</a>; cmp. b. h. <a href=\"#\" data-headword=\"זִיו\">זִיו</a>) <i>Iyar</i>, the second month of the Hebrew calendar, of twenty nine days, varying betw. the tenth of April and the eighth of June. <span class=\"citation\">R. Hash. 3ᵃ</span>; a. fr. [V. Schrader K. A. T. glossary.]</div>","alt":[]},"1243":{"h":"*אֲיָירָא","r":"A01243","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוֹר\">אור</a>; cmp. <a href=\"#\" data-headword=\"יְאוֹר\">יְאֹר</a> esp. <span class=\"citation\">Job XXVIII, 10</span>; v. H. Dict. s. v.) <i>channel, duct</i>. <span class=\"citation\">Y. M. Kat. I, 80ᵇ</span> bot. <span dir=\"rtl\">א׳ דציפורין וכ׳</span> the duct of Zepph. was damaged during the festive week.</div>","alt":[]},"1244":{"h":"אַיְירִי","r":"A01244","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"ארי\">ארי</a>, <a href=\"#\" data-headword=\"אֲרָא\"><a href=\"#\" data-headword=\"אֲרָא\">אֲרָא</a>.</a></div>","alt":[]},"1245":{"h":"אַיְירִינוֹן","r":"A01245","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (εἰρίνεον, εἰρινοῦν, neut.) <i>woolen</i>. <span class=\"citation\">Esth. R. to I, 6</span> (ref. to Aquila’s translation).</div>","alt":[]},"1246":{"h":"אַיְישַׁר","r":"A01246","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אַיְשַׁר\">אַיְשַׁר</a></div>","alt":[]},"1247":{"h":"אֵיךְ","r":"A01247","html":"<div class=\"sense\"><i>as, how</i>. <span class=\"citation\">Targ. Prov. XX, 20</span>; a. fr.</div>","alt":[]},"1248":{"h":"אֵיכָא","r":"A01248","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"אִי II\">אֵי</a> a. <a href=\"#\" data-headword=\"כָּא\">כָּא</a>) <i>where now?</i> (ubinam). <span class=\"citation\">Targ. O. Gen. XXXVII, 16</span> (ed. Berl.); a. e., v. <a href=\"#\" data-headword=\"אֵיכַן\">אֵיכַן</a> a. <a href=\"#\" data-headword=\"הֵיכָא\">הֵיכָא</a>.</div>","alt":[]},"1249":{"h":"אִיכָּא","r":"A01249","html":"<div class=\"sense\"> (contr. of <span dir=\"rtl\">אִית־כָּא</span>) </div><div class=\"sense\"><b>1)</b> <i>there is, there are</i> (<i>sunt qui</i>). <span dir=\"rtl\">א׳ דאמרי</span> (abbrev. <span dir=\"rtl\">א&quot;ד</span>.) some say. <span class=\"citation\">Ḥull. 3ᵇ</span>; a. fr. <span dir=\"rtl\">א׳ בינייהו</span> they differ in this &amp;c. <span class=\"citation\">Ib. 4ᵃ</span>; a. fr.—<span dir=\"rtl\">מאי א׳ למימר</span> what is there to say? how can it be explained? what can you reply? <span class=\"citation\">Ib. 12ᵃ</span> top; a. fr.—</div><div class=\"sense\"><b>*2)</b> <i>he who</i>. <span class=\"citation\">Targ. Prov. XIX, 7</span>. [Prob. to be read <a href=\"#\" data-headword=\"אִינָא\">אִינָא</a>.]</div>","alt":[]},"1250":{"h":"אֵיכְדֵּין","r":"A01250","html":"<div class=\"sense\"><i>how then! how!</i> <span class=\"citation\">Targ. O. Deut. I, 12</span>; a. e.; <span class=\"citation\">V</span>. <a href=\"#\" data-headword=\"אֵיכָא\">אֵיכָא</a>.</div>","alt":[]},"1251":{"h":"אֵיכָה","r":"A01251","html":"<div class=\"sense\"> (b. h. = <a href=\"#\" data-headword=\"אֵיכָה\">אֵי־כֹה</a>) </div><div class=\"sense\"><b>1)</b> <i>oh how! oh!</i> <span class=\"citation\">Gen. R. s. 19</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>Ekhah</i>, name of the Book of Lamentations, also <span dir=\"rtl\">מגילת א׳</span>.—א׳ רבתי <i>Ekhah Rabbathi</i> (<i>Lam. R.</i>), Midrash Rabboth on Lamentations.</div>","alt":[]},"1252":{"h":"אִיכּוּ","r":"A01252","html":"<div class=\"sense\"><b>1)</b>  (= (= <span dir=\"rtl\">אי כה</span>) <i>if now; oh that</i>. <span class=\"citation\">Bets. 4ᵇ</span> top <span dir=\"rtl\">א׳ השתא אשתלאי</span> if I (had given my decision forthwith) I should have made a mistake. <span class=\"citation\">Yeb. 46ᵃ</span>.—<span class=\"citation\">Snh. 107ᵃ</span> <span dir=\"rtl\">א׳ זממא וכ׳</span> oh that a muzzle had been put on my enemy’s (euphem. for <i>my</i>) mouth! i.e. oh that I never had said this!</div><div class=\"sense\"><b>—2)</b>  pr. n. f. <i>Ikhu</i>. Taan. 35ᵃ what is thy name? She said, Ikhu.—Said he <span dir=\"rtl\">א׳ נמטו כשוריך</span> oh that thy joists were sufficiently long!</div>","alt":[]},"1253":{"h":"אִיכּוּל","r":"A01253","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲכַל\">אכל</a>) <i>consumption, combustion</i>. <span class=\"citation\">Y. Ber. IV, 7ᵇ</span> top, a. e. <span dir=\"rtl\">א׳ איברים</span> the consumption on the altar of the pieces of the daily offering; v. <a href=\"#\" data-headword=\"אֵבֶר\">אֵבֶר</a>. [V. <a href=\"#\" data-headword=\"עִיכּוֹל\">עִיכּוּל</a>.]</div>","alt":[]},"1254":{"h":"אִיכּוּמָא","r":"A01254","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָכַם\">אכם</a>) <i>black color, something black</i>. Y. Sabb. II, 4ᵈ <span dir=\"rtl\">ההן א׳</span> black naphta.</div>","alt":[]},"1255":{"h":"אִיכּוּף","r":"A01255","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אוּכָּף\">אוּכָּף</a></div>","alt":[]},"1256":{"h":"אֵיכַן","r":"A01256","html":"<div class=\"sense\"> (<span dir=\"rtl\">אֵי־כַּאַן</span>, v. <a href=\"#\" data-headword=\"אֵיכָא\">אֵיכָא</a>) <i>where?</i> also relat. <i>where</i>, &amp;c. <span class=\"citation\">Targ. Gen. XXXVII, 16</span>. <span class=\"citation\">Y. Ber. I, 3ᵇ</span> bot. <span dir=\"rtl\">א׳ יצאת בת קול</span> where did that divine voice come forth? Ib. III, 6ᵃ bot. <span dir=\"rtl\">מא׳ ללמוד</span> one from whom to learn. Ib. IV, 7ᵃ <span dir=\"rtl\">מא׳ למדו וכ׳</span> whence did they derive the obligation of three prayers?—<span dir=\"rtl\">עד א׳</span> how far? how long? <span class=\"citation\">Y. Peah VIII, beg. 20ᵈ</span>. <span class=\"citation\">Cant. R. to VI, 4</span>; a. e. [In Babli <a href=\"#\" data-headword=\"הֵיכָן\">הֵיכַן</a> q. v.]</div>","alt":["אֵיכָן"]},"1257":{"h":"איכפייה","r":"A01257","html":"<div class=\"sense\"> <span class=\"citation\">Esth. R. to I, 1</span>ᵇ <span dir=\"rtl\">בני אי׳</span> (Var. <span dir=\"rtl\">אוכ׳</span>), v. <a href=\"#\" data-headword=\"*אוּכַּיְיפָא\">אוּכַּיְיפָא</a></div>","alt":["איכפית"]},"1258":{"h":"אִיכְפַּת","r":"A01258","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אִכְפָּה\">אַכְפָּה</a></div>","alt":[]},"1259":{"h":"אִיכָּר","r":"A01259","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>husbandman, farm-laborer</i>. <span class=\"citation\">Arakh. VI, 3</span> (<span class=\"citation\">23ᵇ</span>) <span dir=\"rtl\">אם היה אי׳</span> (Mish. <span dir=\"rtl\">אכ׳</span>) if he is a husbandman; a. e.—Pl. <span dir=\"rtl\">אִיכָּרִים</span>. <span class=\"citation\">Y. M. Kat. III, 82ᵇ</span> bot. <a href=\"#\" data-headword=\"איבריו\">איבריו</a> (read <span dir=\"rtl\">אִיכָּרָיו</span>) his farm-hands. [V. <a href=\"#\" data-headword=\"איבריו\">איבריו</a>.]</div>","alt":["אִכָּר"]},"1260":{"h":"אִיכָּרָא","r":"A01260","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XXI, 10</span>; a. e.—Pl. <span dir=\"rtl\">אִיכָּרִין</span>, <span dir=\"rtl\">אִיכָּרַיָּיא</span>, <span dir=\"rtl\">אִיכָּרֵי</span>. <span class=\"citation\">Targ. Jer. XXXI, 23</span>; a. e.—<span class=\"citation\">Erub. 28ᵇ</span>, v. <a href=\"#\" data-headword=\"אִיזְלָא\">אִיזְלָא</a>.—*Denom. <a href=\"#\" data-headword=\"אִיכַּרְיָיתָא\">אִיכַּרְיָיתָא</a> f. pl. <span class=\"citation\">Erub. 82ᵇ</span> רפתא א׳ <i>farmer’s loaves;</i> v., however, <a href=\"#\" data-headword=\"*אִיבְרָיָאתָא\">אִיבְרָיָאתָא</a>.</div>","alt":["אִכָּ׳"]},"1261":{"h":"אִיכְרוּם","r":"A01261","html":"<div class=\"sense\"> v. <span dir=\"rtl\">אִכְ׳</span></div>","alt":[]},"1262":{"h":"אִיכַּרְיָיתָא","r":"A01262","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אִיכָּרָא\">אִיכָּרָא</a></div>","alt":[]},"1263":{"h":"*אֱיָל","r":"A01263","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>superiority, patronage, arbitration</i>; v. <span class=\"citation\">Midr. Till. to Ps. LXXXVIII, 5</span>. <span class=\"citation\">Midr. Till. to Ps. CIV, 29</span> (ref. to <span class=\"citation\">Is. LVII, 19</span> <i>peace, peace</i> &amp;c.) <span dir=\"rtl\"><a href=\"#\" data-headword=\"אִילּוּלָא\">אילולי</a> (<span dir=\"rtl\">אֱיָילוֹ</span>) <span dir=\"rtl\">אֱיָלוֹ של וכ׳</span></span></div>","alt":["אֱיָיל"]},"1264":{"h":"אַיִל","r":"A01264","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>ram</i> (<i>the strong</i>). <span class=\"citation\">B. Kam. 65ᵇ</span> if one stole <span dir=\"rtl\">טלה ונעשה א׳</span> a lamb and it grew to be a ram. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">א׳ בן יומו קרוי א׳</span> a ram one day old is called a ram (<i>ayil</i> is used in a general sense, irrespective of age). <span class=\"citation\">R. Hash. 16ᵃ</span>; a. fr.—[*Pl. <a href=\"#\" data-headword=\"אֵלִים\">אֵלִים</a>. Tosef. <span class=\"citation\">R. Hash. I</span>II (II), 3 (Var. <span dir=\"rtl\">יעלים</span>).]—</div><div class=\"sense\"><b>*2)</b>  <span dir=\"rtl\">א׳ קמצא</span> [perh. <a href=\"#\" data-headword=\"אַיָּל\">אַיָּל</a> q. v.] <i>a species of locusts.</i> <span class=\"citation\">Eduy. VIII, 4</span>; <span class=\"citation\">Pes. 16ᵃ</span>; <span class=\"citation\">Ab. Zar. 37ᵃ</span> <a href=\"#\" data-headword=\"אייל\">אייל</a> ed. (Ms. M. <a href=\"#\" data-headword=\"איול\">אייול</a>), v. <a href=\"#\" data-headword=\"דְּכֵי\">דְּכֵי</a>.</div>","alt":["אַיִיל"]},"1265":{"h":"אַיָּל","r":"A01265","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> prob. fr. <a href=\"#\" data-headword=\"אֲוַל\">אול</a> = <span dir=\"rtl\">עול</span>, cmp. Var. lect. of <a href=\"#\" data-headword=\"אַיֶּלֶת II\"><span dir=\"rtl\">אַיֶּלֶת</span> II</a>; cmp. <span dir=\"rtl\">אלל</span>) [<i>the climber</i>], <i>hart</i>. <span class=\"citation\">Ḥull. 28ᵃ</span>; a. e.</div>","alt":[]},"1266":{"h":"אֵילָא","r":"A01266","html":"<div class=\"sense\"><b>1)</b> ; trnsf. <i>beak of a ship</i> (a beam to which the head of a ram was attached), <i>prow</i>. <span class=\"citation\">Ned. 50ᵃ</span></div><div class=\"sense\"><b>—2)</b> <i>projection from a lateral wall, buttress</i>, &amp;c. <span class=\"citation\">Targ. Ezek. XL, 48</span>; a. e. (Var. <a href=\"#\" data-headword=\"אֵלָא\">אֵלָא</a>).—</div><div class=\"sense\"><b>*3)</b>  (cmp. <a href=\"#\" data-headword=\"אַיִל\">אַיִּל</a> 2) name of a <i>worm</i> or <i>mite</i> in grapes. <span class=\"citation\">Sabb. 90ᵃ</span> <span dir=\"rtl\">איל</span> (Rashi a. Ms. Oxf. <span dir=\"rtl\">איי׳</span>).</div>","alt":["אַיְילָא"]},"1267":{"h":"אַיָּלָא","r":"A01267","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Deut. XIV, 5</span>; a. fr.—<span class=\"citation\">Bekh. 7ᵇ</span>.—Pl. <span dir=\"rtl\">אַיָּלִין</span>, <a href=\"#\" data-headword=\"אִילְיָא\">אַיָּלַיָּא</a>, <span dir=\"rtl\">אַיָּי׳</span>. Targ. Y. Deut. l. c. (ed. Vien. <a href=\"#\" data-headword=\"אִילְיָן\">אִילְיָן</a>!) <span class=\"citation\">Targ. Lam. I, 6</span>.</div>","alt":["אַיָּילָא","אַיְּלָא"]},"1268":{"h":"אִילָא","r":"A01268","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ila</i> </div><div class=\"sense\"><b>1)</b> ; a Tannai. <span class=\"citation\">Bekh. IV, 5</span> (<span class=\"citation\">29ᵃ</span>), a medical expert <span dir=\"rtl\">כא׳ ביבנה</span> like I. in Yabneh’.</div><div class=\"sense\"><b>—2)</b>  an Amora. <span class=\"citation\">Yoma 73ᵇ</span>; a. fr. [Other forms <span dir=\"rtl\">אילעא</span>, <span dir=\"rtl\">אילי</span>, <a href=\"#\" data-headword=\"הִילָא I\">הילא</a>; v. Frankel M’bo p. 75ᵇ.]</div>","alt":[]},"1269":{"h":"אִילָּא","r":"A01269","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֶלָּא\">אֶלָּא</a>. <span class=\"citation\">Y. Shebu. I, 33ᵇ</span> bot. <span dir=\"rtl\">לא מסתברא דאי׳</span> v. <a href=\"#\" data-headword=\"חִילּוּפָא\">חִילּוּפָא</a>.</div>","alt":[]},"1270":{"h":"אילאסרין","r":"A01270","html":"<div class=\"sense\"> v. <span dir=\"rtl\">אִילְצָרָא</span></div>","alt":[]},"1271":{"h":"אֵילַהּ","r":"A01271","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֱלָהּ\">אֱלָהּ</a></div>","alt":[]},"1272":{"h":"אַיָּלָה","r":"A01272","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>hind, roe</i>. <span class=\"citation\">B. Bath. 16ᵇ</span> top <span dir=\"rtl\">א׳ רחמה צר</span> the hind has a narrow womb (vagina).</div><div class=\"sense\"><b>—2)</b>  mostly <span dir=\"rtl\">אילת השחר</span> <i>the first rays</i> (climber) <i>of the morning dawn</i>; cmp. <span class=\"citation\">Yoma 29ᵃ</span>. <span class=\"citation\">Y. Ber. I, 2ᶜ</span>; a. fr.; (cmp. <span class=\"citation\">Gen. XIX, 15</span> <span dir=\"rtl\">השחר עלה</span>).</div>","alt":["אַיָּילָה","אַיֶּילֶת"]},"1273":{"h":"אִילָּהֵין","r":"A01273","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִילּוּלָא\">אִלָּ׳</a></div>","alt":[]},"1274":{"h":"אֵילּוּ","r":"A01274","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵלּוּ\">אֵלּוּ</a></div>","alt":[]},"1275":{"h":"אילו","r":"A01275","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 17</span> <span dir=\"rtl\">א׳ פילוס</span> v. <a href=\"#\" data-headword=\"אִילְיוֹפֹּולִיס\">אִילְיוֹפֹּולִיס</a></div>","alt":[]},"1276":{"h":"אִילּוּ","r":"A01276","html":"<div class=\"sense\"> (late b. h. = <span dir=\"rtl\">אִן III</span>, 6) <i>if</i> (oh that!). Targ. Ez. l. c.; a. fr.—<span class=\"citation\">Gen. R. s. 12</span> <span dir=\"rtl\">א׳ היו … היתה נאה</span> if the pillars had been higher, it would have looked better; a. fr.—וא׳ <i>but if</i> (<i>considering</i>), <i>whereas</i>. <span class=\"citation\">Ber. 20ᵃ</span>; a. fr.—<span dir=\"rtl\">וא׳ ר׳</span> whereas R. Yudah &amp;c.—א׳ … וא׳ <i>while …, in this case on the contrary</i>. <span class=\"citation\">Ib. 37ᵃ</span> <span dir=\"rtl\">דא׳ במעשה … ואי׳ וכ׳</span> for while over pot-dishes we say the benediction &amp;c., here, in our case we say—; a. fr. Y. Shebu. I, 33ᵇ top—<span dir=\"rtl\">ש אי׳ מי</span> in the case of one who …—<span dir=\"rtl\">כְּאִילּוּ</span>, <span dir=\"rtl\">כְּאִלּוּ</span>, contr. <a href=\"#\" data-headword=\"כִּילּוּ\">כִּילּוּ</a> <i>as if, as though</i>. <span class=\"citation\">Y. Maas. Sh. V, 56ᵈ</span> bot. <span dir=\"rtl\">כא׳ לפניו שינה</span> as if the Lord were, so to say, asleep, when Israel is in trouble; a. v. fr.—Y. Kil. IV, end, 29ᵈ <span dir=\"rtl\">כילו</span>.</div>","alt":["אִלּוּ"]},"1277":{"h":"אֵילוֹגִין","r":"A01277","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (elogium) <i>record, bill of indictment, sentence stating the crime, verdict</i>. <span class=\"citation\">Ex. R. s. 15</span> שאעביר אי׳ שלכם I may set aside (cancel) your verdict. <span class=\"citation\">Ex. R. s. 31</span> <span dir=\"rtl\">אל׳</span>. [Corr. acc. <span class=\"citation\">Num. R. s. 16</span> <span dir=\"rtl\">אליגון</span>; <span class=\"citation\">Gen. R. s. 28</span>, beg. <a href=\"#\" data-headword=\"אגאלוגין\">אגאליגין</a>; <span class=\"citation\">Lam. R. to I, 14</span> <a href=\"#\" data-headword=\"אַנְלוֹגִין\">אנלוגין</a>, <a href=\"#\" data-headword=\"אולוגלוגין\">אולוגלוגין</a> Ar.; <span class=\"citation\">Midr. Till. to Ps. I, 5</span> <a href=\"#\" data-headword=\"אגלין\">אגלין</a>; <span class=\"citation\">Pesik. R. s. 44</span> <a href=\"#\" data-headword=\"אמלוגין\">אמלוגין</a>, <span dir=\"rtl\">אמלגין</span>.]</div>","alt":["אֵלוֹגִין"]},"1278":{"h":"אילווא","r":"A01278","html":"<div class=\"sense\"> <span class=\"citation\">Git. 69ᵇ</span>, v. <a href=\"#\" data-headword=\"אַלְוָא\">אַלְוָא</a></div>","alt":[]},"1279":{"h":"אִילַּוָּיוּתָא","r":"A01279","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"לוי\">לוי</a>) (<i>lamentation at</i>) <i>funeral escorts</i>. <span class=\"citation\">Targ. Job. III, 7</span> Ms. (ed. <a href=\"#\" data-headword=\"אִלְיוּתָא\">אִלְיוּתָא</a>; h. text <a href=\"#\" data-headword=\"לִוְיָתָן\">לִוְיָתָן</a>).</div>","alt":[]},"1280":{"h":"אֵילוּל","r":"A01280","html":"<div class=\"sense\">= <a href=\"#\" data-headword=\"אֱלוּל\">אֱלוּל</a>. <span class=\"citation\">Targ. Y. Num. XIV, 37</span>.</div>","alt":[]},"1281":{"h":"אִילּוּלָא","r":"A01281","html":"<div class=\"sense\"><b>1)</b> (b. h. <a href=\"#\" data-headword=\"לוּלַי\">לוּלֵי</a> = <a href=\"#\" data-headword=\"אִילּוּלָא\">אִילּוּ לֹא</a>, ch. <a href=\"#\" data-headword=\"אִילּוּלָא\">אִילּוּ לָא</a>) <i>were it not, but for</i> (followed by h. <a href=\"#\" data-headword=\"שֶׁ־\">שֶׁ־</a>, ch. <a href=\"#\" data-headword=\"דְּ־\">דְּ־</a>, or by a noun without a verb; v. <a href=\"#\" data-headword=\"אִלְמָלֵא\">אִלְמָלֵא</a>). <span class=\"citation\">Targ. Y. Deut. I, 1</span>; a. e.—Mekh. B’shall., Amalek 1 <span dir=\"rtl\">א׳ שאמר משה</span> but for Moses, who said &amp;c; a. fr.</div><div class=\"sense\"><b>—2)</b>  (followed by a verb without <span dir=\"rtl\">ש־</span> or <span dir=\"rtl\">ד־</span> = <a href=\"#\" data-headword=\"אִילּוּלָא\">אִילּוּלֻא</a> h. <a href=\"#\" data-headword=\"אִילּוּ\">אִילּוּ</a>) <i>if indeed, if</i>. <span class=\"citation\">Targ. Koh. VI, 6</span>. <span class=\"citation\">Targ. Esth. VII, 4</span>; a. e.—</div><div class=\"sense\"><b>*3)</b> <i>oh that!</i> <span class=\"citation\">Num. R. s. 2</span>, beg. <span dir=\"rtl\">א׳ הוא מדגיל וכ׳</span> oh that He would allow His love to be a banner over me! [<a href=\"#\" data-headword=\"אַלְוַאי\">אלואי</a> as in preceding lines?]—</div><div class=\"sense\"><b>*4)</b> <i>whether</i>. <span class=\"citation\">Targ. Cant. VI, 11</span> <span dir=\"rtl\">א׳ פשן וכ׳</span></div>","alt":["אִילּוּלֵי","אִלּ׳"]},"1282":{"h":"אִילּוּלֵיפוֹן","r":"A01282","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"אִילּוּלָא\">preced.</a> with <a href=\"#\" data-headword=\"פּוֹן\">פון</a> = h. <a href=\"#\" data-headword=\"פֶּן\">פֶּן</a>) <i>if not perchance, but for</i>. <span class=\"citation\">Targ. Y. Gen. XXXI, 42</span>; a. fr. (in some ed. in two words <span dir=\"rtl\">אילולי פון</span>).</div>","alt":["אִלּוּלָפוֹן"]},"1283":{"h":"אַיְלוֹנִית","r":"A01283","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (prob. fr. <a href=\"#\" data-headword=\"אַיִל\">אַיִל</a>; cmp. <a href=\"#\" data-headword=\"זָכָר\">זָכָר</a> a. <a href=\"#\" data-headword=\"דְּכִי\">דְּכַי</a>) (<i>the man-like</i>) <i>barren, wombless, incapable of conception</i>. <span class=\"citation\">Keth. 11ᵃ</span> (etymol. from <a href=\"#\" data-headword=\"אַיִל\">אַיִל</a>) <span dir=\"rtl\">איי׳ דוכרנית</span> <i>aylonith</i> means ram-like. <span class=\"citation\">Nidd. V, 9</span> (<span class=\"citation\">47ᵇ</span>); a. fr.</div>","alt":["אַיְילוֹנִית"]},"1284":{"h":"אילוסיס","r":"A01284","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִלְסִיס\">אִלְסִיס</a></div>","alt":[]},"1285":{"h":"אילוסריקא","r":"A01285","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹלוֹסֵירִיקָא\">אוֹלוֹסֵירִיקָא</a></div>","alt":[]},"1286":{"h":"*אִילוֹפִיסָה","r":"A01286","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (prob. ὑελέψης <i>glass</i>-smelter) <i>Ilofisa</i>. <span class=\"citation\">Y. Ter. I, 40ᶜ</span> top.</div>","alt":[]},"1287":{"h":"אילטיס","r":"A01287","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִלְסִיס\">אִלְסִיס</a></div>","alt":[]},"1288":{"h":"אִילְיָא","r":"A01288","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ילי</span>, <a href=\"#\" data-headword=\"אלי I\">אלי</a>, v. <a href=\"#\" data-headword=\"יְלֵל\">ילל</a>; cmp. <a href=\"#\" data-headword=\"אֱלִי\">אֱלִי</a> <span class=\"citation\">Joel I, 8</span>) <i>mourning, lamentation, dirge</i>. <span class=\"citation\">Targ. II Sam. I, 17</span>; <span class=\"citation\">II Chron. XXXV, 25</span>; a. fr.—<span class=\"citation\">Y. Sot. VII, 21ᶜ</span> top; Meg. I, 71ᵇ bot. <span dir=\"rtl\">סורסי לאילייא</span> Syriac is adapted for dirges; <span class=\"citation\">Esth. R. to I, 22</span> <span dir=\"rtl\">פרסי לאלייה</span> (corr. acc.).</div>","alt":["אִילְיָיא","אֶלְיָא","(אֶלְיָיה)"]},"1289":{"h":"*אִילִיאוֹס","r":"A01289","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἥλιος) <i>Sun.</i> <span class=\"citation\">Ex. R. s. 15</span>. [The words from <a href=\"#\" data-headword=\"סַנְדְּרוֹס\">סנדריאוס</a> to <span dir=\"rtl\">אורח</span> are a marginal gloss, prob. to be emended: (<span dir=\"rtl\">אלכ</span>) <span dir=\"rtl\">סנדרוס איוס איליאו היה שמו והשמש וכ׳</span></div>","alt":["אִילְיוֹס"]},"1290":{"h":"אִילְיוֹן","r":"A01290","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִילּוּלָא\">אִלְ׳</a></div>","alt":[]},"1291":{"h":"אִילְיוֹפֹּולִיס","r":"A01291","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Ἡλιόπολις) <i>Heliopolis</i>, in lower Egypt. Pesik. Vayhi p. 63ᵇ Ar. (ed. <a href=\"#\" data-headword=\"פּוֹלִיס\">פוליס</a>); <span class=\"citation\">Pesik. R. s. 17</span> <span dir=\"rtl\">אילו פוליס</span> (corr. acc.)</div>","alt":["אִלְיוֹ׳"]},"1292":{"h":"אִילֵימָא","r":"A01292","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"אִי IV\">אִי</a> <i>if</i>, and <a href=\"#\" data-headword=\"לֵימָא\">לֵימָא</a> = <span dir=\"rtl\">לֵימַר</span>) prop. <i>if to say</i>, hence a dialectic term in debate, <i>you do not mean to say</i>, or <i>shall I say</i>? <span class=\"citation\">B. Mets. 12ᵇ</span> <span dir=\"rtl\">א׳ כשחייב מודה</span> shall I say (it means) when the debtor concedes (his indebtedness)? <span class=\"citation\">Kidd. 74ᵃ</span> <span dir=\"rtl\">אהייא א׳ וכ׳</span> what does it refer to? You cannot say it refers to … <span class=\"citation\">Sabb. 150ᵇ</span> (some ed. <span dir=\"rtl\">אל׳</span>). <span class=\"citation\">Yoma 52ᵇ</span>; a. v. fr.</div>","alt":["(אִלֵּ׳)"]},"1293":{"h":"אִילֵּימָא I","r":"A01293","html":"<div class=\"sense\"><i>unless, but for;</i> v. <a href=\"#\" data-headword=\"אִלֵּימָא I\">אִלֵּימָא</a>.</div>","alt":[]},"1294":{"h":"אִילֵּימָא II","r":"A01294","html":"<div class=\"sense\"><i>mute</i>, v. <a href=\"#\" data-headword=\"אִלְּמָא\">אִלְּמָא</a>.</div>","alt":[]},"1295":{"h":"אִילְיֵין","r":"A01295","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִילֵּין\">אִילֵּין</a></div>","alt":[]},"1296":{"h":"אילין","r":"A01296","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Kil. V, 26</span>, ed. Zuck. <a href=\"#\" data-headword=\"קְלָאִילָּן\">קלא אילן</a>, v. <a href=\"#\" data-headword=\"קלא\">קלא</a> <span dir=\"rtl\">אילן</span>.</div>","alt":[]},"1297":{"h":"אִילְיָן","r":"A01297","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַיָּלָא\">אַיָּלָא</a></div>","alt":[]},"1298":{"h":"אִילֵּין","r":"A01298","html":"<div class=\"sense\"> com. pl. (h. <i>these, those</i>. <span class=\"citation\">Targ. Jud. XX, 17</span>; a. e.—<span class=\"citation\">Y. Ber. V, 9ᶜ</span> top <span dir=\"rtl\">א׳ דמתרגמין</span> those who translate; a. v. fr.—<span class=\"citation\">Y. Erub. III, 20ᵈ</span> top <span dir=\"rtl\">אילין אינון</span> insert <a href=\"#\" data-headword=\"מַאי\">מאי</a>, what are those (names mentioned)?</div>","alt":["(אִילְיֵין","אִלְיֵין)"]},"1299":{"h":"אִילִיס","r":"A01299","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אָלִיס\">אָלִיס</a></div>","alt":[]},"1300":{"h":"אֲיֵלִיתָא","r":"A01300","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָלְיְתָא\">אָלְיְתָא</a></div>","alt":[]},"1301":{"h":"אֵילֵךְ","r":"A01301","html":"<div class=\"sense\"> a. <i>hither, thither</i>. <span class=\"citation\">Targ. Y. Num. XXII, 4</span>.—<span dir=\"rtl\">(<span dir=\"rtl\">מכן</span>) <span dir=\"rtl\">מכאן וא׳</span></span> from now and further on, i.e. <i>after that</i>. <span class=\"citation\">Targ. Esth. II, 14</span>. <span class=\"citation\">Ber. I, 2</span>; a. fr.—<span class=\"citation\">Men. 28ᵇ</span> <span dir=\"rtl\">אחד א׳ ואחד א׳</span> one in this, another in that direction. <span class=\"citation\">Erub. 55ᵇ</span>. [Diff. from. <a href=\"#\" data-headword=\"אִלֵּךְ\">אִלֵּךְ</a>.] V. <a href=\"#\" data-headword=\"הֵילֵךְ\">הֵילֵךְ</a>.</div>","alt":["אִילַךְ"]},"1302":{"h":"אֵילָם","r":"A01302","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Elam</i>. Y. Kidd. IV, 65ᵈ top; v. <a href=\"#\" data-headword=\"עִילָם\">עילָם</a>.</div>","alt":[]},"1303":{"h":"אִילֵּם","r":"A01303","html":"<div class=\"sense\"><i>mute</i>, v. <a href=\"#\" data-headword=\"אִלֵּם\">אִלֵּם</a>.</div>","alt":[]},"1304":{"h":"אִילְּמָא","r":"A01304","html":"<div class=\"sense\">v. <a href=\"#\" data-headword=\"אִלְּמָא\">אִלְּמָא</a></div>","alt":[]},"1305":{"h":"אִילְּמָנָא","r":"A01305","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִלֵּימְנָא\">אִלֵּימְנָא</a></div>","alt":[]},"1306":{"h":"אִילָּן","r":"A01306","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. b. h. <a href=\"#\" data-headword=\"אַלֹּון I\">אֵלוֹן</a> <i>oak</i>, v. <a href=\"#\" data-headword=\"אֵלָה\">אֵלָה</a>) <i>tree.</i> <span class=\"citation\">Shebi. I, 1</span>, a. e. <span dir=\"rtl\">שדה הא׳</span> a field containing at least three trees within a distance of a S’ah (v. <a href=\"#\" data-headword=\"סְאָה\">סְאָה</a>). <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">א׳ סרק</span> bearing no edible fruit, opp. <span dir=\"rtl\">א׳ מאכל</span>.—<span class=\"citation\">Pes. 112ᵃ</span> (prov.) <span dir=\"rtl\">אם בקשת וכ׳</span> if you desire to be strangled, be hanged on a large tree, (if you must refer to an authority, select a good one).—Pl. <span dir=\"rtl\">אִילָּנוֹת</span>, const. <span dir=\"rtl\">אִילָּנֵי</span>. <span class=\"citation\">Shebi. I, 2</span>. <span class=\"citation\">Gen. R. s. 16</span>; a. fr.</div>","alt":[]},"1307":{"h":"אִילַן","r":"A01307","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. I, 11</span>; a. fr.—<span class=\"citation\">Ab. Zar. 50ᵇ</span>, v. <a href=\"#\" data-headword=\"ברי\">ברי</a> ch.—Pl. <span dir=\"rtl\">אִילָנִין</span>, <span dir=\"rtl\">אִילָנַיָּיא</span>, <span dir=\"rtl\">אִילָנַיָּא</span>, <span dir=\"rtl\">אִילָנֵי</span>, <a href=\"#\" data-headword=\"אִילַן\">אִלָ׳</a>. <span class=\"citation\">Targ. Gen. II, 5</span>; a. fr.—<span class=\"citation\">Lev. R. s. 12</span> <span dir=\"rtl\">מתקריין וכ׳</span> (insert <span dir=\"rtl\">פיריהון</span>) <a href=\"#\" data-headword=\"א׳\">א׳</a> fruits are named after the trees. <span class=\"citation\">B. Bath. 16ᵇ</span>; a. fr.—<span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">א׳ דסדום</span>, v. <a href=\"#\" data-headword=\"*אמבוניא\">אמבוניא</a>.—[<span dir=\"rtl\">קלא א׳</span>, <span dir=\"rtl\">תלא א׳</span>, v. s. <a href=\"#\" data-headword=\"קְלֵי ²\">קְלָא</a> a. <a href=\"#\" data-headword=\"תְּלָא\">תְּלָא</a> respectively.]</div>","alt":["אִילָנָא","אִלָ׳"]},"1308":{"h":"אִילֵס","r":"A01308","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אָלִיס\">אָלִיס</a></div>","alt":[]},"1309":{"h":"אִילְסָרִין","r":"A01309","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִלְצָרִין\">אִלְצָרִין</a></div>","alt":[]},"1310":{"h":"אִילפָא I","r":"A01310","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲלַף I\">אלף</a>, <a href=\"#\" data-headword=\"יְלֵף\">ילף</a>; Assyr. êlippu) <i>ship, raft</i>. <span class=\"citation\">Targ. Jon. I, 3</span>; a. e.—<span class=\"citation\">Lev. R. s. 12</span>, beg. <span dir=\"rtl\">כהדא א׳</span> like the ship tossed about on high sea. <span class=\"citation\">Koh. R. to III, 2</span> (prov.) at the time thou tiest thy Lulab (for the Feast of Booths) <span dir=\"rtl\">קטר אלפך</span> tie thy ship (cease navigation). <span class=\"citation\">Ab. Zar. 10ᵇ</span> <span dir=\"rtl\">ווי לה לאי׳ וכ׳</span> woe to the ship which leades without having paid its toll (of a convert who died before circumcision).—Trnsf. <i>the body of a chicken</i> (<i>chest-bone</i> resembling a ship). <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">נסבית הדין אי׳ וכ׳</span> (<a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a>) I took for myself this ship (of the chicken), for in a ship I came &amp;c.—Pl. <span dir=\"rtl\">אִילְפַיָּא</span>. <span class=\"citation\">Targ. Ps. CIV, 26</span>; a. e.</div>","alt":["אִלְפָא"]},"1311":{"h":"אִילְפָא II","r":"A01311","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ilfa</i>, an Amora. <span class=\"citation\">Taan. 21ᵃ</span>; a. fr. [In. Talm. Y. <a href=\"#\" data-headword=\"חִילְפַי\">חילפיי</a>]. <span class=\"citation\">R. Hash. 17ᵇ</span> אילְפָי וא&quot;ל א׳ <i>Ilfay</i> or, some say, <i>Ilfa</i> (v. Rabb. D. S. a. l.)</div>","alt":[]},"1312":{"h":"אִילְפַי","r":"A01312","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִילְפָא II\">preced.</a></div>","alt":[]},"1313":{"h":"אִילְפֵס","r":"A01313","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִילּוּלָא\">אִלְ׳</a></div>","alt":["אִילְקַט","אִילְקְטִי"]},"1314":{"h":"אַיֶּלֶת I","r":"A01314","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אַיָּלָה\">אַיָּלָה</a></div>","alt":[]},"1315":{"h":"אַיֶּלֶת II","r":"A01315","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (<i>not</i> bibl. <a href=\"#\" data-headword=\"אַיֶּלֶת I\">אֵילַת</a>) <i>Ayeleth</i>, one day’s journey south of Jerusalem. <span class=\"citation\">Maas. Sh. V, 2</span>; <span class=\"citation\">Bets. 5ᵃ</span> <a href=\"#\" data-headword=\"עַלַּת\">עלת</a> ed. (Ms. M. <span dir=\"rtl\">איילת</span>); <span class=\"citation\">R. Hash. 31ᵇ</span> <a href=\"#\" data-headword=\"אַיֶּלֶת I\">אילת</a> ed. (Ms. M. <span dir=\"rtl\">עַיֶּילֶת</span>; Ms. L. <a href=\"#\" data-headword=\"עַלַּת\">עלת</a> corr. into <a href=\"#\" data-headword=\"עַיְנוּתָא\">עיי׳</a>; Ms. 2 <span dir=\"rtl\">עגלת</span>; v. Rabb. D. S. a. l. note). [Bets. a. R. Hash. l. c. read <span dir=\"rtl\">מן הדרום</span> for <span dir=\"rtl\">מן הצפון</span> a. vice versa.] Cmp. <a href=\"#\" data-headword=\"אַיָּל\">אַיָּל</a>.</div>","alt":["אַיֶּילֶת"]},"1316":{"h":"אַיַּלְתָּא","r":"A01316","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>hind, roe</i>. <span class=\"citation\">Targ. Jer. XIV, 5</span>; a. e. <span class=\"citation\">Cant. R. to II, 9</span>; a. e.—<span dir=\"rtl\">א׳ דשחרא</span> (v. <a href=\"#\" data-headword=\"אַיָּלָה\">אַיָּלָה</a>) <i>morning dawn</i>. <span class=\"citation\">Y. Ber. I, 2ᶜ</span>; a. e.—Pl. <a href=\"#\" data-headword=\"אַיַּלְתָּא\">אַיָּילָתָא</a>, <span dir=\"rtl\">אַיָּילָאתָא</span>. <span class=\"citation\">Targ. Ps. XXIX, 9</span>; a. e.</div>","alt":["אַיַּילְתָּא","אֲיַלְתָּא"]},"1317":{"h":"אָיַם","r":"A01317","html":"<div class=\"sense\"> (√<a href=\"#\" data-headword=\"אוֹ I\">או</a>, v. <a href=\"#\" data-headword=\"אֵיבָה\">אֵיבָה</a>) <i>to feel aversion, fright</i>. Denomin. <a href=\"#\" data-headword=\"אֵימָה\">אֵימָה</a>.</div><div class=\"sense\"><b>Pi. אִיֵּים</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"אֵימָה\">אֵימָה</a>; with <span dir=\"rtl\">על</span>) <i>to impress with awe, forewarn</i> (witnesses). <span class=\"citation\">R. Hash. 20ᵃ</span> <span dir=\"rtl\">מְאַיְּימִין על העדים</span> we may try to intimidate &amp;c. <span class=\"citation\">Yoma 4ᵇ</span> <span dir=\"rtl\">לְאַיֵּים עליו</span> to impress him. <span class=\"citation\">Sot. I, 4</span>; a. e.</div></div>","alt":[]},"1318":{"h":"אֵימָא","r":"A01318","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אְמָא I\">אֲמָא</a></div>","alt":[]},"1319":{"h":"אימָּא I","r":"A01319","html":"<div class=\"sense\"><i>distaff</i>, v. <a href=\"#\" data-headword=\"אִימָּה II\"><span dir=\"rtl\">אִימָּה</span> II</a>.</div>","alt":[]},"1320":{"h":"אִימָּא II","r":"A01320","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אֵם\">אֵם</a>) </div><div class=\"sense\"><b>1)</b> <i>mother</i>, frequ. <i>my mother</i>; v. <a href=\"#\" data-headword=\"אַבָּא I\">אַבָּא</a>. <span class=\"citation\">Targ. Gen. III, 20</span>; a. fr.—<span class=\"citation\">Ber. 18ᵇ</span> <span dir=\"rtl\">אֵימא לה לא׳</span> tell my mother; a. fr.—א׳ זקינה <i>grandmother</i>. <span class=\"citation\">Meg. 27ᵇ</span></div><div class=\"sense\"><b>—2)</b>  trnsf. <i>the flesh of a stone fruit</i>. <span class=\"citation\">Sabb. 143ᵃ</span> <span dir=\"rtl\">חזיין אגב אִימָּן</span> may be handled on account of the flesh (with which they were surrounded when Sabbath cause).—Pl. <a href=\"#\" data-headword=\"אַמָּהָתָא\">אִימָּהָתָא</a>, <a href=\"#\" data-headword=\"אַמְהֲתָא\">אִמְהָתָא</a>. <span class=\"citation\">Targ. Jer. XVI, 3</span>; esp. <i>the arch-mothers</i> of the Israel. nation. <span class=\"citation\">Targ. Y. Ex. XVII, 9</span>; a. e.—<span class=\"citation\">Kidd. 82ᵃ</span> <span dir=\"rtl\">א׳ דינוקי</span> the mothers of school children. [V. also <a href=\"#\" data-headword=\"אִימָּה II\"><span dir=\"rtl\">אִימָּה</span> II</a>.]</div>","alt":["אִמָּא","אִימָּה"]},"1321":{"h":"אִימָּא III","r":"A01321","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"> [or <i>title;</i> cmp. <a href=\"#\" data-headword=\"אַבָּא I\">אַבָּא</a>]. <i>Imma</i>. <span class=\"citation\">Y. Git. I, 43ᶜ</span>; <span class=\"citation\">Shebi. VI, 36</span>ᶜ top <span dir=\"rtl\">א׳ שלום</span> Imma (Mother) Shalom.</div>","alt":[]},"1322":{"h":"אִימָּאוּס","r":"A01322","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִמָּאוּס\">אִמָּאוּס</a></div>","alt":[]},"1323":{"h":"אִימָּה I","r":"A01323","html":"<div class=\"sense\"><i>mother</i>, v. <a href=\"#\" data-headword=\"אִימָּא II\"><span dir=\"rtl\">אִימָּא</span> II</a>.</div>","alt":[]},"1324":{"h":"אִימָּה II","r":"A01324","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָמַם\">אמם</a>, √אם <i>to gather</i>; cmp. <a href=\"#\" data-headword=\"אוּמָּה\">אוּמָּה</a> a. <a href=\"#\" data-headword=\"עֲמַם I\">עמם</a> I in Ges. H. Dict.) <i>distaff.</i> <span class=\"citation\">Kel. XI, 6</span> (Ar. <a href=\"#\" data-headword=\"אֵימָא\">אימא</a>, Var. <a href=\"#\" data-headword=\"עִימָּא\">עִימָּא</a>).</div>","alt":[]},"1325":{"h":"אֵימָה","r":"A01325","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>fear, awe</i>. <span class=\"citation\">Num. R. s. 9</span>; <span class=\"citation\">Y. Sot. I, beg. 16ᵇ</span> <span dir=\"rtl\">אלא מתוך דבר של אמה</span> (read <a href=\"#\" data-headword=\"אִימָּה I\">אימה</a>) but from a solemn conversation (v., however, Maim. <span class=\"citation\">Sotah IV, 18</span> a. comment.). <span class=\"citation\">R. Hash. 17ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">אֵימוֹת</span>. <span class=\"citation\">Sabb. 77ᵇ</span> <span dir=\"rtl\">חמש א׳ הן</span> there are five sorts of fear. [Tanḥ. Tsav 2 <span dir=\"rtl\">(<span dir=\"rtl\">אימות</span>) <span dir=\"rtl\">אימת שירוף</span></span>, v. <a href=\"#\" data-headword=\"*אִימּוּס\">אִימּוּס</a>.]</div>","alt":[]},"1326":{"h":"אִימָּהוֹת","r":"A01326","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵם\">אֵם</a></div>","alt":[]},"1327":{"h":"אימהן","r":"A01327","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵימְתָן\">אֵימְתָן</a></div>","alt":[]},"1328":{"h":"אימולוגים","r":"A01328","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אוֹמוֹלוֹגְיָיא\">אומולוגייא</a></div>","alt":[]},"1329":{"h":"אִימּוּם","r":"A01329","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִמּוּם\">אִמּוּם</a>. [<span class=\"citation\">Tosef. Kidd. IV, 8</span> <span dir=\"rtl\">באימום</span> read <span dir=\"rtl\">בבִימוֹס</span>.]</div>","alt":[]},"1330":{"h":"אימונים","r":"A01330","html":"<div class=\"sense\"> <span class=\"citation\">Koh. R. to VII, 11</span>, v. <a href=\"#\" data-headword=\"אִמָּאוּס\">אִמָּאוּס</a></div>","alt":[]},"1331":{"h":"אימוס","r":"A01331","html":"<div class=\"sense\"> <span class=\"citation\">Sabb. 141ᵇ</span>, v. <a href=\"#\" data-headword=\"אִמּוּם\">אִמּוּם</a></div>","alt":[]},"1332":{"h":"*אִימּוּס","r":"A01332","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contr. of <a href=\"#\" data-headword=\"אִמָּאוּס\">אִמְאוּס</a> = <a href=\"#\" data-headword=\"מִיאוּס\">מִיאוּס</a>; <span dir=\"rtl\">מאס</span>) <i>disfiguration</i>. <span dir=\"rtl\">א׳ שירוף</span> <i>one disfigured by burns</i>. <span class=\"citation\">Cant. R. to VII, 9</span> <span dir=\"rtl\">ונעשה א׳ ש׳</span> and he (Nebucadn.) became &amp;c. [Tanḥ. Tsav. 2 (ed. Buber 3) <span dir=\"rtl\">ונעשה אֵימַת שירוף עליו</span> and the fright (repulsiveness) of a burned face was put upon him. <span class=\"citation\">Midr. Till. to Ps. XXII</span> <a href=\"#\" data-headword=\"*אמבירוס\">אמבירוס</a>, read <span dir=\"rtl\">אֶמְפּוּרוֹס</span>, ἔμπυρος, <i>fire-scathed</i>.]</div>","alt":[]},"1333":{"h":"אֵימוּר","r":"A01333","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲמַר\">אֲמַר</a></div>","alt":[]},"1334":{"h":"אֵימוּרִים","r":"A01334","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָמַר I\">אמר</a>, v. Ges. H. Dict. s. v.; cmp. <span class=\"citation\">Deut. XXVI, 17</span> sq.) <i>devoted objects, sacrifices</i>. <span class=\"citation\">Succ. 55ᵇ</span> <span dir=\"rtl\">אֲמוּרֵי הרגלים וכ׳</span> (Mish. <span class=\"citation\">ib.</span> <a href=\"#\" data-headword=\"אֵימְתָן\">אֵימ׳</a>) are not the festive Emurim (v. infra) the Lord’s, i.e. to be offered on the altar? Answ. <span dir=\"rtl\">מה שאמור ברגלים</span> <i>Emuré</i> &amp;c. means, whatever is consecrated as offering for festivals.—Esp. <i>Emurim, Emurin, those portions of sacrifices offered on the altar</i>. <span class=\"citation\">Pes. 71ᵃ</span> <span dir=\"rtl\">אֵימוּרֵי חגיגה וכ׳</span> the Emurim of the pilgrim’s feast offering. <span class=\"citation\">Zeb. II, 2</span>; a. fr.</div>","alt":["אֲמוּרִים","אֵימוּרִין I"]},"1335":{"h":"אֵימוּרִים ²","r":"A01335","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּר I\">מור</a>, <a href=\"#\" data-headword=\"יָמַר\">ימר</a>) <i>exchange</i> (cmp. <a href=\"#\" data-headword=\"חֲלִיפִים\">חליפין</a> as to pl.). <span dir=\"rtl\">בני א׳</span> <i>hostages</i> in place of their parents. <span class=\"citation\">Lam. R. to III, 13</span> ed. (Ar. <a href=\"#\" data-headword=\"*אִימְרָיָיא\">אימְרָיָיא</a> q. v.). V. also <a href=\"#\" data-headword=\"*אֲמוּרְיָא\">אֲמוּרְיָא</a>.</div>","alt":["אֵימוּרִין","אֲמוּ׳ II"]},"1336":{"h":"אֵימוּרִין","r":"A01336","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵימוּרִים ²\">preced. ws.</a></div>","alt":[]},"1337":{"h":"*אִימְּטִין","r":"A01337","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (= <span dir=\"rtl\">איתמ׳</span>, play on <a href=\"#\" data-headword=\"מִיטָּה\">מִיטָּה</a> and <a href=\"#\" data-headword=\"אֲמִיטְתָא\">אמיטתא</a>) <i>those who go to bed with the setting in of darkness</i> (a witty expression made up in oppos. to <span dir=\"rtl\">שיחרין</span>, v. <a href=\"#\" data-headword=\"שְׁחַר\">שְׁחַר</a>). <span class=\"citation\">Ex. R. s. 47</span> <span dir=\"rtl\">למדו תורה דא׳</span> learn the teachings of those who rested well by night (as better fitted to teach).</div>","alt":[]},"1338":{"h":"*אימיקנטרון","r":"A01338","html":"<div class=\"sense\"> <span class=\"citation\">Koh. R. to II, 17</span>, prob. a. corruption of <a href=\"#\" data-headword=\"מְקַטְרֵג\">מקטרג</a> <i>a malicious informer</i>.</div>","alt":["או׳"]},"1339":{"h":"*אִימִירָא","r":"A01339","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἡμέρα) <i>day</i>. <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> top, they lament over it <span dir=\"rtl\">מילני אי׳</span>, μέλαινα ἡμέρα, oh, the black (luckless) day! V. Macrob. Sat. I, 15 <i>dies atri</i></div>","alt":[]},"1340":{"h":"אִימִירוֹן","r":"A01340","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἥμερον, neut. or accus.) <i>tame, soft, gentle</i> (opp. <a href=\"#\" data-headword=\"אַגְרִיאוֹן\">אַגְרִיאוֹן</a> q. v.). <span class=\"citation\">Gen. R. s. 77</span> end <span dir=\"rtl\">נמירון</span> (corr. acc.). <span class=\"citation\">Num. R. s. 11</span>; Pesik. Haḥod. p. 44ᵇ <span dir=\"rtl\">אי מכון</span>; <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">אימרון</span>; <span class=\"citation\">Cant. R. to III, 7</span> <a href=\"#\" data-headword=\"אדיבון\">אדיבון</a> (corr. acc.). Midr. Sam. ch. XVII (for <a href=\"#\" data-headword=\"אַגְרִיאוֹן\">אגריון</a> read <a href=\"#\" data-headword=\"אִימִירוֹן\">אימירון</a>, for <span dir=\"rtl\">נימירון</span> read <a href=\"#\" data-headword=\"אַגְרִיאוֹן\">אגריון</a>).</div>","alt":[]},"1341":{"h":"*אִימְלָא","r":"A01341","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"מְעִיל\">מְעִיל</a>; contr. of <span dir=\"rtl\">אימעלא</span>; cmp. <a href=\"#\" data-headword=\"מִילְּתָא\">מִילְתָא</a>) <i>cloak.</i> Pl. <span dir=\"rtl\">אִימְלִין</span>. <span class=\"citation\">Targ. Ez. XXVII, 24</span>.</div>","alt":[]},"1342":{"h":"אִימָמָא","r":"A01342","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִי־\">אִי־</a>) <i>day time</i>. <span class=\"citation\">Y. Ber. III, 6ᵈ</span> top; a. e. <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> top <span dir=\"rtl\">א׳ ארך</span> the day growing longer.</div>","alt":[]},"1343":{"h":"אימן","r":"A01343","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Kel. B. Bath. II, 6</span> read <a href=\"#\" data-headword=\"אִימּוּם\">אִימּוּם</a>.</div>","alt":[]},"1344":{"h":"אִימֵּן","r":"A01344","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָמַן\">אָמַן</a></div>","alt":[]},"1345":{"h":"אִימְנוֹן = הִמְנוֹן","r":"A01345","html":"","alt":[]},"1346":{"h":"איממריי","r":"A01346","html":"<div class=\"sense\">, read <span dir=\"rtl\">אימריי׳</span>, v. <a href=\"#\" data-headword=\"אֵימוּרִים ²\"><span dir=\"rtl\">אֵימוּרִים</span> II</a> a. <a href=\"#\" data-headword=\"*אִימְרָיָיא\"><a href=\"#\" data-headword=\"*אִימְרָיָיא\">אִימְרָיָיא</a>.</a></div>","alt":[]},"1347":{"h":"אִימְצִי","r":"A01347","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְצִי I\">מְצִי</a></div>","alt":[]},"1348":{"h":"אֵימַר","r":"A01348","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אֵמֶר\">אֵמֶר</a>) <i>speech, utterance</i>. <span class=\"citation\">Targ. Num. XXIV, 3</span>; a. e.—Pl. <a href=\"#\" data-headword=\"אִימַר\">אִימְרַיָּא</a>. <span class=\"citation\">Targ. Prov. IV, 5</span> Ms. (ed. <span dir=\"rtl\">מַאֲמָרֵי</span>); a. e.</div>","alt":[]},"1349":{"h":"אִימַר","r":"A01349","html":"<div class=\"sense\"><i>to retract</i>, v. <a href=\"#\" data-headword=\"מרי I\">מרי</a> ch.</div>","alt":["אִימְרוּ","אִימרִיא","(אימראי)"]},"1350":{"h":"אִימַּר","r":"A01350","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָמַר I\">אמר</a>, √<span dir=\"rtl\">אם</span>, v. <a href=\"#\" data-headword=\"אָמַם\">אמם</a>; cmp. <span dir=\"rtl\">עמרא</span>, <a href=\"#\" data-headword=\"חוֹמְרָא\">חומרא</a>, <a href=\"#\" data-headword=\"צמר\">צמר</a>) </div><div class=\"sense\"><b>1)</b>  [<i>thick, heavy</i>,] <i>lamb</i>. <span class=\"citation\">Targ. Gen. XXX, 32</span>; a. fr.—<span class=\"citation\">Ned. I, 3</span> ‘this be as forbidden to me <span dir=\"rtl\">כאימרא</span> (Y. ib. I, end, 37ᵃ <span dir=\"rtl\">כאימרה</span>) as <i>the</i> lamb’—<span dir=\"rtl\">כאימר תמידא</span> that means, ‘as the lamb of the daily offering’. Lam. R. introd. (R. <span class=\"citation\">Josh. 2</span>) <span dir=\"rtl\">דהוה נכיס אמ׳ וכ׳</span> who slaughters a lamb and augurs from its liver. <span class=\"citation\">Erub. 53ᵇ</span> (deriding the Galilean dialect) a Galilean cried <span dir=\"rtl\">אמר למאן וכ׳</span> who wants <i>amar?</i> (indistinctly pronouncing the vowels, as well as the guttural sound of <a href=\"#\" data-headword=\"א\">א</a>), when they said to him …, <span dir=\"rtl\">חמר למירכב או חמר למשתי עמר למילבש או אימר לאיתכסאה</span> (for var. lect., v. Rabb. D. S. a. l. note 10) do you mean <i>ḥǎmâr</i> (an ass) to ride on, or <i>ḥămar</i> (wine) to drink, or <i>ãmar</i> (wool) for putting on, or <i>immar</i> (lamb) for slaughtering?; a. fr.—Pl. <a href=\"#\" data-headword=\"מְרַד\">אִימְּרִין</a>, <a href=\"#\" data-headword=\"אִימַר\">אִימְּרַיָּא</a>, <span dir=\"rtl\">אִימְּרַיָּיה</span>, <a href=\"#\" data-headword=\"מְצִי I\">אִמְּ׳</a>. <span class=\"citation\">Ezra VII, 9</span>; a. e.—<span class=\"citation\">Targ. Ex. XXIX, 38</span>; <span class=\"citation\">XII, 5</span>; a. e.—Y. Snh. I, 18ᵈ top <span dir=\"rtl\">אי׳ רכיכין</span> the lambs (of the spring) are yet tender (in a letter announcing the intercalation of a month); Bab. <span class=\"citation\">Snh. 11ᵇ</span> <span dir=\"rtl\">א׳ עדקין</span> (not <a href=\"#\" data-headword=\"עֵירוּבָא\">ער׳</a>; v. <span class=\"citation\">Tosef. ib. II, 6</span>); a. e.—Fem. <a href=\"#\" data-headword=\"אִימַּרְתָּא\">אִימַּרְתָּא</a> <i>ewe</i>. <span class=\"citation\">Targ. Lev. V, 6</span>; a. e.—<span class=\"citation\">Ḥull. 51ᵃ</span>. <span class=\"citation\">Gen. R. s. 44</span> end, the sow (Rome) pastures with twenty (young ones), <span dir=\"rtl\">וא׳ ולא בחד</span> and the ewe (Sarah) not even with one.—2) (cmp. <a href=\"#\" data-headword=\"חוּמְרָא I\">חוּמְרָא</a>) <i>knot, bandage</i> on wounds. <span class=\"citation\">Snh. 98ᵃ</span> כולהו שרי ואסרי אי׳ וכ׳ Ar. (in ed. a. Ms. our w. omitted) all of them untie their bandages all at once and tie them up all at once, but he attends to one at a time.</div><div class=\"sense\"><b>—3)</b> <i>fringe, border</i>. <span class=\"citation\">Targ. Ps. CXXXIII, 2</span>. <span class=\"citation\">Targ. Y. Ex. XXVI, 4</span> (Var. <span dir=\"rtl\">אֶימְרָא</span>). V. <a href=\"#\" data-headword=\"אִימְּרָה\">next w.</a></div><div class=\"sense\"><b>—4)</b> *  pr. n. pl. <a href=\"#\" data-headword=\"*איבּוּס\">כפר א׳</a> <i>K’far Imra</i> (Lamb-ville). <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> bot.; (<span class=\"citation\">Lam. R. to II, 2</span> <a href=\"#\" data-headword=\"נְמַר\">נמרא</a>).</div>","alt":["אִימְּרָא","אִמַּר","אִמְּרָא","(אִימְּרָה)"]},"1351":{"h":"אִימְּרָה","r":"A01351","html":"<div class=\"sense\"> h. f. (v. <a href=\"#\" data-headword=\"אִימַּר\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>fringe, border, skirt;</i> trnsf. <i>the bordered garment</i>, (toga prætexta), <i>state garment</i>. <span class=\"citation\">Taan. 11ᵇ</span>; <span class=\"citation\">Ab. Zar. 34ᵃ</span> <span dir=\"rtl\">חלוק לבן שאין בו אימרא</span> a white plain frock without border (without official distinction; cmp. toga pura). <span class=\"citation\">Y. Kil. IX, 32ᵃ</span> top; <span class=\"citation\">Tosef. ib. V, 19</span> <a href=\"#\" data-headword=\"א׳\">א׳</a> (<a href=\"#\" data-headword=\"ה\">ה</a>)<span dir=\"rtl\">מפורסמת</span> a conspicuous border garment. Y. Kidd. IV, beg. 65ᵇ (play on <a href=\"#\" data-headword=\"אָמַר I\">אִמֵּר</a> <span class=\"citation\">Ezra II, 59</span>) <span dir=\"rtl\">פירסמו וכ׳</span> they made themselves as conspicuous as the border on the frock. <span class=\"citation\">Sabb. 105ᵃ</span>; <span class=\"citation\">Tosef. ib. XII</span> (<span class=\"citation\">XIII), 1</span>.—<span class=\"citation\">Y. Yoma I, 38ᵈ</span> top; <span class=\"citation\">Y. Meg. I, 72ᵃ</span> bot. <span dir=\"rtl\">אִימְּרַת חלוקי</span> the skirt of my frock; a. fr.—[<span class=\"citation\">Lam. R. to II, 17</span> explain. <span dir=\"rtl\">אִמְרָתוֹ</span> ib., <span dir=\"rtl\">פורפירא</span>, v. <a href=\"#\" data-headword=\"בְּזַע\">בזע</a>.] Pl. (of <a href=\"#\" data-headword=\"אוּמְרִית\">אוּמְּרִית</a>) <span dir=\"rtl\">אוּמְרִיֹּות</span>. <span class=\"citation\">Neg. XI, 10</span>. <span class=\"citation\">Y. M. Kat. I, 80ᵈ</span> bot.; v. <a href=\"#\" data-headword=\"זָוַג\">זָוַג</a>.</div><div class=\"sense\"><b>—2)</b>  trnsf. <i>object of distinction, decoration</i> (play on <a href=\"#\" data-headword=\"אֲמִירָה II\"><span dir=\"rtl\">אֲמִירָה</span> II</a>); cmp. <a href=\"#\" data-headword=\"חֲטִיבָה I\">חְטִיבָה</a>. Mekh. B’shall., Shirah, s. 3 (ref. to <span dir=\"rtl\">האמר־</span> <span class=\"citation\">Deut. XXVI, 17</span>) <span dir=\"rtl\">עשאני וכ׳</span> He made me (His) decoration (chosen people) &amp;c.; <span class=\"citation\">Yalk. Ex. 244</span> <a href=\"#\" data-headword=\"אֲמִירָה I\">אְמִירָה</a>.</div>","alt":["(אִימְּרָא)"]},"1352":{"h":"*אִימְרָיָיא","r":"A01352","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מרי I\">מרי</a>, v. <a href=\"#\" data-headword=\"*אִימְרָנָא\">next w.</a>) <i>rebellion</i>. <span class=\"citation\">Lam. R. to III, 13</span> (rendering <span dir=\"rtl\">בני אשפתו</span> ibid. ‘the children of those thrown down’ (into the dung, conquered), Rab explains ‘the children of his destruction’ (v. <a href=\"#\" data-headword=\"אוֹפִיכָא\">אוֹפִיכָא</a>), <span dir=\"rtl\">בני אִימְרָיֵיה</span> the children of rebellion against him. (Editions vary, <span dir=\"rtl\">אימריה</span>, <span dir=\"rtl\">רייא …</span>, <span dir=\"rtl\">אמורים</span> &amp;c., v. <a href=\"#\" data-headword=\"אֵימוּרִים ²\"><span dir=\"rtl\">אֵימוּרִים</span> II</a>). [<span class=\"citation\">Esth. R. to I, 1</span>ᵇ, independently interpreted, v. <a href=\"#\" data-headword=\"*אוּכַּיְיפָא\">אוּכַּיְיפָא</a> a. <a href=\"#\" data-headword=\"*אֲמוּרְיָא\">אֲמוּרְיָא</a>.]</div>","alt":[]},"1353":{"h":"*אִימְרָנָא","r":"A01353","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"מָרוֹן I\">מָרוֹן</a>; v. <a href=\"#\" data-headword=\"אִימַר\">אִימַר</a> a. <a href=\"#\" data-headword=\"*אִימְרָיָיא\">preced.</a>) <i>rebellion</i>. <span dir=\"rtl\">בני א׳</span> <i>rebels</i>. <span class=\"citation\">R. Hash. 18ᵃ</span> (translating <span dir=\"rtl\">בני מרון</span> Mish.) (all creatures pass before the Lord for receiving their decrees) <span dir=\"rtl\">כבני א׳</span> like rebels (after surrender brought before a court martial; cmp. <span class=\"citation\">Midr. Till. to Ps. XVII, 1</span>, s. v. <a href=\"#\" data-headword=\"אַפֹּופְסִין\">אפופסין</a>, a. <span class=\"citation\">Y. R. Hash. I, 57ᵇ</span>). [Rashi <span dir=\"rtl\">אמרנא</span> = Syr. <span dir=\"rtl\">אֵמרונא</span> ‘like young lambs passing singly to be marked for tithes’.]</div>","alt":[]},"1354":{"h":"אִימַּרְתָּא","r":"A01354","html":"<div class=\"sense\"><b>1)</b> <i>ewe</i>, v. <a href=\"#\" data-headword=\"אִימַּר\">אִימַּר</a>.</div><div class=\"sense\"><b>—2)</b>  pr. n. f. <i>Immarta</i>. <span class=\"citation\">Snh. 52ᵇ</span> Im. daughter of Tali (prob. pseudonyms).</div>","alt":[]},"1355":{"h":"אֵימָת","r":"A01355","html":"<div class=\"sense\"><i>when?</i> <span class=\"citation\">Ḥull. 17ᵃ</span>.—<span class=\"citation\">Ber. I, 1</span>, a. fr. <span dir=\"rtl\">מאימתי</span> from what time (of the day)? <span class=\"citation\">Shebi. I, 1</span>, a. fr. <span dir=\"rtl\">עד אימתי</span>; <span class=\"citation\">ib. II, 1</span> <span dir=\"rtl\">עד אימת</span> how long (until when)?</div>","alt":["אֵימָתַי"]},"1356":{"h":"אֵימַת","r":"A01356","html":"<div class=\"sense\"><b>1)</b> <i>whenever, when</i>. <span class=\"citation\">Targ. Y. Lev. XXIII, 42</span>; a. e. Y. B. Kam. III, 3ᵈ top <span dir=\"rtl\">אי׳ דמתיבון וכ׳</span> when they quote the Mishnah in support of &amp;c. <span class=\"citation\">Ab. Zar. 53ᵇ</span> <span dir=\"rtl\">כל אי׳ דבעינא לה</span> whenever I desire it. <span class=\"citation\">Nidd. 66ᵃ</span></div><div class=\"sense\"><b>—2)</b>  also (<a href=\"#\" data-headword=\"אֵימָתַי\">אִימַתִּי</a>) <a href=\"#\" data-headword=\"אֵימָתַי\">אֵימָתַי</a> <i>when?</i> <span class=\"citation\">Targ. Job. VII, 4</span>.—לא׳ <i>for what time? until what time?</i> <span class=\"citation\">Targ. O. Ex. VIII, 5</span>; a. e.</div>","alt":[]},"1357":{"h":"אֵימְתָא","r":"A01357","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"אֵימָה\">אֵימָה</a>. <span class=\"citation\">Targ. O. Ex. XV, 16</span>; a. e.—<span class=\"citation\">B. Kam. 28ᵃ</span>; a. e.</div>","alt":[]},"1358":{"h":"אֵימָתַי","r":"A01358","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵימָת\">אֵימָת</a>, <a href=\"#\" data-headword=\"אֵימַת\"><a href=\"#\" data-headword=\"אֵימַת\">אֵימַת</a>.</a></div>","alt":["אִימַתִּי"]},"1359":{"h":"אֵימְתָן","r":"A01359","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"אֵימְתָא\">אימתא</a>) </div><div class=\"sense\"><b>1)</b> <i>fear-inspiring, powerful</i>. <span class=\"citation\">Targ. Jud. III, 30</span>.—Pl. <span dir=\"rtl\">אֵימְתָנִין</span>, <span dir=\"rtl\">אֵימְתָנֵי</span>, <a href=\"#\" data-headword=\"אֵימְתָן\">אֵימָ׳</a>. Targ. Ḥab. I, 7. <span class=\"citation\">Targ. Gen. XIV, 5</span> (Y. II, <span dir=\"rtl\">אמתניא</span>, h. text <span dir=\"rtl\">אֵימִים</span>).</div><div class=\"sense\"><b>—2)</b> <i>timid</i>. <span class=\"citation\">Y. Meg. III, 74ᵃ</span> bot. <span dir=\"rtl\">ספרא הוה אימתן וכ׳</span> (ed. Krot. <a href=\"#\" data-headword=\"אימהן\">אימהן</a>, corr. acc.) the school-master was a timid man and but for R. Abbahu that passed by, he would not have cleared the children out of the premises of the Synagogue. [Hebr. form, v. <a href=\"#\" data-headword=\"אֵמְתָן\">אֵמְתָן</a>.]</div>","alt":["אֵימִתָנָא","אֵימָ׳"]},"1360":{"h":"אָיַן","r":"A01360","html":"<div class=\"sense\">, <i>Pi</i>. <a href=\"#\" data-headword=\"אִיֵּין\">אִיֵּין</a> (= <a href=\"#\" data-headword=\"עִיֵּין\">עִיֵּין</a>, v. <a href=\"#\" data-headword=\"אַיִן I\">next w.</a>) <i>to look upon, investigate</i>. <span class=\"citation\">B. Bath. 115ᵃ</span> (play on <a href=\"#\" data-headword=\"אִין I\">אִין</a>) <span dir=\"rtl\">אַיֵּין עליו</span> Ar. (ed. <a href=\"#\" data-headword=\"עִיֵּין\">עַיֵּין</a>) investigate his family relations. <span class=\"citation\">Kidd. 4ᵃ</span></div>","alt":[]},"1361":{"h":"אַיִן I","r":"A01361","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (√<a href=\"#\" data-headword=\"אוֹ I\">או</a>; cmp. <a href=\"#\" data-headword=\"אָוֶן\">אָוֶן</a>, <a href=\"#\" data-headword=\"עַיִן\">עַיִן</a>) [b. h. <i>naught</i>], <i>something rounded, decorative</i>. <span class=\"citation\">Koh. R. to III, 12</span> expl. as <a href=\"#\" data-headword=\"נוֹי\">נוֹי</a>, ref. to the shape of the human buttock, v. <a href=\"#\" data-headword=\"*אֱפִיפְּיוֹן\">אֱפִיפְּיוֹן</a>.</div>","alt":[]},"1362":{"h":"אַיִן II","r":"A01362","html":"<div class=\"sense\"><i>where?</i> (only with pref. <a href=\"#\" data-headword=\"מ\">מ</a> or <a href=\"#\" data-headword=\"ל\">ל</a>). <span dir=\"rtl\">לְאַ׳</span> <i>whither?</i> מֵאַ׳ <i>whence</i>? <span class=\"citation\">Y. Snh. X, 28ᵈ</span> bot; <span class=\"citation\">Y. Ḥag. II, 77ᵃ</span> bot. <span dir=\"rtl\">מא׳ ולא׳</span> whence and whither?—<span class=\"citation\">Aboth III, 1</span>. <span class=\"citation\">Gen. R. s. 2</span> <span dir=\"rtl\">מא׳ הרגלים</span> whence art thou coming? i.e. where hast thou been staying?—<span class=\"citation\">Y. Snh. X, 28ᵇ</span> top <span dir=\"rtl\">היה לו מא׳ ללמוד</span> he had (a precedent) to learn from.—Contr. of <span dir=\"rtl\">מן אין</span>: <a href=\"#\" data-headword=\"מִנַּיִן\">מִנַיִן</a>, v. <a href=\"#\" data-headword=\"מִן\">מִן</a>.</div>","alt":["אַיִין"]},"1363":{"h":"אֵין","r":"A01363","html":"<div class=\"sense\"><i>nothing, not</i>. <span class=\"citation\">Ber. 5ᵃ</span> אין עוף אלא וכ׳ <i>uf</i> (flight, <span class=\"citation\">Job V, 7</span>) means nothing else but &amp;c.; a. v. fr.—<a href=\"#\" data-headword=\"אֵינִי\">אֵינִי</a>, <span dir=\"rtl\">אֵינְךָ</span> <i>not I</i> &amp;c. <span dir=\"rtl\">אֵינִי יודע</span> I do not know; do I not know? <span class=\"citation\">B. Mets. 97ᵇ</span>; a. fr. Ber. l. c. but the Holy One … <span dir=\"rtl\">אֵינוֹ כן</span> is not so; a. fr.—<span dir=\"rtl\">אֵינוֹ דין</span> is it not a legitimate conclusion?, whence <i>so much the more</i>. <span class=\"citation\">Y. Naz. VI, 55ᵃ</span>; a. v. fr.—… <span dir=\"rtl\">אין לי אלא … מניין</span> from this I could only prove …, whence, however, will you deduct …? <span class=\"citation\">Ḥull. 65ᵇ</span>; a. fr. [<span class=\"citation\">Y. Git. IX, end, 50ᵈ</span> <span dir=\"rtl\">אפי׳ כתב אינו</span> read <span dir=\"rtl\">סימנו</span>.]</div>","alt":[]},"1364":{"h":"אִין I","r":"A01364","html":"<div class=\"sense\"> (Syr. = <a href=\"#\" data-headword=\"הֵין\">הֵין</a>, <span dir=\"rtl\">הֶן</span>) <i>yes, indeed</i>. <span class=\"citation\">Keth. 65ᵃ</span> <span dir=\"rtl\">השתא א׳ וכ׳</span> now,—yes, but not before. <span class=\"citation\">B. Mets. 98ᵃ</span> <span dir=\"rtl\">חדא א׳ בעידן וכ׳</span> as regards the one (cow)—well, she died &amp;c.; a. fr.—<a href=\"#\" data-headword=\"אֵינִי\">אֵינִי</a> = <a href=\"#\" data-headword=\"אִינְהוּ\">אִין הִי</a> <i>is it really so? indeed?</i>, i.e. it cannot be. <span class=\"citation\">Ḥull. 96ᵇ</span> <span dir=\"rtl\">א׳ והאמר</span> it cannot be so; for did not R. … say &amp;c.? <span class=\"citation\">M. Kat. 20ᵃ</span>; a. v. fr.</div>","alt":["אֵין"]},"1365":{"h":"אִין II","r":"A01365","html":"<div class=\"sense\"><b>1)</b> <i>if, whether</i>. <span class=\"citation\">Targ. Ps. VII, 4</span>; a. e. [Apocopated: <a href=\"#\" data-headword=\"אִי IV\">אִי</a> q. v.]—<span dir=\"rtl\">אין תימר</span> (h. <span dir=\"rtl\">אם תאמר</span>) if thou wilt say (argue). Y. Macc. II, 31ᵈ bot.; a. fr.—<span dir=\"rtl\">אין כיני</span> (h. <span dir=\"rtl\">אם כן היא</span>) if this is (be) the case. <span class=\"citation\">Y. Naz. VI, 54ᵈ</span> bot.—Lam. R. introd. end <span dir=\"rtl\">אן את יתיב וכ׳</span> if thou remainest here, or &amp;c. <span class=\"citation\">Koh. R. to X, 5</span> <span dir=\"rtl\">אן אתת ענתה וכ׳</span></div><div class=\"sense\"><b>—2)</b>  adv. of interrogation, introducing the alternative, <i>or</i>. <span class=\"citation\">Targ. Job VI, 6</span>; a. e.</div>","alt":["אֶן"]},"1366":{"h":"אִינָא","r":"A01366","html":"<div class=\"sense\"> c. (cmp. <span dir=\"rtl\">אִינְחוּ</span>), followed by <span dir=\"rtl\">ד־</span>, <i>he who</i>. <span class=\"citation\">Targ. Prov. XI, 26</span>; a. e. (also <a href=\"#\" data-headword=\"אִנָּא\">אִנָא</a> ed.).</div>","alt":[]},"1367":{"h":"אֵינָב","r":"A01367","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= b. h. <a href=\"#\" data-headword=\"עֵנָב\">עֵנָב</a> q. v.) <i>berry, an excrescence on the eye</i>. <span class=\"citation\">Tosef. Bekh. IV, 2</span>. [Mish. <span class=\"citation\">ib. VI, 2</span> <a href=\"#\" data-headword=\"עֵינָב\">עֵינָב</a>. Talm. ed. 38ᵃ; 38ᵇ <span dir=\"rtl\">עצב</span> (corr. acc.).]</div>","alt":[]},"1368":{"h":"אִינְבָּא","r":"A01368","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִנְבָּא I\">אִנְבָּא</a></div>","alt":[]},"1369":{"h":"אִינְגַּד","r":"A01369","html":"<div class=\"sense\"><i>prolong! go further!</i> <span class=\"citation\">Git. 58ᵃ</span> <span dir=\"rtl\">א׳ פוסתא וכ׳</span> go one page and a half further, (and you will find it). [Rashi: <i>a little</i> = <a href=\"#\" data-headword=\"אִינְגַּד\">אִי־נְגַד</a>, v. <span dir=\"rtl\">אי III</span>.]</div>","alt":["*(נגד)"]},"1370":{"h":"אינגורין","r":"A01370","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶנִּיגָרוֹן\">אֶנִּיגָרוֹן</a></div>","alt":[]},"1371":{"h":"אִינְדְּרָא","r":"A01371","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = next w.—<i>Pl.</i> with suffix of third pers. sing. <span dir=\"rtl\">אִינְדְּרוֹי</span>. <span class=\"citation\">Targ. Ps. CIV, 3</span> Ms. (ed. <span dir=\"rtl\">אכסדרוי</span>). [The verse is variously corrupted and defective.]</div>","alt":[]},"1372":{"h":"אִינְדְּרוֹנָא","r":"A01372","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִידְּרוֹן\">אִידְּרוֹן</a></div>","alt":[]},"1373":{"h":"אינדרטין","r":"A01373","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַנְדְּרוֹנִיטִין\">אַנְדְּרוֹנִיטִיס</a></div>","alt":[]},"1374":{"h":"אִינְהוּ","r":"A01374","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיהוּ\">אִיהוּ</a></div>","alt":["אִינְהִי"]},"1375":{"h":"אינו","r":"A01375","html":"<div class=\"sense\"> <span class=\"citation\">Y. Git. IX, end, 50ᵈ</span> <span dir=\"rtl\">אפי׳ כתב א׳</span>, read <span dir=\"rtl\">סִימָנוֹ</span>, v. Bab. <span class=\"citation\">Git. 87ᵇ</span></div>","alt":[]},"1376":{"h":"אִינוֹמִילִין","r":"A01376","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (οἰνόμελι) <i>wine mixed with honey</i>. <span class=\"citation\">Sabb. XX, 2</span> (<span class=\"citation\">139ᵇ</span>) <a href=\"#\" data-headword=\"אִסְקְרִיטִין\">אי׳</a> Ar. (ed. <span dir=\"rtl\">אנ׳</span>, var. in Mss. <span dir=\"rtl\">יינמילין</span>, <span dir=\"rtl\">ינמי׳</span>, v. Rabb. D. S. a. l. note 20). <span class=\"citation\">Ab. Zar. 30ᵃ</span> defined as a mixture of wine, honey and pepper. <span class=\"citation\">Ter. XI, 1</span> יינומלין Ar. (ed. <a href=\"#\" data-headword=\"יִינוֹמְלִים\">יינומלים</a>; Ms. M. <span dir=\"rtl\">אט׳</span>, read <span dir=\"rtl\">אינו׳</span>). <span class=\"citation\">Y. Sabb. XIV, 14ᶜ</span> top <span dir=\"rtl\">יינומילין</span>.</div>","alt":["(אִינוֹמְלִין","יִינוֹ׳)"]},"1377":{"h":"אִינוּן","r":"A01377","html":"<div class=\"sense\"> pl. of <a href=\"#\" data-headword=\"אִיהוּ\">אִיהוּ</a>, <a href=\"#\" data-headword=\"אִיהִי I\">אִיהִי</a>.</div>","alt":["אִינִין"]},"1378":{"h":"*אינוניתא","r":"A01378","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 29</span> <span dir=\"rtl\">ר׳ חנינא א׳</span>, a corruption of <a href=\"#\" data-headword=\"אִינְיָינִי\">אינייני</a> or <span dir=\"rtl\">אנינייא</span>, dialect. = <a href=\"#\" data-headword=\"חֲנִינָא\">חנינא</a>; cmp. Frankel M’bo p. 64ᵇ <span dir=\"rtl\">א׳ בן סוסיי</span> with p. 88ᵃ <span dir=\"rtl\">ח׳ בר סיסיי</span>. [Our w. omitted in <span class=\"citation\">Yalk. Gen. 47</span>, Job 908.]</div>","alt":[]},"1379":{"h":"*אִינַחְתָּא","r":"A01379","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">אנח</span>) <i>sigh, grief</i>. Targ. II Esth. III, 3.  v. <a href=\"#\" data-headword=\"אַנְחָתָא\">אַנְחָתָא</a>.</div>","alt":[]},"1380":{"h":"אינטפלינית","r":"A01380","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Kil. V, 25</span>, read with ed. Zuck. <a href=\"#\" data-headword=\"אִיסְפְּלִידָא\">אִיסְפְּלָנִית</a>.</div>","alt":["איינ׳"]},"1381":{"h":"אֵינִי","r":"A01381","html":"<div class=\"sense\"><b>1)</b>  = 1) = <span dir=\"rtl\">אֵין אֲנִי</span>, v. <a href=\"#\" data-headword=\"אֵין\">אֵין</a></div><div class=\"sense\"><b>—2)</b>  <a href=\"#\" data-headword=\"אִינְהוּ\">אִין הִי</a>, v. <a href=\"#\" data-headword=\"אִין I\"><span dir=\"rtl\">אִין</span> I</a></div>","alt":[]},"1382":{"h":"אִינִי","r":"A01382","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ini</i>, an Amora; cmp. <a href=\"#\" data-headword=\"אִינְיָינִי\">אִינְיָינִי</a>. <span class=\"citation\">Cant. R. to VIII, 11</span>. [<span class=\"citation\">Koh. R. to IX, 10</span> <span dir=\"rtl\">איבו</span>.]</div>","alt":[]},"1383":{"h":"איניבא","r":"A01383","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִנְבָּא I\">אִנְבָּא</a></div>","alt":[]},"1384":{"h":"אִינְיָיא","r":"A01384","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אִינִי\">אִינִי</a>) <i>Inya</i>. <span class=\"citation\">Y. Git. I, 43ᵈ</span> (Y. B. Bath. 16ᶜ <span dir=\"rtl\">חייה</span>). V. <a href=\"#\" data-headword=\"אִינְיָינִי\">next w.</a></div>","alt":[]},"1385":{"h":"אִינְיָינִי","r":"A01385","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Inyani</i>, an Amora. <span class=\"citation\">Y. Yoma III, 40ᶜ</span>; a. e. Y. [<span class=\"citation\">Maas. Sh. IV</span>, 55ᵃ bot. <a href=\"#\" data-headword=\"אִינְיָיא\">אינייא</a>, seems to be a different person, v. <a href=\"#\" data-headword=\"אִינְיָיא\">preced. w.</a> a. Frankel M’bo p. 64ᵇ.] V. <a href=\"#\" data-headword=\"*אינוניתא\">אינוניתא</a>.</div>","alt":["אִנְיָנִי","(אִינִינְיָיא)"]},"1386":{"h":"אִינִין","r":"A01386","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִינוּן\">אִינוּן</a></div>","alt":[]},"1387":{"h":"אִינִישׁ","r":"A01387","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֱינָשׁ\">אֱינָשׁ</a></div>","alt":[]},"1388":{"h":"אִינָךְ","r":"A01388","html":"<div class=\"sense\"><b>1)</b> <i>those</i>, v. <a href=\"#\" data-headword=\"אִיהוּ\">אִיהוּ</a>.</div><div class=\"sense\"><b>—2)</b> <i>onyx</i>, v. <a href=\"#\" data-headword=\"אָנָךְ\">אָנָךְ</a>.</div>","alt":[]},"1389":{"h":"אֶינְמִירִינוֹן","r":"A01389","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a contraction of ἔλαιον μύῤῥινον; cmp. <a href=\"#\" data-headword=\"אניגרון\">אניגרון</a> as to <a href=\"#\" data-headword=\"נ\">נ</a> for <a href=\"#\" data-headword=\"ל\">ל</a>) <i>unguent scentedwith Arabian myrtle</i>. <span class=\"citation\">Cant. R. to IV, 14</span>. [Muss. οἶνος μυρίνης; but the context requires an unguent.]</div>","alt":["אֶינְמְרִנוֹן"]},"1390":{"h":"אִינְפֹּולַי","r":"A01390","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַמְפְּלַי\">אֲמַפְּלַי</a></div>","alt":[]},"1391":{"h":"אִינְקָא","r":"A01391","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ינק</span>) <i>suckling</i> (infant or animal); cmp. <a href=\"#\" data-headword=\"יַנְקָא I\">יַנְקָא</a>. Targ. II Esth. I, 2 <span dir=\"rtl\">א׳ די דהבא</span> a suckling (kid?) of gold (lying, on the third step, opposite <a href=\"#\" data-headword=\"נְמַר\">נמרא</a> [not <a href=\"#\" data-headword=\"נְשַׁר II\">נשרא</a>] the panther; ref. to <span class=\"citation\">Is. XI, 6</span>). Pl. <span dir=\"rtl\">(<span dir=\"rtl\">אֶנְקִין</span>) <span dir=\"rtl\">אֱנָקִין</span></span>. Ib. (end) <span dir=\"rtl\">א׳ בכיין</span> the sucklings were crying.</div>","alt":[]},"1392":{"h":"אִינְקוֹרָא","r":"A01392","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָקַר I\">נקר</a>) <i>a bird with traces of bites or wounds on its legs;</i> [<i>black bird with white spots on its head</i>, quot. in Rashi; to be read <span dir=\"rtl\">אינקודי</span>?].—Pl. <a href=\"#\" data-headword=\"אִינְקוֹרָא\">אִינְקוֹרֵי</a>, <span dir=\"rtl\">אִנְ׳</span>. <span class=\"citation\">Ḥull. 57ᵃ</span></div>","alt":["אִנְקוֹרָא"]},"1393":{"h":"אינקלסיא","r":"A01393","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶנְקְלַסְיָא\">אנקלסיא</a></div>","alt":[]},"1394":{"h":"אֱינָשׁ","r":"A01394","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אנש</span>, sec. r. of <a href=\"#\" data-headword=\"אוּשׁ I\">אוּשׁ</a>; h. <i>being</i>, esp. <i>human being</i> <span class=\"citation\">Dan. II, 10</span>, a. fr. <span dir=\"rtl\">אנש</span>.—<span class=\"citation\">Ib. VII, 13</span> <a href=\"#\" data-headword=\"אמוראי\">בר א׳</a> son of man (in Talm. freq. <span dir=\"rtl\">בר נש</span>). <span class=\"citation\">Targ. O. Lev. XIII, 2</span>; a. fr.—<span class=\"citation\">Y. Snh. VIII, 25ᵃ</span> bot., a. fr. <span dir=\"rtl\">כאי׳ דמר</span> as if one says. <span class=\"citation\">Y. Ber. VIII, 12ᵃ</span> bot. <span dir=\"rtl\">אֲנָשָׁא רבא</span> a great man. <span class=\"citation\">Shebu. 22ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">אֵינָשִׁין</span>, const. <a href=\"#\" data-headword=\"נְשֵׁי\">אֵינָשֵׁי</a>. <span class=\"citation\">Targ. O. Gen. VI, 4</span>; a. e.—<span dir=\"rtl\">אִינְשִׁין</span>, <a href=\"#\" data-headword=\"נְשֵׁי\">אִינְשֵׁי</a>. Targ. Y. ibid.; a. e.—In Talm. mostly <a href=\"#\" data-headword=\"נְשֵׁי\">אִינְשֵׁי</a> <i>people</i>. <span class=\"citation\">B. Kam. 92ᵇ</span> <span dir=\"rtl\">אמרי א׳</span> (text <span dir=\"rtl\">רבנן</span>, corr. acc.). <span class=\"citation\">Snh. 95ᵇ</span> <span dir=\"rtl\">היינו דאמרי א׳</span> (abbr. <span dir=\"rtl\">ה&quot;דא&quot;א</span>) this is what people say, it is a common saying (proverb). <span class=\"citation\">Ibid. 103ᵃ</span>; a. v. fr.—<span class=\"citation\">Git. 45ᵃ</span> <span dir=\"rtl\">אִינְשִׁין</span> (our people?).</div>","alt":["אֵינָשׁ) אִינְשָׁא","(אֵינָשָׁא","אִינִישׁ","אֱנַשׁ"]},"1395":{"h":"אינתימרוס","r":"A01395","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> prob. a corrupt. for <a href=\"#\" data-headword=\"אנטיפטרוס\">אַנְטִיפַּטְרוֹס</a> <i>Antipater</i>. Targ. II, <span class=\"citation\">Esth. III, 1</span>.</div>","alt":["אנת׳"]},"1396":{"h":"אִיס־","r":"A01396","html":"<div class=\"sense\"> a prefix for the formation of (verbal) nouns (Ispeel nouns), affecting the first radical in the same way as the prefix of the Hithpa. or Ithpe.; e.g. from <span dir=\"rtl\">סגי</span>, <a href=\"#\" data-headword=\"אִסְטַגְיוֹת\">אִסְטַגְיוֹת</a> (pl.) <i>rims;</i> from <a href=\"#\" data-headword=\"סוּר I\">סוַר</a> = <a href=\"#\" data-headword=\"שִׁיר I\">שור</a> <i>to walk, stride</i>, <a href=\"#\" data-headword=\"אִיסְתְּוָורָא\">אִיסְתְּוָורָא</a> <i>ankle</i>, &amp;c. Before dentals <span dir=\"rtl\">איס</span> and <a href=\"#\" data-headword=\"אס\">אס</a> interchange with <span dir=\"rtl\">אִיצְ־</span> and <span dir=\"rtl\">אִצְ־</span>. [Words not found under <span dir=\"rtl\">איס־</span> must be looked for under <a href=\"#\" data-headword=\"אִס־\">אִס־</a> and <i>vice versa</i>.]</div>","alt":["אִס־"]},"1397":{"h":"אִיס","r":"A01397","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (υἱός) <i>son</i>. <span class=\"citation\">Ex. R. s. 15</span>, v. <a href=\"#\" data-headword=\"*אִילִיאוֹס\">אִילִיאוֹס</a>.</div>","alt":["*(אס)"]},"1398":{"h":"אִיסָא","r":"A01398","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Isa</i>, an Amora, disciple of R. Yoḥanan. <span class=\"citation\">Y. Ter. I, 40ᶜ</span> top. V. <a href=\"#\" data-headword=\"אִיסִי\">אִיסִי</a>.</div>","alt":[]},"1399":{"h":"איסגנטירין","r":"A01399","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אסגינטרין\">אסגנטירין</a></div>","alt":["איסגינטרין"]},"1400":{"h":"אִיסָדָא","r":"A01400","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סַדָּא\">סדא</a>, <a href=\"#\" data-headword=\"סַדְיָא\"><a href=\"#\" data-headword=\"סַדְיָא\">סדיא</a>)</a><i>head-side, pillow</i>. <span class=\"citation\">Targ. Gen. XXVIII, 11</span>; a. e.—<span class=\"citation\">Ber. 56ᵃ</span> <span dir=\"rtl\">אאיסדָן</span> by our head-side.—[<span class=\"citation\">Ib.</span> <span dir=\"rtl\">בי סדיא</span> <i>pillow</i>.]</div>","alt":[]},"1401":{"h":"אֵיסוּ","r":"A01401","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"אָסוּ\">אָסוּ</a>.</div>","alt":[]},"1402":{"h":"אִיסוֹדָא","r":"A01402","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">אֵיסוֹדֵי</span> m. = <a href=\"#\" data-headword=\"יְסוֹדָא\">יְסוֹדָא</a>. <span class=\"citation\">Targ. O. Num. V, 17</span> ed. Berl.</div>","alt":["אִסוֹדָא"]},"1403":{"h":"אִיסוֹפֹּולִיטְיָיא","r":"A01403","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἰσοπολιτεία) <i>civic rights granted to strangers, isopolity</i> (v. Sm. Ant. s. v. Civitas). <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">עבדות וגרות בארץ לא להם וענו אותם ארבע מאות שנה אפילו</span> [<span dir=\"rtl\">על</span>] <span dir=\"rtl\">א׳ שלהם</span> Ar. s. v. <a href=\"#\" data-headword=\"פְּלַטְיָא I\">פלטיא</a> II (ed. <span dir=\"rtl\">איספטלים</span>, <span dir=\"rtl\">איספטליס</span>, corr. acc.) ‘slavery and stranger’s condition’ (indicated <span class=\"citation\">Gen. XV, 13</span>) were in a land not theirs (in Egypt), but, ‘and they shall afflict them four hundred years’ refers even to their isopolity (in Canaan, from the birth of Isaac); <span class=\"citation\">Cant. R. to II, 17</span> <span dir=\"rtl\">באיספטלייה …</span> (corr. as above.). <span class=\"citation\">Gen. R. s. 44</span>; <span class=\"citation\">Yalk. Gen. 77</span> <span dir=\"rtl\">לאספטיא …</span> (corr. as above.). Pesik. Haḥod. p. 47ᵇ note 96.</div>","alt":["*(אספלטייא)"]},"1404":{"h":"אֵיסוּר","r":"A01404","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אסר</span>) </div><div class=\"sense\"><b>1)</b> <i>imprisonment</i>. <span class=\"citation\">Ber. 28ᵇ</span> <span dir=\"rtl\">אין אֵיסוּרוֹ א׳ עולם</span> the imprisonment which he decrees is not everlasting (as he may die and his successor may relieve me). </div><div class=\"sense\"><b>2)</b> * (= <a href=\"#\" data-headword=\"אָסִיר\">אָסִיר</a>), pl. <a href=\"#\" data-headword=\"אֵימוּרִין\">אֵיסוּרִין</a> <i>prisoners</i>. <span class=\"citation\">Ex. R. s. 30</span> he burst the prison open <span dir=\"rtl\">והוציא האיסו׳</span> (ib. also <span dir=\"rtl\">האֵיסָרִין</span>) and set the prisoners free [prob. to be read <span dir=\"rtl\">אסירין</span>].</div>","alt":[]},"1405":{"h":"אִיסּוּר I","r":"A01405","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Issur;</i> </div><div class=\"sense\"><b>1)</b>  a proselyte. <span class=\"citation\">Ab. Zar. 70ᵃ</span>. <span class=\"citation\">B. Bath. 149ᵃ</span></div><div class=\"sense\"><b>—2)</b>  an expert on coins. <span class=\"citation\">B. Kam. 99ᵇ</span> bot.</div>","alt":[]},"1406":{"h":"אִיסּוּר II","r":"A01406","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אסר</span>; cmp. b. h. <a href=\"#\" data-headword=\"אֵיסוּר\">אֵסוּר</a>, a. <a href=\"#\" data-headword=\"אֵיסוּר\">אֵיסוּר</a>) </div><div class=\"sense\"><b>1)</b> <i>band, chain;</i> trnsf. <i>social circle</i>. <span class=\"citation\">Succ. 45ᵇ</span> (ref. to <span class=\"citation\">Ps. CXVIII, 27</span>) <span dir=\"rtl\">כל העושה א׳ לחג וכ׳</span> he who creates a circle for the festival with eating and drinking, i.e. social pleasures. [Oth. explan.: he who makes an <i>addition</i> to the number of festive days;—hence the popular name of <span dir=\"rtl\">אסרו חג</span> for the day following the festivals.]</div><div class=\"sense\"><b>—2)</b> <i>prohibition, interdict;</i> also <i>the forbidden object</i>. <span class=\"citation\">Y. Ber. I, 3ᵇ</span> bot. <span dir=\"rtl\">דברי תורה יש בהן א׳ וכ׳</span> the Biblical law contains prohibitions and permissions.—א׳ ערוה <i>an obstacle to marriage by the existing laws of incest</i>, e.g. a man prevented from performing a levirate marriage because his late brother’s wife is his own wife’s sister; &amp;c.—א׳ מצוה <i>a marriage</i> (or sexual connection) <i>permitted in the Torah but forbidden by Rabbinical enactment;</i>—so called because obedience to the Rabbis is a meritorious act <a href=\"#\" data-headword=\"מִצְוָה\">(מצוה</a>); <span dir=\"rtl\">א׳ קדושה</span> <i>marriage restrictions</i> incumbent <i>on priests</i> on account of their sacred office; (another opinion inverts the last two definitions). <span class=\"citation\">Yeb. II, 3</span> (<span class=\"citation\">20ᵃ</span>).—<span dir=\"rtl\">אין א׳ חל על א׳</span> one prohibition can take no legal hold where another prohibition already exists; i.e. you can punish, or impose sacrificial expiation, only for the first one; e.g. if you eat the meat of an unclean animal which, besides, has not been slaughtered according to ritual <span dir=\"rtl\">(נבלה</span>). Ib. 13ᵇ; a. fr.—Exceptions to this principle (adopted by most authorities) are when the acceding act is: 1) <span dir=\"rtl\">א׳ כֹּולֵל</span> <i>a more comprehensive prohibition</i>, i.e. <i>having a wider range of prohibited objects</i>; e.g. the law imposing abstinence from food on the Day of Atonement includes food in general, i.e. food otherwise allowed as well as food forbidden at all times; <span dir=\"rtl\">א׳ מוֹסִיף</span> <i>a more extensive prohibition</i>, i.e. <i>having a wider range of persons concerned;</i> e.g. the sister of A’s wife is forbidden to him (<span dir=\"rtl\">אחות אשתו</span>) but not to his brothers. If, afterwards, his brother B. marries that sister of A.’s wife, she is forbidden in marriage (after B.’s death) to <i>all</i> the brothers as a brother’s wife, and to A. both as his own living wife’s sister and as his late brother’s wife <span dir=\"rtl\">(אשת אח</span>);</div><div class=\"sense\"><b>—3)</b>  א׳ בַּת אַחַת <i>a coincidental prohibition</i>, i.e. two prohibitions <i>taking effect at the same moment</i>, e.g. the Day of Atonement coinciding with the Sabbath day, in which case the restrictions connected with each take effect at the same time (night-fall); </div><div class=\"sense\"><b>4)</b>  א׳ חָמוּר <i>a heavier prohibition</i>, i.e. a prohibition <i>imposing larger restrictions</i>, e.g. the law prohibiting <i>any</i> profitable use of thing <span dir=\"rtl\">(א׳ הנאה</span>), compared to the lighter prohibition, <span dir=\"rtl\">א׳ קַל</span>, not to eat or drink a thing (v. infra). <span class=\"citation\">Yeb. 32ᵇ</span> sq; <span class=\"citation\">Shebu. 24ᵃ</span>; <span class=\"citation\">24ᵇ</span>; <span class=\"citation\">Ḥull. 101ᵃ</span> sq; Kerith. 14ᵇ.—א׳ תורה <i>a Biblical prohibitory law;</i> א׳ דרבנן <i>a Rabbinical prohibitory enactment</i>.—א׳ לאו <i>a prohibition expressed in the Law by a plain</i> (<a href=\"#\" data-headword=\"לֹא\">לֹא</a>) ‘thou shalt not’, without defining the penalty, in which case the latter consists of thirty nine lashes (v. <a href=\"#\" data-headword=\"מַלְקוּת\">מַלְקוּת</a>).—א׳ כרת <i>a prohibition to which the Bible attaches the penalty of excision</i> (by the hand of God).—<span dir=\"rtl\">א׳ מיתה</span> a prohibition the transgression of which the Bible punishes with death (execution).—א׳ אכילה <i>the law not to eat</i> (meat boiled with milk); <span class=\"citation\">Kerith. 14ᵇ</span>.—א׳ תורה <i>a Biblical prohibitory law;</i> א׳ דרבנן <i>a Rabbinical prohibitory enactment</i>.—א׳ לאו <i>a prohibition expressed in the Law by a plain</i> (<a href=\"#\" data-headword=\"לֹא\">לֹא</a>) ‘thou shalt not’, without defining the penalty, in which case the latter consists of thirty nine lashes (v. <a href=\"#\" data-headword=\"מַלְקוּת\">מַלְקוּת</a>).—א׳ כרת <i>a prohibition to which the Bible attaches the penalty of excision</i> (by the hand of God).—<span dir=\"rtl\">א׳ מיתה</span> a prohibition the transgression of which the Bible punishes with death (execution).—א׳ אכילה <i>the law not to eat</i> (meat boiled with milk); <span dir=\"rtl\">א׳ הנאה</span> <i>not to make any use</i> (of it, as selling &amp;c.); <span dir=\"rtl\">א׳ בישול</span> <i>not to boil</i> (meat with milk). <span class=\"citation\">Ḥull. 115ᵇ</span>; a. fr.—<span dir=\"rtl\">א׳ במות</span>, v. <a href=\"#\" data-headword=\"בָּמָה\">בָּמָה</a>.—Pl. <span dir=\"rtl\">אִיסּוּרִין</span>. <span class=\"citation\">Ḥull. 98ᵃ</span> sq. <span dir=\"rtl\"><span dir=\"rtl\">כל א׳ שבתורה</span> (<span dir=\"rtl\">בטלין</span>) <span dir=\"rtl\">בששים</span></span> all things Biblically forbidden are neutralized if mixed with a quantity sixty times as large; <span class=\"citation\">ib.</span> <span dir=\"rtl\">במאה</span>—in a quantity one hundred times as large; a. fr.</div>","alt":["אִסּוּר"]},"1407":{"h":"אִיסּוּרָא","r":"A01407","html":"<div class=\"sense\"><b>1)</b>  as the <a href=\"#\" data-headword=\"אִיסּוּר II\">preced.</a> , <i>band</i>. <span class=\"citation\">Targ. Ezek. III, 25</span>.—Pl. <span dir=\"rtl\">אִיסוּרִין</span>. Targ. ib. XVI, 4 (bandages).—2) as the <a href=\"#\" data-headword=\"אִיסּוּר II\">preced.</a> 2). <span class=\"citation\">Ḥull. 9ᵇ</span>; a. fr.—<span class=\"citation\">B. Bath. 92ᵇ</span> <span dir=\"rtl\">כי אזלינן בתר רובא בא׳ בממונא לא</span> we follow the majority principle (that a doubtful thing is presumed to have the legal status of the majority of its class) only in <i>ritual questions</i>, but not in civil law.—<span dir=\"rtl\">עבד א׳</span> to commit a crime, euphem. for <i>prostitution</i>, &amp;c. <span class=\"citation\">Ab. Zar. 18ᵃ</span>. <span class=\"citation\">Git. 38ᵃ</span>.—Pl. <span dir=\"rtl\">אִיסּוּרֵי</span>, <span dir=\"rtl\">אִסּוּרֵי</span>. <span class=\"citation\">Sabb. 60ᵇ</span> <span dir=\"rtl\">בבלאי שרי א׳</span> a Babylonian permitter of forbidden things (R. Ḥiya).—<span class=\"citation\">Nidd. 24ᵇ</span>, a. fr. <span dir=\"rtl\">הלכתא כרב בא׳</span> Rab is the adopted authority in ritual law. [<span class=\"citation\">Kidd. 12ᵃ</span> זול איסורי &amp;c. read <span dir=\"rtl\">אִיסָרֵי</span>; v. <a href=\"#\" data-headword=\"אִיסָר\">אִיסָר</a>.]</div>","alt":["אִיסוּרָא I","אִסּוּרָא","אֱסוּרָא"]},"1408":{"h":"אִיסוּרָא II","r":"A01408","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">יסר</span>) <i>chastisement.</i> Pl. <span dir=\"rtl\">אִיסוּרִין</span>. <span class=\"citation\">Targ. Koh. III, 10</span>. <span class=\"citation\">Targ. Jer. XXX, 11</span> (Var. <span dir=\"rtl\">יסורין</span>).</div>","alt":[]},"1409":{"h":"אֱיסוּרְיָא","r":"A01409","html":"<div class=\"sense\"><i>, </i> pl. <a href=\"#\" data-headword=\"אֲסוּרְיָיתָא\">אֱיסוּרְיָיתָא</a>, v. <a href=\"#\" data-headword=\"אֲסוּרְיָיתָא\">אֲסוּרְיָיתָא</a>.</div>","alt":[]},"1410":{"h":"אִיסְט־","r":"A01410","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אִיסְ־</span>. For words under <a href=\"#\" data-headword=\"אִיסְט־\">איסט־</a> not found here below, v. <a href=\"#\" data-headword=\"אִסְטְ־\">אסט־</a>, <span dir=\"rtl\">איצט־</span>, <a href=\"#\" data-headword=\"אִצְט־\">אצט־</a>.</div>","alt":[]},"1411":{"h":"אִיסְטְבָא","r":"A01411","html":"<div class=\"sense\"> [also ָ<a href=\"#\" data-headword=\"ה\">ה</a>, a. with one <a href=\"#\" data-headword=\"ו\">ו</a>] m. (Ispe. noun of <span dir=\"rtl\">סב</span>, <span dir=\"rtl\">סבב</span> = h. <a href=\"#\" data-headword=\"אִיסטֵיב\">אִיסְטֵיב</a> q. v., b. h. <a href=\"#\" data-headword=\"מֵסֵב\">מֵסֵב</a>; v. <span dir=\"rtl\">אִיסְ־</span>) <i>a surrounding, attachment</i>, whence </div><div class=\"sense\"><b>1)</b> <i>balcony, colonnade, portico</i>(also <i>an independent colonnade</i>), esp. <span dir=\"rtl\">הָאִ׳</span> the Itst’ba (Ist’ba) <i>the Temple portico</i>. <span class=\"citation\">Pes. I, 5</span> (<span class=\"citation\">11ᵇ</span>) <span dir=\"rtl\">על גג האיצ׳</span> Ms. M. (Bab. ed. incorr. <span dir=\"rtl\">גב</span>, Var. <a href=\"#\" data-headword=\"אִיסְטְוָוה\">אִסְטְוָה</a>, v. Rabb. D. S. a. l. note). Ib. 13ᵇ one recited <span dir=\"rtl\">על גב</span> on top (inside) …, say <span dir=\"rtl\">על גג הא׳</span> on the roof of the Its. (so as to expose it to public view). Y. Sabb. I, 2ᵈ bot. <span dir=\"rtl\">איסטוה וכ׳</span>; Bab. <span class=\"citation\">Sabb. 7ᵃ</span> <span dir=\"rtl\">איצ׳ שלפני העמודים</span> a balcony in front of the columns (projecting into the street, used as a stand for dealers, v. <a href=\"#\" data-headword=\"אִיסטֵיב\">אִיסְטֵיב</a>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דוקא א׳ דלא ניחא תשמישיה</span> Ms. M. (ed. <span dir=\"rtl\">א׳ הוא דלא</span>) only the colonnade the use of which for passers by is not convenient. <span class=\"citation\">Num. R. s. 12</span> two columns of silver which were placed in front of the Ark <span dir=\"rtl\">כמין איסטווה</span> (<span class=\"citation\">Cant. R. to I, 11</span> <span dir=\"rtl\">אִיסְטְוִוין</span> pl.) forming a kind of balcony; <span class=\"citation\">Y. Sot. VIII, 22ᶜ</span> <span dir=\"rtl\">תנם לא׳</span> allow the surplus of three handbreadths (over the space occupied by the Tablets) for the balcony.—<span class=\"citation\">Yoma 49ᵃ</span> דעבוד מעשה אסטווה Ar. (ed. <span dir=\"rtl\">איצ׳</span>) they (the laymen) served only the purpose of a portico (holding the bowls up to view, v. <span class=\"citation\">Pes. I, 5</span>, but not handing them to the altar).—<span class=\"citation\">Y. Succ. V, 55ᵃ</span> bot., v. <a href=\"#\" data-headword=\"דִּיפְּלֵי\">דִּיפְּלֵי</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"הֶסֵּב\">הֶסֵּב</a>, <span dir=\"rtl\">הֲסִיבָּה</span>) <i>something to recline on; couch, seat</i>. <span class=\"citation\">Kidd. 70ᵃ</span>, (to one using the high-toned <span dir=\"rtl\">קרפיטא</span> q. v.) <span dir=\"rtl\">א׳ דאמרי אינשי</span> call it itst’ba as the people do.—<span class=\"citation\">M. Kat. 10ᵇ</span> למבני א׳ Ar. a. ed. (Var. as Yoma l. c.) to build a temporary <i>banqueting place</i> for guests during the festive week, cmp. <a href=\"#\" data-headword=\"אַכְוַרְנְקָא\">אַכְוַרְנְקָא</a>, (Rashi: <i>stone building</i>, Ms. Rashi <span dir=\"rtl\">כסא</span>).—Pl. <span dir=\"rtl\">אִיצְטְבָאוֹת</span> (h. form). <span class=\"citation\">Ex. R. s. 31</span> (basilicas).—<span dir=\"rtl\">אִיצְטְבֵי</span> (Chald. form). <span class=\"citation\">Pes. 65ᵇ</span> <span dir=\"rtl\">דמסגי אא׳</span> they (the priests) walked alongside the walls on balconies (projecting boards made for them that they should not tread on the blood); Y. ib. V, 32ᶜ bot. <span dir=\"rtl\">מִסְטְוָיוֹת</span>, V. <span dir=\"rtl\">מִסְטְוָה</span>.</div>","alt":["אִיסְטְוָוא","אִסְ׳","אִיצְ׳","אִצְ׳"]},"1412":{"h":"*אִיסְטַגְלִילִית","r":"A01412","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Ispe. of <span dir=\"rtl\">סגלל</span>, r. <span dir=\"rtl\">סגל</span>; cmp. <a href=\"#\" data-headword=\"סגלגל\">סגלגל</a> a. b. h. <a href=\"#\" data-headword=\"אֶשְׁכּוֹל\">אֶשְׁכֹּול</a>) <i>cluster, a crowded band</i>. <span class=\"citation\">Ber. 51ᵃ</span> א׳ של מלאכים וכ׳ Ms. Beth Nath. (Ar. <span dir=\"rtl\">אִסִתַּלְגִּינִית</span>, ed. <a href=\"#\" data-headword=\"איסתלגינית\">אִיסְתַּלְגָנִית</a>. transpose <span dir=\"rtl\">איסתגל׳</span>, Ms. M. <span dir=\"rtl\">איסתלתנות</span> read <span dir=\"rtl\">אִיסְתַּלְתָּלִית</span> fr. <a href=\"#\" data-headword=\"תַּלְתַּל\">תלתל</a>; v. Rabb. D. S. a. l.) a cluster of angels of destruction.</div>","alt":[]},"1413":{"h":"אִיסְטַגְנֵין","r":"A01413","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אִסְטַ׳</span></div>","alt":["אִיסְטַגְנִינוּת"]},"1414":{"h":"איסטדומוטא","r":"A01414","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְטְרוֹפוֹמָטָא\">אִסְטְרוֹפוֹמָטָא</a></div>","alt":[]},"1415":{"h":"אִיסְטַדְיָא","r":"A01415","html":"<div class=\"sense\"> &amp;c., v. <a href=\"#\" data-headword=\"אִסְטַגְנֵין\">אִיצְטַ׳</a> a. <a href=\"#\" data-headword=\"אִסְטַרְיָא\"><a href=\"#\" data-headword=\"אִסְטַרְיָא\">אִסְטַרְיָא</a>.</a></div>","alt":["אִיסְטַדְיָה"]},"1416":{"h":"איסטדין","r":"A01416","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיצְטַדִּין\">אִיצְטַדִּין</a> a. <a href=\"#\" data-headword=\"אִסְטָרִין\"><a href=\"#\" data-headword=\"אִסְטָרִין\">אִסְטָרִין</a>.</a></div>","alt":[]},"1417":{"h":"אִיסְטְדִירָא","r":"A01417","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטְרִידָא\">אִיסְטְרִידָא</a></div>","alt":[]},"1418":{"h":"אִיסְטַהַר","r":"A01418","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"> (r. <a href=\"#\" data-headword=\"סַהַר\">סהר</a> = <span dir=\"rtl\">זהר</span>) <i>Istahar</i> (beauty). <span class=\"citation\">Yalk. Gen. 44</span> (a legendary personage).</div>","alt":[]},"1419":{"h":"אִיסטְוָוא I","r":"A01419","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִיסְטְבָא</a></div>","alt":["אִיסְטְוָוה"]},"1420":{"h":"אִיסְטְוָוא II","r":"A01420","html":"<div class=\"sense\"> (m.?) (Isp. noun of <span dir=\"rtl\">סוי</span>; cmp. b. h. <a href=\"#\" data-headword=\"סוּת\">סוּת</a>, <a href=\"#\" data-headword=\"מַסְוֶה\">מַסְוֶה</a>) <i>cover, blanket</i>, (<i>coarse</i>) <i>cloak</i>. <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> <span dir=\"rtl\">מרקען</span>—<span dir=\"rtl\">א׳ דההוא גברא אית ביה</span> (ed. Krot. … בָּהּ … מקרען <i>rents</i>) this man’s (thy) blanket has twelve patches (<span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">חד כותאי</span>, 1 has <a href=\"#\" data-headword=\"מַרְדְּעָא\">מרדעא</a>).</div>","alt":["אִסְ׳"]},"1421":{"h":"אִיסְטְוָוה","r":"A01421","html":"<div class=\"sense\"> v. supra.</div>","alt":[]},"1422":{"h":"אִיסְטְוָונָא","r":"A01422","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִיסְטְבָא</a>) <i>a balcony</i>(h. . <span class=\"citation\">Targ. II Kings XI, 14</span>; <span class=\"citation\">II Chron. XXXIV, 31</span>, a. e. <span dir=\"rtl\">נֵיה …</span> the balcony (of his palace).</div>","alt":[]},"1423":{"h":"אִיסְטְוָונִית","r":"A01423","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִיסְטְבָא</a>) <i>a system of colonnades, colonnade with double rows, basilica</i> (v. Sm. Ant. s. v. Basilica). <span class=\"citation\">Pes. 13ᵇ</span> <span dir=\"rtl\">א׳ היתה נקראת</span> (the <i>itst’ba</i> of the Temple being of double rows) was called <i>ist’vanith</i>, v. <a href=\"#\" data-headword=\"אִסְטֵיב\">אִסְטֵיו</a>, <a href=\"#\" data-headword=\"סְטֵיו\">סְטֵיו</a>. Ohol. XVIII, 9 (ed. <span dir=\"rtl\">נִיֹּות …</span> pl.). <span class=\"citation\">Tosef. Sabb. I, 4</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"אִיסְטְוָונִית\">אִיסְטְוָונִיֹּות</a>. Ohol. l. c., v. supra.—Tanḥ. <span class=\"citation\">Mishp. 14</span> (ed. Bub. 6 <span dir=\"rtl\">איסטוטין</span> corr. acc.). Tosef. Oh. XVIII, 12 <a href=\"#\" data-headword=\"אִיסְטוָנוֹת\">אִיסְטְוָנוֹת</a> (prob. incorr.).</div>","alt":["אִיצְ׳","אִסְ׳","אִצְ׳"]},"1424":{"h":"אִיסטְוָורָא","r":"A01424","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטְרִידָא\">אִיסְתְּ׳</a></div>","alt":[]},"1425":{"h":"אִיסְטוֵיט","r":"A01425","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סוּט\">סוּט</a> ch.</div>","alt":[]},"1426":{"h":"אִיסטוֹלִין","r":"A01426","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְטְלִי\">אִסְטְלִי</a></div>","alt":["אִיסְטוֹלִי"]},"1427":{"h":"אִיסְטוָנוֹת","r":"A01427","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטְוָונִית\">אִיסְטְוָונִית</a></div>","alt":[]},"1428":{"h":"איסטופיטא","r":"A01428","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲטִימִיטוֹן\">אֲטִימִיטוֹן</a></div>","alt":[]},"1429":{"h":"אִיסְטַטְיוֹן","r":"A01429","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (στατίων, statio, v. Harper’s Lat. Dict. 1882 s. v. Statio II, B, 4) <i>seat of the fiscal officers in the Roman provinces</i>, also <i>the staff of officers</i>. <span class=\"citation\">Gen. R. s. 66</span> (play on <i>Shulamith</i> <span class=\"citation\">Cant. VII</span>, </div><div class=\"sense\"><b>1)</b>  the people of Israel <span dir=\"rtl\">שמשלמת אִיסְטַטְיוֹנוֹ של עולם וכ׳</span> that preserves the (divine) government of the world complete (filling the vacancies) both in this world &amp;c. Cant. R. to l. c. <a href=\"#\" data-headword=\"איסטטיונרון\">איסטטיונרון</a>, read <span dir=\"rtl\">אִיסְטַטְיוֹנָרִין</span> (stationarii) the number of officers (of the divine government). Cmp. <span dir=\"rtl\">צַדִּיק</span>. V. <a href=\"#\" data-headword=\"סְטַטְיוֹנָר\">סְטַטְיוֹנָר</a></div>","alt":["*(אישטטיון)"]},"1430":{"h":"איסטטיונרון","r":"A01430","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטַטְיוֹן\">אִיסְטַטְיוֹן</a></div>","alt":[]},"1431":{"h":"אִיסְטַטִּית","r":"A01431","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִסְטָנִית\">אִסְטָנִית</a></div>","alt":[]},"1432":{"h":"*אִיסְטַטָּנִית","r":"A01432","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Ispa. of <span dir=\"rtl\">סטן</span>) <i>querulous.</i> <i>—</i> Pl. <a href=\"#\" data-headword=\"*אִיסְטַטָּנִית\">אִיסְטַטָּנִיֹּות</a>. <span class=\"citation\">Gen. R. s. 45</span>. [<span class=\"citation\">Deut. R. s. 6</span> <a href=\"#\" data-headword=\"אִיסְטְסוֹנִית\">אִיסְטְסוֹנִיֹּות</a>, <a href=\"#\" data-headword=\"אִיסְטְסוֹנִית\">אִיסְטְסָנִיֹּות</a>; Ar. <span dir=\"rtl\">סְטִיסְיָאנוֹת</span>, denom. of <a href=\"#\" data-headword=\"סִיס\">סִיס</a>, <a href=\"#\" data-headword=\"סוּסְיָא\">סוּסְיִא</a>, <i>scratching like a bird;</i> v. Gen. R. l. c. quot. s. v. <a href=\"#\" data-headword=\"חָמַס\">חָמַס</a>, a. <span class=\"citation\">Ḥull. 62ᵃ</span> s. v. <a href=\"#\" data-headword=\"סְנוּנִית\">סְנוּנִית</a>.] V. <a href=\"#\" data-headword=\"*אִסְטָנִית\">אִסְטָנִית</a>.</div>","alt":[]},"1433":{"h":"אִיסטֵיב","r":"A01433","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Isp. n. of <span dir=\"rtl\">סב</span> in <span dir=\"rtl\">סבב</span>; cmp. b. h. <a href=\"#\" data-headword=\"מֵסֵב\">מֵסֵב</a>, <span dir=\"rtl\">מוּסַב</span>) <i>an extension around the house</i> (gen. with a stone bench) <i>used as workshop or dealer’s shop, portico, colonnade</i> (cmp. <a href=\"#\" data-headword=\"מִסְטוֹבָא\">מִסְטוֹבָא</a>). Y. B. Bath. II, beg. 13ᵇ top, R.—drove a pastry dealer <span dir=\"rtl\">מא׳ לא׳</span> from portico to portico (it being private ground). Ib. III, end, 14ᵇ a window <span dir=\"rtl\">שהיא פתוחה לא׳ וכ׳</span> opening towards a porch is made only for letting light in. V. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִיסְטְבָא</a>.</div>","alt":["אִסְ׳"]},"1434":{"h":"אִיסְטֵיו","r":"A01434","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִיסטֵיב\">preced.</a>, a. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִיסְטְבָא</a>) <i>colonnade</i>. <span class=\"citation\">Y. Succ. V, 55ᵃ</span> bot.; <span class=\"citation\">Y. Taan. III, 66ᵈ</span> bot.; v. <a href=\"#\" data-headword=\"סְטֵיו\">סְטֵיו</a>.</div>","alt":["אִסְ׳"]},"1435":{"h":"איסטיוט","r":"A01435","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סוּט\">סוּט</a></div>","alt":[]},"1436":{"h":"איסטיות","r":"A01436","html":"<div class=\"sense\"> Y. Ab. Zar. II, 42ᵃ bot. v. <a href=\"#\" data-headword=\"אִסְטַגְיוֹת\">אִסְטַגְיוֹת</a></div>","alt":[]},"1437":{"h":"אִיסטִיטִית","r":"A01437","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִסְטָנִית\">אִסְטָנִית</a></div>","alt":[]},"1438":{"h":"אִיסְטְיָיא","r":"A01438","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Istya</i>. <span class=\"citation\">Y. Yeb. I, 2ᶜ</span></div>","alt":[]},"1439":{"h":"*איסטילין","r":"A01439","html":"<div class=\"sense\"> Midr. Sam. ch. XI, v. <a href=\"#\" data-headword=\"אִסְטְלִי\">אִסְטְלִי</a></div>","alt":[]},"1440":{"h":"איסטיס","r":"A01440","html":"<div class=\"sense\"> <span class=\"citation\">Ex. R. s. 15</span>, read <a href=\"#\" data-headword=\"אִיסטֵיב\">אִיסְטֵיב</a>; cmp. Tanḥ. Ḥayé, 3 <span dir=\"rtl\">איצטבא</span>.</div>","alt":["איסטית"]},"1441":{"h":"אִיסָטִיס","r":"A01441","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἰσάτις, isatis tinctoria) <i>a plant producing a deep blue dye, woad.</i> <span class=\"citation\">Shebi. VII, 1</span>. Y. ib. 37ᵇ <a href=\"#\" data-headword=\"אסטים\">אסטים</a> (corr. acc.). <span class=\"citation\">B. Kam. 101ᵇ</span> אס׳ Ar. (ed. <span dir=\"rtl\">סטיס</span>, <a href=\"#\" data-headword=\"סטים\">סטים</a>; corr. acc.). <span class=\"citation\">Meg. IV, 7</span>; a. fr.</div>","alt":["אִסָּטִיס","(סָטִיס)"]},"1442":{"h":"איסטיסית","r":"A01442","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִסְטָנִית\">אִסְטָנִית</a></div>","alt":[]},"1443":{"h":"איסטירטיגוס","r":"A01443","html":"<div class=\"sense\"> <span class=\"citation\">Midr. Till. to Ps. XVII</span>, beg. <span dir=\"rtl\">כמין א׳</span> read <span dir=\"rtl\">אִיסְפַרְגִּיס</span>, v. <a href=\"#\" data-headword=\"סְפַרְגִּיס\">סְפַרְגִּיס</a>. [V. <a href=\"#\" data-headword=\"אִסְטַרְטֵיגוֹס\">אִסְטַרְטֵיגוֹס</a>.]</div>","alt":[]},"1444":{"h":"איסטית","r":"A01444","html":"<div class=\"sense\"> <span class=\"citation\">Ex. R. s. 15</span>, read <a href=\"#\" data-headword=\"אִיסטֵיב\">אִיסְטֵיב</a>, v. <a href=\"#\" data-headword=\"איסטיס\">איסטיס</a></div>","alt":[]},"1445":{"h":"אִיסְטְמָא","r":"A01445","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> (h. ; Ispe. of √<a href=\"#\" data-headword=\"צם\">צם</a>) <i>something restraining</i> (the hair from flying), <i>band, chaplet</i> (of woolen and other stuff). <span class=\"citation\">Sabb. 57ᵇ</span> (Ms. M. <span dir=\"rtl\">אצ׳</span>); v. <a href=\"#\" data-headword=\"בִּזְיוֹנָא\">בִּזְיוּנֵא</a>. <span class=\"citation\">Tosef. ib. IV, 7</span>, <span class=\"citation\">Kil. V, 26</span>.</div><div class=\"sense\"><b>—2)</b> <i>steel</i>, v. <a href=\"#\" data-headword=\"אִסְטְמָא\">אִסְטְמָא</a>.</div>","alt":["אִצְטְמָא"]},"1446":{"h":"*איסטמאה","r":"A01446","html":"<div class=\"sense\">, Ms. M. <span dir=\"rtl\">איסתמי מייתי</span>, Ar. <span dir=\"rtl\">אסטממיתיה</span>, Ms. O. <span dir=\"rtl\">איסתמתיה</span>, some ed. <span dir=\"rtl\">איסטמה</span>, a word in a charm formula (apparently a fictitious denom. of <a href=\"#\" data-headword=\"סמי\">סמי</a>). <span class=\"citation\">Sabb. 67ᵃ</span></div>","alt":[]},"1447":{"h":"איסטנינותיא","r":"A01447","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטַפְלִינִין\">אִיסְטַפְנִינֵי</a></div>","alt":[]},"1448":{"h":"אִיסְטְנִיס","r":"A01448","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>delicate</i>, v. <a href=\"#\" data-headword=\"אִיסְתְּנִיס\">איסְתְּנִיס</a>.</div>","alt":[]},"1449":{"h":"אִיסְטְסוֹנִית","r":"A01449","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִיסְטַטָּנִית\">אִיסְטַטָּנִית</a></div>","alt":["אִיסְטְסָנִית"]},"1450":{"h":"איסטפונין","r":"A01450","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטַפְלִינִין\">next w.</a></div>","alt":[]},"1451":{"h":"אִיסְטַפְלִינִין","r":"A01451","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (σταφυλῖνος, οι, Syr. <span dir=\"rtl\">אסטפלינין</span> P. Sm. 301, prob. of Semit. orig., rad. <span dir=\"rtl\">טפל</span>) <i>a kind of carrot, parsnip</i>. <span class=\"citation\">Y. Maasr. II, end, 50ᵃ</span> bot. <span class=\"citation\">Y. Ḥall. IV, 60ᵃ</span> top <a href=\"#\" data-headword=\"אִיסְטְרִידָא\">אִיסְתַּ׳</a>. <span class=\"citation\">Ib.</span> <a href=\"#\" data-headword=\"איסטנינותיא\">איסטנינותיא</a> read <span dir=\"rtl\">איסטפנינִיתֵיה</span> his parsnip. Y. Kil. I, 27ᵃ bot. <span dir=\"rtl\">אסטפלינון</span> R. Sims. to <span class=\"citation\">Kil. I, 4</span> (ed. corrupt). <span class=\"citation\">Tosef. Ukts. I, 1</span> <span dir=\"rtl\">אסטפונין</span>.</div>","alt":["אִיסְטַפְנִינֵי","(אִיסְתַּפְנִינֵי)"]},"1452":{"h":"אִיסְטְרָא","r":"A01452","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְתִּירָא\">אִיסְתִּירָא</a></div>","alt":[]},"1453":{"h":"אִיסְטְרוֹבִיל","r":"A01453","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (στρόβιλος) </div><div class=\"sense\"><b>1)</b> <i>cone</i>, also <i>kernel of the stone pine</i>, (nux pinea).—Pl. <span dir=\"rtl\">אִיסְטְרוֹבְלִין</span>, <span dir=\"rtl\">אִיסְטְרוֹבִילִין</span> &amp;c. <span class=\"citation\">Ab. Zar. I, 5</span> (<span class=\"citation\">13ᵇ</span> sq.); defined ibid. <i>fruit of the cedar</i> (stone pine); a. fr. <span class=\"citation\">Pesik. R. s. 10</span> <span dir=\"rtl\">אסטרובלית</span> (read <span dir=\"rtl\">לִים</span>— or <span dir=\"rtl\">לוֹת</span>—).</div><div class=\"sense\"><b>—2)</b>  (v. Sm. Ant. s. v. Mola) <i>the cone</i> or <i>lower millstone</i> (which is immovable, hence included in the sale of the house). <span class=\"citation\">B. Bath. IV, 3</span>. <span class=\"citation\">Zabim IV, 2</span>.—Pl. <span dir=\"rtl\">אִסְטְרוֹבְלִין</span>, <a href=\"#\" data-headword=\"אִיסְטְרוֹבִיל\">אִיסְטְרוֹבִילֵי</a> &amp;c. <span class=\"citation\">Gen. R. s. 28</span>; a. e. <span class=\"citation\">Keth. 69ᵃ</span> Ar. (ed. more correctly <span dir=\"rtl\">בל …</span>, sing.).</div>","alt":["אִיסְטְרוֹבְלָא","אִסְ׳","אִצְ׳","אִיצְ׳"]},"1454":{"h":"אִיסְטְרוֹבִילוֹס","r":"A01454","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Istrobilos</i> (v. <a href=\"#\" data-headword=\"אִיסְטְרוֹבִיל\">preced.</a>; but prob. a corrupt. of <a href=\"#\" data-headword=\"אֲרִיסְטוֹבּוֹלוֹס\">אֲרִיסְטוֹבוּלוֹס</a>). <span class=\"citation\">Y. Kil. IX, 32ᶜ</span> bot. (<span class=\"citation\">Y. Keth. XII, 35ᵇ</span> <a href=\"#\" data-headword=\"איסטריבוליא\">איסטריבוליא</a>, corr. acc.).</div>","alt":[]},"1455":{"h":"אִיסְטְרוֹגֵי","r":"A01455","html":"<div class=\"sense\"> m. pl., a. corrupt. of <span dir=\"rtl\">אִיסְטַרְטֵיגֵי</span>, v. <span dir=\"rtl\">אִסְטַ׳</span></div>","alt":[]},"1456":{"h":"איסטרולוגוס","r":"A01456","html":"<div class=\"sense\"> and deriv., v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אַסְ׳</a>. [<span class=\"citation\">Koh. R. to I, 14</span>, read <a href=\"#\" data-headword=\"לוֹגִיסְטֵיס\">לוֹגִיסְטֵס</a>.]</div>","alt":[]},"1457":{"h":"איסטרטטי","r":"A01457","html":"<div class=\"sense\"> <span class=\"citation\">Cant. R. to VII, 9</span>, defining <span dir=\"rtl\">גדבריא</span> <span class=\"citation\">Dan. III, 2</span>, read <a href=\"#\" data-headword=\"אִסְטְרָטִילָטָא\">אִיסְטְרַטִילָטֵי</a>, v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִסְ׳</a></div>","alt":[]},"1458":{"h":"איסטריא","r":"A01458","html":"<div class=\"sense\">, <span class=\"citation\">Men. 103ᵇ</span>, v. <a href=\"#\" data-headword=\"אִסְטְרַטְיָא\">אִסְטְרַטְיָא</a> a. <a href=\"#\" data-headword=\"אִסְטַרְיָא\"><a href=\"#\" data-headword=\"אִסְטַרְיָא\">אִסְטַרְיָא</a>.</a></div>","alt":[]},"1459":{"h":"איסטריבוליא","r":"A01459","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטְרוֹבִילוֹס\">אִיסְטְרוֹבִילוֹס</a></div>","alt":[]},"1460":{"h":"אִיסְטְרִידָא","r":"A01460","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Ispe. of <a href=\"#\" data-headword=\"סָרָד\">סרד</a>, cmp. <a href=\"#\" data-headword=\"סָרִיד\">סְרִיד</a>, <a href=\"#\" data-headword=\"סְרָדָא\">סְרָדָא</a> &amp;c.) <i>net-work</i>, esp. <i>rigging, sail-yard, sails</i>. [If the vers. <a href=\"#\" data-headword=\"אִיסְטְדִירָא\">אִיסְטְדִירָא</a>, <a href=\"#\" data-headword=\"אִסְתְּדִירָא\">אִסְתְּדִירָא</a>, v. Rabb. D. S. to <span class=\"citation\">Sabb. 111ᵇ</span> note 2, be correct, it must be derived from <span dir=\"rtl\">סדר</span>; cmp. b. h. <span dir=\"rtl\">סִדְרוֹן</span>, <a href=\"#\" data-headword=\"סִדְרָא\">סְדֵרָה</a>.] <span class=\"citation\">Sabb. 111ᵇ</span> <span dir=\"rtl\">קטרא דקטרי באי׳</span> the loop which they make when attaching the sail to the rigging. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ודאי׳ גופה</span> and the (permanent) knots in the rigging or ropes.</div>","alt":["*(איסטדירא)","אִיסְתְּ׳","אִצְטְ׳"]},"1461":{"h":"איסטריפומטא","r":"A01461","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְטְרוֹפוֹמָטָא\">אִסְטְרוֹפוֹמָטָא</a></div>","alt":[]},"1462":{"h":"*אִיסְטַרְכִין","r":"A01462","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (Ispe. of <a href=\"#\" data-headword=\"סֶרֶךְ\">סרך</a>; cmp. b. h. <span dir=\"rtl\">שְׂרוֹךְ</span>) <i>plaited chords</i>, as a collect. noun fem. <i>a girdle of strips of cloth</i> (used by washers). <span class=\"citation\">Y. B. Kam. X, end, 7ᶜ</span> <span dir=\"rtl\">הוה עביד ליה חדא א׳ וכ׳</span> used to make for himself one girdle of one kind of wool (so as not to be suspected of using strips of the cloths given him for washing).</div>","alt":[]},"1463":{"h":"אִיסִי","r":"A01463","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Isi</i>, abbr. of Joseph (v. <span class=\"citation\">Yoma 52ᵇ</span> <span dir=\"rtl\">הוא יוסף הוא א׳</span>), esp. known: I. b. Y’hudah, an Amora; (v. Frankel M’bo, p. 100ᵇ). <span class=\"citation\">Ḥull. 115ᵇ</span>; a. fr.</div>","alt":[]},"1464":{"h":"איסיפקאות","r":"A01464","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְקָפָא\">אִסְקָפָא</a></div>","alt":[]},"1465":{"h":"אִיסְכֹּולִי","r":"A01465","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִסְ׳</a></div>","alt":[]},"1466":{"h":"אִיסְכֹּולַסְטִיקָא","r":"A01466","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (σχολαστικός, <i>scholasticus;</i> S.; D. C.) <i>scholasticus = causidicus, advocate, pleader</i>. <span class=\"citation\">Y. Ber. IV, 7ᵈ</span>; cmp. <span class=\"citation\">Gen. R. s. 64</span>, end, <span dir=\"rtl\">אסקולסטיכא דאורייתא</span> Ar. (trnsp. <a href=\"#\" data-headword=\"כ\">כ</a> a. <a href=\"#\" data-headword=\"ק\">ק</a>; ed. <a href=\"#\" data-headword=\"ארכילוסטקיא\">ארכילוסטקיא</a>; corr. acc.) pleader in behalf of the Jewish law.—Pl. <a href=\"#\" data-headword=\"אִיסְכֹּולַסְטִיקָא\">אִיסְכֹּולַסְטִיקֵי</a>. <span class=\"citation\">Cant. R. to VII, 9</span> <a href=\"#\" data-headword=\"איסכלוסקי\">איסכלוסקי</a>, corr. acc.—אִיסְכֹּולַסְטְקִין <span class=\"citation\">Ex. R. s. 43</span> <span dir=\"rtl\">כקתדרה של אסט׳</span> (corr. acc., <a href=\"#\" data-headword=\"כַּו\">כו</a> mistaken for <a href=\"#\" data-headword=\"ט\">ט</a>) like the pulpit of the scholastici. [Also written <span dir=\"rtl\">סְכוֹ׳</span>.]</div>","alt":["אִסְ׳"]},"1467":{"h":"אִיסְכּוּפְיָה","r":"A01467","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> א׳ דשילה <i>Iskufia, near Shiloh</i>. <span class=\"citation\">Y. Meg. I, 72ᵈ</span> top, expl. <span dir=\"rtl\">תאנת שלה</span> <span class=\"citation\">Josh. XVI, 6</span> (σκοπιά; cmp. <span class=\"citation\">Zeb. 118ᵇ</span>, as quot. in <span class=\"citation\">Yalk. Deut. 881</span>).</div>","alt":[]},"1468":{"h":"איסכלא","r":"A01468","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אַסְכּ׳</span> a. <a href=\"#\" data-headword=\"אִיסְטְבָא\"><a href=\"#\" data-headword=\"אִיסְטְבָא\">אִסְ׳</a>.</a></div>","alt":[]},"1469":{"h":"איסכלוסקי","r":"A01469","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְכֹּולַסְטִיקָא\">אִיסְכֹּולַסְטִיקָא</a></div>","alt":[]},"1470":{"h":"*אִיסְמְטָא","r":"A01470","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"סִימְטָא\">סִימְטָא</a> q. v.; <span dir=\"rtl\">סמט</span> = <span dir=\"rtl\">שמט</span>) <i>recess of the market place, alley</i>. <span class=\"citation\">Y. Ber. III, 6ᶜ</span> bot.</div>","alt":[]},"1471":{"h":"*איסניא","r":"A01471","html":"<div class=\"sense\"> <span class=\"citation\">Gen. R. s. 37</span>, v. <a href=\"#\" data-headword=\"אוסיא\">אוסיא</a></div>","alt":[]},"1472":{"h":"איספו","r":"A01472","html":"<div class=\"sense\">, Tanḥ. T’rumah, 9 <span dir=\"rtl\">א׳ נרמוז</span>, v. <a href=\"#\" data-headword=\"אִיסְפֶנְדַּמְנוֹס\">אִיסְפֶנְדַּמְנוֹס</a></div>","alt":[]},"1473":{"h":"איספוטיקוס","r":"A01473","html":"<div class=\"sense\"> read <a href=\"#\" data-headword=\"אִיפָּטִיקוֹס\">אִיפָּטִּיקוֹס</a>.</div>","alt":[]},"1474":{"h":"איספוסין","r":"A01474","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"איפופיס\">איפופסין</a></div>","alt":[]},"1475":{"h":"איספטיא","r":"A01475","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסוֹפֹּולִיטְיָיא\">אִיסוֹפֹּולִיטְיָיא</a></div>","alt":["איספטייה","איספטלייה"]},"1476":{"h":"איספטר","r":"A01476","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְפָּתִי\">אִסְפָּתִי</a></div>","alt":[]},"1477":{"h":"איספי","r":"A01477","html":"<div class=\"sense\"> Tanḥ. T’rumah, 9, v. <a href=\"#\" data-headword=\"איספו\">איספו</a></div>","alt":[]},"1478":{"h":"איספיטין","r":"A01478","html":"<div class=\"sense\"> <span class=\"citation\">Yalk. Ps. 808</span>, v. <a href=\"#\" data-headword=\"*אִסְפְּרִיטִין\">אִיסְפְּרִיטִין</a></div>","alt":[]},"1479":{"h":"*איספיסריאון","r":"A01479","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 5</span>, read <span dir=\"rtl\">אוֹפְּסָרִיאוּ</span> (ὀψαρίου) = <i>comes annonæ;</i> v. D. C. s. v. Comes.</div>","alt":["קומיס א׳"]},"1480":{"h":"אִיסְפְּלִידָא","r":"A01480","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְפַּרְגּוֹס\">אִסְפּ׳</a></div>","alt":["איספליטון","אִיסְפְּלָנִית(א)","אִיסְפַּמְיָא"]},"1481":{"h":"אִיסְפֶנְדַּמְנוֹס","r":"A01481","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (σφενδάμνος) <i>maple-tree</i>. Tanḥ. T’rumah, 9 <span dir=\"rtl\">איספו נרמוז</span> ed. (Ar. <a href=\"#\" data-headword=\"אספינדמון\">אספינדמון</a>; corr. acc.) <i>Tidhar</i> (<span class=\"citation\">Is. LX, 13</span></div>","alt":[]},"1482":{"h":"*אִיסְפְּקָא","r":"A01482","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָפַק I\">ספק</a>) prop. <i>feeder, supplier</i>, hence <i>vessel in which wine is put on the table</i> (amphora). <span class=\"citation\">Targ. O. Ex. XVI, 33</span> Ar. (ed. <a href=\"#\" data-headword=\"צְלוֹחִית\">צלוחית</a>). <span class=\"citation\">Git. 14ᵃ</span>. Cmp. <a href=\"#\" data-headword=\"זֶפֶק\">זֶפֶק</a>.</div>","alt":[]},"1483":{"h":"איספקאות","r":"A01483","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְקָפָא\">אִסְקָפָא</a></div>","alt":[]},"1484":{"h":"אִיסְפִּקְלָטוֹר","r":"A01484","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (speculator, spiculator) <i>arm-bearer</i>, esp. <i>guardsman</i> of the Roman Emperor; mostly <i>executioner, torturer</i> (v. D. C. s. v.). <span class=\"citation\">Sabb. 108ᵃ</span>. <span class=\"citation\">Num. R. s. 19</span>. <span class=\"citation\">Lev. R. s. 26</span> <a href=\"#\" data-headword=\"סִיפּוּק\">ספ׳</a>. <span class=\"citation\">Lam. R. to II, 1</span>.  v. <a href=\"#\" data-headword=\"סְפִיקוּלָא I\">סְפִיקוּלָא</a>.</div>","alt":["סְפִיקְלָטוֹר"]},"1485":{"h":"אִיסְפַּקְלָטוֹרָא","r":"A01485","html":"<div class=\"sense\"> …, <span dir=\"rtl\">רֵי …</span> Targ. II Esth. V, 2. <span class=\"citation\">Targ. Y. Gen. XXXVII, 36</span>.</div>","alt":["סְפוֹקְלָטוֹרָא"]},"1486":{"h":"אִיסְפַּקְלַרְיָא","r":"A01486","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְפַּרְגּוֹס\">אִסְפַּ׳</a></div>","alt":[]},"1487":{"h":"*איספקסיטין","r":"A01487","html":"<div class=\"sense\">, read <span dir=\"rtl\">אוֹפְּסַרְטִיטֵיס</span> m. (ὀψαρτυτής) <i>cook</i>. <span class=\"citation\">Esth. R. to I, 14</span>, read <span dir=\"rtl\">הא׳ של כולם</span> (<a href=\"#\" data-headword=\"מְמוּכָן\">ממוכן</a> = <i>preparing</i>).</div>","alt":[]},"1488":{"h":"איספקרפסטי","r":"A01488","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְקְפַסְטִי\">אִסְקְפַסְטֵי</a></div>","alt":[]},"1489":{"h":"אִיסְפַּרְגּוֹס","r":"A01489","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀσπάραγος) </div><div class=\"sense\"><b>1)</b> <i>asparagus</i>, also <i>shoots of cabbage</i>, like asparagus in form. <span class=\"citation\">Ned. VI, 10</span> if one vows abstinence from cabbage <span dir=\"rtl\">אסור בא׳</span> he is forbidden to eat asparagus (the latter being considered a species of the genus ‘cabbage’). <span class=\"citation\">Tosef. Dem. IV, 5</span> <span dir=\"rtl\">לקנב את הא׳ שׁבו</span> to cut off the stalks thereon (and throw the remainder away).</div><div class=\"sense\"><b>—2)</b> <i>asparagus, a beverage</i> of wine or beer with asparagus. <span class=\"citation\">Ber. 51ᵃ</span>. <span class=\"citation\">Pes. 110ᵇ</span>. <span class=\"citation\">Kidd. 70ᵃ</span> <span dir=\"rtl\">אי׳ דקריוה וכ׳</span> aspar. as the educated call (the morning drink). [<span class=\"citation\">Yalk. Gen. 34</span> <a href=\"#\" data-headword=\"אִיסְפַּרְגּוֹס\">איספרגוס</a> read <span dir=\"rtl\">אִיסְפַרְגִּיס</span> (σφραγίς) <i>seal</i>, v. <a href=\"#\" data-headword=\"סְפַרְגִּיס\">סְפַרְגִּיס</a>.]</div>","alt":["אִסְפַּ׳"]},"1490":{"h":"אִיסְפַּרְגַּל","r":"A01490","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Arab. safar-ḡel) <i>ispargal</i>, name of a fruit (called Persæa, Περσαία), <i>plum;</i> others: <i>quince</i>.—Pl. <span dir=\"rtl\">אִיסְפַּרְגְּלִין</span>. <span class=\"citation\">Y. Maasr. I, 48ᵈ</span> bot.; <span class=\"citation\">Y. Kil. I, 27ᵃ</span>, explain. <span dir=\"rtl\">פרישין</span> = persæa. V. Löw Pfl. pp. 144, 289, a. Sm. Ant. s. v. <i>Persæa</i></div>","alt":["(אספרלג)"]},"1491":{"h":"אִיסְפַרְמְקִי","r":"A01491","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְפַּרְגּוֹס\">אִסְפַּ׳</a></div>","alt":["(איספרקמי)"]},"1492":{"h":"איספרנמין","r":"A01492","html":"<div class=\"sense\">, Tanḥ. ed. Bub. T’rumah. 9, v. <a href=\"#\" data-headword=\"אִיסְפֶנְדַּמְנוֹס\">אִיסְפֶנְדַּמְנוֹס</a></div>","alt":[]},"1493":{"h":"אִיסְפַּתְרִין","r":"A01493","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִסְ׳</a></div>","alt":[]},"1494":{"h":"אִיסָק","r":"A01494","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Isak</i>. <span class=\"citation\">B. Mets. 39ᵇ</span> Mari ben I. (v. Rabb. D. S. a. l.); <span class=\"citation\">Keth. 27ᵇ</span></div>","alt":[]},"1495":{"h":"איסקבטיריי","r":"A01495","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"איסקריטורי\">איסקריטורי</a></div>","alt":[]},"1496":{"h":"אִיסְקוּדְרֵי","r":"A01496","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְקוּנְדְּרֵי\">אִיסִקוּנְדְּרֵי</a></div>","alt":[]},"1497":{"h":"אִיסְקוֹזוּת","r":"A01497","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Isp. of <span dir=\"rtl\">קוז</span> = <span dir=\"rtl\">קוץ</span>; cmp. <span dir=\"rtl\">קְזוֹזוֹת</span>) <i>cutting</i>, trnsf. <i>fate, doom;</i> cmp. <a href=\"#\" data-headword=\"גְּזֵירָה\">גְּזֵירָה</a>. <span class=\"citation\">Esth. R. to I, 14</span> (Ar. ed. Koh. <span dir=\"rtl\">ית …</span>). [Levy Talm. Dict. s. v. <a href=\"#\" data-headword=\"אִיסְקוֹזוּת\">אִסְקוֹזוֹת</a>, quotes <span dir=\"rtl\">היו א׳ … מתוקנות</span>, pl.]</div>","alt":["*(אִיסקוֹזִית)"]},"1498":{"h":"איסקומדרי","r":"A01498","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְקוּנְדְּרֵי\">next w.</a></div>","alt":[]},"1499":{"h":"אִיסְקוּנְדְּרֵי","r":"A01499","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (Pers. iskodâr, ἀσκάνδης, σαγγάνδης, ἀστάδης; v. Perles Et. St. p. 113) prop. <i>despatch-bearers</i>, name of a game, <i>a kind of chess</i>. <span class=\"citation\">Kidd. 21ᵇ</span> באי׳ אטללתו Ar. (Var. Ar. <span dir=\"rtl\">בסק׳</span>; ed. <a href=\"#\" data-headword=\"איסקומדרי\">איסקומדרי</a>) you must have played at <i>iskundré</i> (instead of studying). <span class=\"citation\">Shebu. 29ᵃ</span> <span dir=\"rtl\">דילמא איס׳ וכ׳</span> (Ms. M. <a href=\"#\" data-headword=\"אִיסְקוּדְרֵי\">איסקודרי</a>) perhaps he gave them checkers (tokens in game) and passed them for Zuzé. <span class=\"citation\">Ned. 25ᵃ</span>. Cmp. <a href=\"#\" data-headword=\"*איסקרנדה\">איסקרנדה</a>.</div>","alt":["אִסְק׳","סְקוּנְדּרֵי"]},"1500":{"h":"אִיסְקוּפָּא","r":"A01500","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְקוּנְדְּרֵי\">אִסְק׳</a></div>","alt":["אִיסְקוּפָה","אִיסְקוּפְתָּא"]},"1501":{"h":"אִיסְקוֹרטְיָא","r":"A01501","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (scortea) <i>leather-coat</i>. <span class=\"citation\">Ned. 55ᵇ</span>.  v. <a href=\"#\" data-headword=\"סְקוֹרְטְיָא\">סְקוֹרְטְיָא</a>.</div>","alt":[]},"1502":{"h":"אִיסְקַרְיָא","r":"A01502","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְקַרְיָא\">אִסְקַרְיָא</a></div>","alt":[]},"1503":{"h":"איסקריטורי","r":"A01503","html":"<div class=\"sense\">, read <span dir=\"rtl\">אִיסְקְרִיטָרְיֵי</span> m. pl. (σηκρητάριοι, secretarii) <i>the sovereign’s private secretaries</i> (Asecretis, v. D. C. Gr. a. Lat. s. v.). <span class=\"citation\">Y. Keth. XII, 35ᵇ</span>; <span class=\"citation\">Y. Kil. IX, 32ᶜ</span> <a href=\"#\" data-headword=\"איסקבטיריי\">איסקבטיריי</a> (corr. acc.).</div>","alt":[]},"1504":{"h":"אִיסְקְרִיטֵי","r":"A01504","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְקוּנְדְּרֵי\">אִסְקְ׳</a></div>","alt":["אִיסְקְרִיטִין"]},"1505":{"h":"*איסקרנדה","r":"A01505","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (corrupt. of <a href=\"#\" data-headword=\"אִיסְקוּדְרֵי\">אִיסְקוּדְרָא</a>, Pers. iskodâr; Koh. Ar.; v. <a href=\"#\" data-headword=\"אִיסְקוּנְדְּרֵי\">אִיסְקוּנְדְּרֵי</a>) <i>courier</i>. <span class=\"citation\">Y. Ab. Zar. I, 39ᵈ</span> top <span dir=\"rtl\">יהב תרתין וכ׳</span></div>","alt":[]},"1506":{"h":"אִיסָר","r":"A01506","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contr. of <span dir=\"rtl\">איסהר</span>, cmp. <a href=\"#\" data-headword=\"אִיסְתִּירָא\">איסתירא</a>, an adapt. of assarius = as) <i>As</i>, a Roman coin, usu. <sup>1</sup>/<sub>24</sub> of a Denar (v. Zuckerm. Talm. Gew. p. 22 sq.), called <span dir=\"rtl\">א׳ האיטלקי</span> <i>Italian As</i>. <span class=\"citation\">Kidd. I, 1</span>; a. fr.—Y. ibid. I, 58ᵈ <span dir=\"rtl\">הא׳ אחד מכ&quot;ד וכ׳</span> the As is <sup>1</sup>/<sub>24</sub> of the silver Denar.—Trnsf. <i>coin</i>. <span class=\"citation\">Taan. 19ᵇ</span> <span dir=\"rtl\">מדלית א׳</span> because there was a scarcity of coin.—Pl. <span dir=\"rtl\">אִיסָרִין</span>. <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> top.—<i>Chald.</i> <span class=\"citation\">Kidd. 12ᵃ</span> <span dir=\"rtl\">איסורי</span> read <span dir=\"rtl\">אִיסָרֵי</span>. [<span class=\"citation\">Gen. R. s. 42</span> <span dir=\"rtl\">א׳ לשם אלסר</span> the Assar received its name from Elasar (<span class=\"citation\">Gen. XIV, 1</span>), comment.; v. however next w.] </div>","alt":[]},"1507":{"h":"אִיסָּר","r":"A01507","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> prop. <i>band</i>, hence <i>vow of abstinence</i>, (cmp. <a href=\"#\" data-headword=\"אֵיסוּר\">איסור</a>). <span class=\"citation\">Y. Ned. I, beg. 36ᶜ</span>.—Pl. <span dir=\"rtl\">אִיסָּרוֹת</span>, <span dir=\"rtl\">אִיסָּרִין</span>, <span dir=\"rtl\">אֱסָרִין</span>. <span class=\"citation\">Ibid.</span> <span dir=\"rtl\">אין לוקין על הא׳</span> the punishment of lashes is not applied for breaking vows. <span class=\"citation\">Y. Yeb. XIII, 13ᵈ</span> <span dir=\"rtl\">אסורות</span> (corr. acc.). <span class=\"citation\">Y. Ned. I, 36ᵈ</span> top. [אֵיסָר <i>prisoner</i>, v. <a href=\"#\" data-headword=\"אֵיסוּר\">אֵיסוּר</a>.] [<span class=\"citation\">Gen. R. s. 42</span> <span dir=\"rtl\">א׳ לשם אלסר</span> bands (chains) forged for Elasar, v. preced.]</div>","alt":[]},"1508":{"h":"אֵיסַר","r":"A01508","html":"<div class=\"sense\"><b>1)</b> <i>band, chain.</i> Pl. <span dir=\"rtl\">אֵיסָרִין</span>. <span class=\"citation\">Targ. Jud. XV, 14</span>.</div><div class=\"sense\"><b>—2)</b> <i>vow</i>. <span class=\"citation\">Targ. O. Num. XXX, 3</span> (Y. <a href=\"#\" data-headword=\"אִיסְרָא I\">אִיסְרָא</a>); a. e.—Pl. <span dir=\"rtl\">אֵיסָרִין</span>, <span dir=\"rtl\">אֵיסָרֵי</span>. <span class=\"citation\">Targ. O. Num. XXX, 5</span>; a. e.—[<span class=\"citation\">Targ. Ps. II, 3</span> <a href=\"#\" data-headword=\"אֵסַרְתָּא\">אֱסָרָתָא</a> (some ed. <span dir=\"rtl\">אֵסָרוּ׳</span>), v. next w.]</div>","alt":[]},"1509":{"h":"אִיסְרָא I","r":"A01509","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  , v. preced.—2) </div><div class=\"sense\"><a href=\"#\" data-headword=\"אִיסְרָא I\">אִיסְרָא</a>, <a href=\"#\" data-headword=\"אִיסְרָא I\">אֵיסְרָא</a>; <a href=\"#\" data-headword=\"אֵיסַרְתָּא\">אֵיסַרְתָּא</a> f. <i>bundle, bunch, sheaf</i>. <span class=\"citation\">Targ. Y. Num. XIX, 18</span>. <span class=\"citation\">Targ. O. Gen. XXXVII, 7</span>; a. e.—Pl. <span dir=\"rtl\">אֵיסָרָן</span>, <a href=\"#\" data-headword=\"אֵיסַרְתָּא\">אֵיסָרָתָא</a>. Ibid. (ed. also <span dir=\"rtl\">אֵסרא</span>, <a href=\"#\" data-headword=\"אֵסַרְתָּא\">אֵסרתא</a>). <a href=\"#\" data-headword=\"אֵסַרְתָּא\">אֱסָרָתָא</a> <span class=\"citation\">Targ. Ps. II, 3</span> (some ed. <span dir=\"rtl\">אֵסָרוּ׳</span>) <i>chains;</i> v. <a href=\"#\" data-headword=\"אֵיסַר\">preced.</a></div>","alt":[]},"1510":{"h":"אִיסְרָא II","r":"A01510","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סַר\">סַר</a>) <i>prince, angel, genius</i>. <span class=\"citation\">Pes. 111ᵇ</span> <span dir=\"rtl\">א׳ דמזוני וכ׳</span> (Ms. M. <span dir=\"rtl\">שדא</span>, read <span dir=\"rtl\">שרא</span>; v. Rabb. D. S. a. l.) the genius appointed over sustenance is named <i>Cleanliness</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">א׳ דעניותא וכ׳</span> (in Ms. our w. omitted) the genius of want is named <i>Filth</i>. <span class=\"citation\">Yoma 77ᵃ</span> א׳ דפרסי Ms. M. (ed. <span dir=\"rtl\">שרא</span>, in a passage omitted in many editions, v. Rabb. D. S. a. l.) the genius of the Persians (Pharsees).</div>","alt":[]},"1511":{"h":"אִיסְרָטָא","r":"A01511","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (strata) <i>street</i>, v. <a href=\"#\" data-headword=\"אִסְרָטָא\">אִסְרָטָא</a>.</div>","alt":[]},"1512":{"h":"*אִיסְרָטָה","r":"A01512","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"אִיסְרָטָא\">same</a>. <span class=\"citation\">Y. B. Bath. VIII, 16ᶜ</span> top <span dir=\"rtl\">אינה היא א׳</span> that is not the proper way (= <span dir=\"rtl\">לא זו הדרך</span>), i.e. it is inconsistent that the same formula should be illegal in the case of a letter of divorce, and legal in the case of a donation. <span class=\"citation\">Y. Gitt. VII, 48ᵈ</span> <span dir=\"rtl\">אינה איסרתה</span> (corr. acc., and supplement acc. to Y. B. Bath. l. c.).</div>","alt":[]},"1513":{"h":"*איסרטוס","r":"A01513","html":"<div class=\"sense\">, <span class=\"citation\">Y. B. Mets. II, 8ᶜ</span> <span dir=\"rtl\">מאילין דא׳</span>, read <span dir=\"rtl\">דָּאנִיסְטִיסֵי</span>, v. <a href=\"#\" data-headword=\"דָּנִיסְטֵיס\">דָּנִיסְטֵיס</a></div>","alt":[]},"1514":{"h":"*אִיסְרָטִין","r":"A01514","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (= <span dir=\"rtl\">אסטרטין</span>, pl. of στρατός) <i>band</i> or <i>body of men</i>. <span class=\"citation\">Gen. R. s. 87</span> <span dir=\"rtl\">א׳ של נואפים</span> (Ar. <a href=\"#\" data-headword=\"אסרטיון\">אסרטיון</a>) bands of adulterers; <span dir=\"rtl\">א׳ של רוצחים</span> bands of murderers; (<span class=\"citation\">Yalk. Gen. 145</span> <span dir=\"rtl\">איסטר׳</span>).</div>","alt":[]},"1515":{"h":"איסרקא","r":"A01515","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְרָטָא\">אִסְרָטָא</a></div>","alt":[]},"1516":{"h":"אֵיסַרְתָּא","r":"A01516","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְרָא I\"><span dir=\"rtl\">אִיסְרָא</span> I</a></div>","alt":[]},"1517":{"h":"איסרתה","r":"A01517","html":"<div class=\"sense\"> Y. Gitt. VII, 48ᵈ, v. <a href=\"#\" data-headword=\"*אִיסְרָטָה\">אִיסְרָטָה</a></div>","alt":[]},"1518":{"h":"אִיסְתְּוָורָא","r":"A01518","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Ithpe. or Ispe. of <a href=\"#\" data-headword=\"סוּר I\">סְוַר</a> = <a href=\"#\" data-headword=\"שְׁוַר\">שָׁוַר</a> <i>to leap, stride;</i> b. h. <a href=\"#\" data-headword=\"אֲשׁוּר\">אֲשׁוּר</a>; cmp. <a href=\"#\" data-headword=\"*אִסְפֶּירֶס\">אִסְפֶּירֶס</a>) <i>ankle</i>, <i>foot-step</i>. <span class=\"citation\">Targ. Job XXIII, 11</span>; a. e. <span class=\"citation\">Yeb. 103ᵃ</span>; <span class=\"citation\">Arakh. 19ᵇ</span> <span dir=\"rtl\">האי אי׳ עד ארעא נחית</span> (Ar. <span dir=\"rtl\">אסתוו׳</span>) what is called <i>ist’vira</i> (<i>ankle</i>, in an anatomical sense) goes down to the ground (the entire length of the foot from the ankle). <span class=\"citation\">Men. 33ᵃ</span>, <span dir=\"rtl\">דעבידא כי אי׳</span> a door turning horizontally like the foot from the ankle.—Pl. <span dir=\"rtl\">אִיסְתְּוָורִין</span>, <span dir=\"rtl\">רֵי …</span> <span class=\"citation\">Targ. Koh. XII, 5</span>; a. fr. Cmp. <a href=\"#\" data-headword=\"אֲרוּרֵי\">אֲתוּרֵי</a>.</div>","alt":["אִיסְתְּוִירָא","אִיסְטְוָורָא","אִיסְתַּוְרָא"]},"1519":{"h":"*איסתוננסין","r":"A01519","html":"<div class=\"sense\"> <span class=\"citation\">Y. Maas. Sh. V, 56ᵇ</span> top <span dir=\"rtl\">תלת׳ א׳ וכ׳</span>, read <span dir=\"rtl\">תלתא סִיטוֹנֵיסִין</span> (pl. of σιτώνης) three <i>corn-dealers</i> upon whose estimates he redeemed the second tithes.</div>","alt":[]},"1520":{"h":"אִיסְתַּוְרָא","r":"A01520","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְתְּוָורָא\">אִיסְתְּוָורָא</a></div>","alt":[]},"1521":{"h":"אִיסְתִּירָא","r":"A01521","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contr. of <span dir=\"rtl\">אסתהרא</span> &amp;c., r. <a href=\"#\" data-headword=\"סַהַר\">סהר</a>, <span dir=\"rtl\">צהר</span>; cmp. <a href=\"#\" data-headword=\"אִסְתְּהַר\">אִסְתַּהַר</a> a. <a href=\"#\" data-headword=\"אִיסָר\">אִיסָר</a>) </div><div class=\"sense\"><b>1)</b> <i>a silver coin</i>, (with <a href=\"#\" data-headword=\"זָוָוא I\">זוזא</a> or <a href=\"#\" data-headword=\"פְּשִׁיטָא\">פשיטא</a>, or sub. <a href=\"#\" data-headword=\"זָוָוא I\">זוזא</a> &amp;c.) equal to a common (provincial) <i>Sela</i>, or <i>half a Zuz</i>. <span class=\"citation\">Keth. 64ᵃ</span>; <span class=\"citation\">Gitt. 45ᵇ</span>, v. <a href=\"#\" data-headword=\"טַרְפְּעִיק\">טרפעיקא</a>. <span class=\"citation\">B. Mets. 102ᵇ</span>. <span class=\"citation\">Bekh. 49ᵇ</span> א׳ סורסיא Syriac Istira (v. Zuckerm. Talm. Münz. p. 27). <span class=\"citation\">Kidd. 11ᵇ</span>.—Pl. <a href=\"#\" data-headword=\"אִיסְתִּירָא\">אִיסְתִּירֵי</a> <span class=\"citation\">Gitt. 14ᵃ</span> <span dir=\"rtl\">א׳ זוזי</span>. <span class=\"citation\">Ḥull. 44ᵇ</span> <span dir=\"rtl\">א׳ פשיטי</span>.—<span class=\"citation\">Ib. 105ᵃ</span>. </div><div class=\"sense\"><b>2)</b> <i>Hebr. </i> pl. <span dir=\"rtl\">אִיצְטְרָאוֹת</span>. <span class=\"citation\">Tosef. Shek. II, 4</span> <span dir=\"rtl\">א׳ של זהב</span> (Var. <a href=\"#\" data-headword=\"אִסְטְרָאוֹת\">אִיסְטְרָאוֹת</a>) <i>gold coins</i> (<i>staters</i>). Y. ib. III, 47ᶜ <span dir=\"rtl\">איצטלי</span> (corr. acc.). [Targ. II Esth. II, 7 <span dir=\"rtl\">יונית אִיסְתֵּירָא</span>, a gloss to <span dir=\"rtl\">ככב נגהא</span>, v. <a href=\"#\" data-headword=\"אִסְתְּהַר\">אִסְתַּהַר</a>, confounding our w. with ἀστήρ.]</div>","alt":["אִסְ׳","אִיסְטְרָא","אִיצְטְרָא"]},"1522":{"h":"איסתלגינית","r":"A01522","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִיסְטַגְלִילִית\">אִיסְטַגְלִילִית</a></div>","alt":["איסתלגנית"]},"1523":{"h":"אִיסְתָּנָא","r":"A01523","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִסְ׳</a></div>","alt":[]},"1524":{"h":"אִיסְתַּנְדְּרָא","r":"A01524","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְטַנְדְּרָא\">אִסְטַנְדְּרָא</a></div>","alt":[]},"1525":{"h":"אִיסְתְּנִיס","r":"A01525","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נֵיס\">ניס</a>, Saf. <span dir=\"rtl\">סניס</span>, Ithpe. <a href=\"#\" data-headword=\"אִיסְטְרִידָא\">איסת׳</a>, Ispe. <a href=\"#\" data-headword=\"איסתניסיה\">איסט׳</a>; cmp. <a href=\"#\" data-headword=\"אִיתְנִיס\">אִיתְנִיס</a>; cmp. <a href=\"#\" data-headword=\"אִשְׁתְּמוֹדַע I\">אִשְׁתְּמוֹדַע</a> as to Ishtafel) <i>of feeble health, delicate, fastidious in diet.</i> <span class=\"citation\">Yoma III, 5</span> איסת׳ Ms. a. Ar. (v. Rabb. D. S. a. l., note 10; Bab. ed. mostly <a href=\"#\" data-headword=\"איסתניסיה\">איסט׳</a>). <span class=\"citation\">Pes. 108ᵃ</span>. <span class=\"citation\">Snh. 100ᵇ</span> (opp. <span dir=\"rtl\">דעתו יפה</span> not choicy); a. fr.—Pl. <span dir=\"rtl\">אִיסְתְּנִיסִים</span> &amp;c. <span class=\"citation\">Gen. R. s. 11</span> Ar. (ed. <a href=\"#\" data-headword=\"איסתניסיה\">איסט׳</a>). <span class=\"citation\">Lam. R. to IV, 2</span> <span dir=\"rtl\">סיה …</span> (read … <a href=\"#\" data-headword=\"סִים\">סִים</a>).—<i>Chald.</i> <span class=\"citation\">Targ. Job VI, 7</span> ed. <a href=\"#\" data-headword=\"אַסְטְרוֹלוֹגְיָא\">אסת׳</a> (Ms. <span dir=\"rtl\">אסט׳</span>). [Cmp. b. h. <a href=\"#\" data-headword=\"נְסַס\">נָסַס</a>, ch. <a href=\"#\" data-headword=\"נְסִיס\">נְסִיס</a>.]</div>","alt":["אִיסְטְנִיס","אִסְ׳"]},"1526":{"h":"איסתניסיה","r":"A01526","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְתְּנִיס\">preced.</a></div>","alt":["איסט׳"]},"1527":{"h":"אִיסְתַּפְנִינִי","r":"A01527","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְטְרָטָא\">אִיסְטַ׳</a></div>","alt":[]},"1528":{"h":"אִיסְתְּרוֹקָנִית","r":"A01528","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִסְ׳</a></div>","alt":[]},"1529":{"h":"אִיסְתַּרְתִּיגִין","r":"A01529","html":"<div class=\"sense\"> read <span dir=\"rtl\">איסטרט׳</span>, v. <a href=\"#\" data-headword=\"אִסְטַרְטֵיג\">אִסְטַרְטֵיג</a> a. foll.</div>","alt":[]},"1530":{"h":"איפאניטא","r":"A01530","html":"<div class=\"sense\"> <span class=\"citation\">Yalk. Ex. 167</span>, v. <a href=\"#\" data-headword=\"*איפומנימא\">איפומנימא</a></div>","alt":[]},"1531":{"h":"אֵיפָה I","r":"A01531","html":"<div class=\"sense\"> Sifra Sh’mini ch. VII, Par. 6, v. <a href=\"#\" data-headword=\"חֵיפָה II\"><span dir=\"rtl\">חֵיפָה</span> II</a></div>","alt":[]},"1532":{"h":"*אֵיפָה II","r":"A01532","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אוֹפִי\">אוֹפִי</a>) <i>character, disposition, temper</i>. <span class=\"citation\">Ex. R. s. 40</span> (play on <a href=\"#\" data-headword=\"אֵיפָה I\">אֵיפֹה</a> <span class=\"citation\">Job XXXVIII, 4</span>) <span dir=\"rtl\">הא׳ שלך וכ׳</span> where was thy predestined temper suspended? (on which limb of Adam’s head, hair &amp;c.?, v. preceding passage ibid.). Ib. <span dir=\"rtl\">אֵיפָתְךָ</span>.</div>","alt":[]},"1533":{"h":"אֵיפָה III","r":"A01533","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> [batch], <i>Ephah</i>, a dry measure. <span class=\"citation\">Sifré Deut. 294</span>, both a small as well as a large Ephah <span dir=\"rtl\">קרויה א׳</span> is named Ephah.—<span class=\"citation\">Men. 45ᵇ</span> top <span dir=\"rtl\">אֵיפָתָן</span> the Ephah belonging to the sacrifices; a. fr.—Pl. <span dir=\"rtl\">אֵיפוֹת</span>. Ibid.</div>","alt":[]},"1534":{"h":"*איפוטונקריק","r":"A01534","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 26</span>, <span dir=\"rtl\">א׳ הינטין</span>; ed. Lemb. <span dir=\"rtl\">אפוטונטריק לינטין</span>, ed. Friedm. <span dir=\"rtl\">לינטין</span>, read <span dir=\"rtl\">מִפַּלְטִין טְרִיקְלִין וְקִיטוֹן</span> than the palace (with) triclinium and bed-chamber wherein I dwell.</div>","alt":[]},"1535":{"h":"איפוטיקוס","r":"A01535","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיפָּטִיקוֹס\">איפטיקוס</a></div>","alt":[]},"1536":{"h":"אִיפּוּכִי","r":"A01536","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶפִּיטְרוֹפּוֹס\">אַפּוּ׳</a></div>","alt":[]},"1537":{"h":"אִיפוֹלִין","r":"A01537","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲפוֹלִים\">אֲפוֹלִים</a></div>","alt":[]},"1538":{"h":"אִיפּוּמָא","r":"A01538","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"פּוּם\">פומא</a>) <i>mouth, orifice</i>, esp. <i>sky-light</i> (impluvium). <span class=\"citation\">Erub. 100ᵃ</span> דהוה סליק בא׳ Ms. M. (ed. <span dir=\"rtl\">והוה</span>) (a palm-tree) which grew up through the impluvium. <span class=\"citation\">Kidd. 81ᵃ</span>. <span class=\"citation\">Ḥull. 51ᵃ</span></div>","alt":[]},"1539":{"h":"איפומטא","r":"A01539","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*איפומנימא\">next w.</a></div>","alt":[]},"1540":{"h":"*איפומנימא","r":"A01540","html":"<div class=\"sense\"> (Mus.), <a href=\"#\" data-headword=\"איפומטא\">איפומטא</a>, <span dir=\"rtl\">איפומניטא</span>, <span dir=\"rtl\">איפומג׳</span> &amp;c. (read: <span dir=\"rtl\">אֶיפִּיטִימְיָא</span>) m. pl. (ἐπιτίμια, τὰ) <i>the imposed penalty, sentence</i>. <span class=\"citation\">Deut. R. s. 2</span>; <span class=\"citation\">Yalk. Gen. 77</span>; Ex. 167. [Mus. reads <span dir=\"rtl\">נקרית</span> sing. fem. = ἐπιτιμία.]</div>","alt":[]},"1541":{"h":"*אֵיפוּס","r":"A01541","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אפס</span>, √<a href=\"#\" data-headword=\"אַף I\">אף</a>, cmp. <a href=\"#\" data-headword=\"אֵבוּס\">אֵבוּס</a>) <i>fodder, feed.</i> Pl. <a href=\"#\" data-headword=\"אֵירוּסִין\">אֵיפוּסִין</a>. <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 52</span> <span dir=\"rtl\">איפוסֵיהֶן אין מתקנין …</span> their feed is not prepared for them; (<span class=\"citation\">Ex. R. s. 24</span>, in a passage otherwise miscopied, <a href=\"#\" data-headword=\"*אפוטיקון\">אפוטיקון</a>).</div>","alt":[]},"1542":{"h":"אִיפֹּופּוֹדִין","r":"A01542","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אִפֹּו׳</span></div>","alt":[]},"1543":{"h":"איפופורין","r":"A01543","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִפֹּופֹּודִין\">אִפֹּופֹּודִין</a>, <a href=\"#\" data-headword=\"אַפֹּופְסִין\">אִפֹּופְסִין</a> a. <a href=\"#\" data-headword=\"*אֱפִיפְּיוֹן\"><a href=\"#\" data-headword=\"*אֱפִיפְּיוֹן\">אֱפִיפְּיוֹן</a>.</a></div>","alt":[]},"1544":{"h":"*אֱיפוֹפֵי","r":"A01544","html":"<div class=\"sense\"><i>ĕfofé</i>, a disguise of <i>ĕlohé</i> <a href=\"#\" data-headword=\"לְהִי\">(אֱלֹהֵי</a>); cmp. <a href=\"#\" data-headword=\"אַשְׁקוּקָה\">אִשְׁקוּקָה</a>, <a href=\"#\" data-headword=\"*אֲלִיקִי\">אֲלִיקִי</a>. <span class=\"citation\">Y. Ned. XI, 42ᶜ</span> top, how did you swear? He said, ‘I swore Efofé Yisrael’ (for, <i>By the God of Israel</i>), ‘I will not enter my house’. He replied, (you said) <i>Efofe Yisrael</i>, <span dir=\"rtl\">ולא עללת לביתיך</span> (not <span dir=\"rtl\">עללה</span>) and on that account you would not enter your house?</div>","alt":[]},"1545":{"h":"איפופיס","r":"A01545","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפֹּופְסִין\">אפופסין</a></div>","alt":["איפופסים","איפופסין","איפופסיס"]},"1546":{"h":"איפוריא","r":"A01546","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"הוֹבְרָיָא\">אוֹ׳</a>, v. <a href=\"#\" data-headword=\"*אָפֹּורְיָיא\">אָפֹּורְיָא</a></div>","alt":[]},"1547":{"h":"אִיפּוּרְיָיא","r":"A01547","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפִּרְיָין\">אַפִּרְיָין</a></div>","alt":[]},"1548":{"h":"*אִיפֹּותוֹרוֹס","r":"A01548","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἱπποθόρος, sub. νόμος, <span dir=\"rtl\">שירת</span>) <i>a tune played to mares on being covered</i>. <span class=\"citation\">Cant. R. to I, 9</span> (being asked why they rushed into the water, the horses said) <span dir=\"rtl\">א׳ נעשית לכם בים</span> (ed. <a href=\"#\" data-headword=\"איפתוסים\">איפתיסיס</a>, <a href=\"#\" data-headword=\"איפתוסים\">איפתוסים</a>, <a href=\"#\" data-headword=\"אִיפַּרְכִי\">אפ׳</a> corr. acc.) a hippothoros is prepared for you in the Sea (a satire on Egyptian lasciviousness).</div>","alt":[]},"1549":{"h":"אֶיפְטָא","r":"A01549","html":"<div class=\"sense\"> (ἑπτά) <i>seven</i>. <span class=\"citation\">Gen. R. s. 14</span>, beg.; a. e. V. <a href=\"#\" data-headword=\"אִיטָא\">אֵיטָא</a>.</div>","alt":["אֶפְטָא"]},"1550":{"h":"אִיפַּטְיָא","r":"A01550","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ὑπατεία) prop. <i>Roman consulship, consulate</i>, in gen. <i>era</i>, dating from accession to government or an other important event. <span class=\"citation\">Lev. R. s. 36</span> <span dir=\"rtl\">נמנה בא׳ של מלכים</span> (Ahaz) was counted under the era of kings (under whom Isaiah prophesied). Num. R. beg. <span dir=\"rtl\">ואיזה א׳</span>—<span dir=\"rtl\">איזה יום</span> what day, month, year and era (from the exodus from Egypt.). Pesik. Baḥod. p. 104ᵃ <span dir=\"rtl\">היו מונין א׳ וכ׳</span> count ye a new era from my son’s redemption. Ib. Haḥod. p. 52ᵇ sq. he wrote her marriage contract <span dir=\"rtl\">וכתב לה א׳</span> in which he stated the era of his government.</div>","alt":["אִיפַּטִּיאָה","(אִפַּטְיָא)"]},"1551":{"h":"אִיפָּטִיקוֹס","r":"A01551","html":"<div class=\"sense\"> (incorr. <span dir=\"rtl\">איפוט׳</span>, <span dir=\"rtl\">איפיט׳</span>) m. (ὑπατικός) <i>consularis, Emperor’s delegate, viceroy</i>. Mekh. B’shall. Amalek, 2, <span dir=\"rtl\">א׳ מבטל וכ׳</span> the Hypaticus annuls it over his (the Hegemon’s) hand (ignoring his authority).—Pl. <span dir=\"rtl\">אִיפָּטִיקִין</span>. Tanḥ. (ed. Bub.), Vayesheb 2 <span dir=\"rtl\">אפסיקין</span> (corr. acc., v. note 4). V. <a href=\"#\" data-headword=\"הִיפָּטִיקוֹס\">היפטיקוס</a>.</div>","alt":[]},"1552":{"h":"איפיטיקוס","r":"A01552","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיפָּטִיקוֹס\">preced.</a></div>","alt":[]},"1553":{"h":"אִיפְּכָא","r":"A01553","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">אפך</span>) <i>the reverse, opposite</i>. <span class=\"citation\">Bekh. 5ᵃ</span>, a. fr. <span dir=\"rtl\">אנן א׳ מתנינן לה</span> our version is the reverse. <span class=\"citation\">Ḥull. 20ᵇ</span>, a. fr. <span dir=\"rtl\">אדרבא א׳ מסתברא</span>, v. <a href=\"#\" data-headword=\"אַדְּרַבָּא\">אַדְּרַבָּא</a>. <span class=\"citation\">R. Hash. 20ᵃ</span>; a. v. fr.</div>","alt":[]},"1554":{"h":"איפליקתא","r":"A01554","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפִּיקִילְטָא\">אַפִּיקִילְטָא</a></div>","alt":[]},"1555":{"h":"אִיפַּסְטְלִין","r":"A01555","html":"<div class=\"sense\"> (אֲפִיצְטְלִין Mus.) m. pl. (pastilli) <i>lozenges, pills of sugar</i>. <span class=\"citation\">Cant. R. to I, 2</span>.  v. <a href=\"#\" data-headword=\"פִּיצְטְלִין\">פִּיצְטְלִין</a>, <a href=\"#\" data-headword=\"פִּסְטִילּוֹס\">פּסְטילוֹס</a>; cmp. <span class=\"citation\">Yalk. Cant. 981</span>.</div>","alt":[]},"1556":{"h":"איפסטקין","r":"A01556","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אַפִּסְטְ׳</span></div>","alt":[]},"1557":{"h":"אֶיפְסָר","r":"A01557","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפְסָר\">אַפְסָר</a></div>","alt":[]},"1558":{"h":"איפקינון","r":"A01558","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָנְפַּקִּינוֹן\">אָנְפָּקִינוֹן</a></div>","alt":[]},"1559":{"h":"אִיפְקַרְסִין","r":"A01559","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיפַּרְכִי\">אַפְ׳</a></div>","alt":[]},"1560":{"h":"אֶיפְרָא","r":"A01560","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲפַר ²\">אֶפְרָא</a></div>","alt":[]},"1561":{"h":"אִיפְרָא","r":"A01561","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>Ifra</i>. <span class=\"citation\">Zeb. 116ᵇ I</span>. Ormuzd, mother of king Shapur; <span class=\"citation\">B. Bath. 8ᵃ</span> bot; <span class=\"citation\">Taan. 24ᵇ</span>; <span class=\"citation\">Nidd. 20ᵇ</span> <a href=\"#\" data-headword=\"אִיפַּרְכִי\">אפ׳</a>.</div>","alt":[]},"1562":{"h":"אִיפַּרְוָון","r":"A01562","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִפַּרְוָורִין\">אִפַּרְוָורִין</a></div>","alt":[]},"1563":{"h":"*איפרוטוס","r":"A01563","html":"<div class=\"sense\">, Midr. Sam. s. 5 <span dir=\"rtl\">א׳ משלו היה</span> read <span dir=\"rtl\">הפְּרוּטוֹת … היו</span> (v. <a href=\"#\" data-headword=\"פְּרוּטָה\">פְּרוּטָה</a>, esp. <span class=\"citation\">Pes. 50ᵇ</span>) he (Nebucadnezar) had to pay the writer’s fees (for the change of <span dir=\"rtl\">בר אלהין</span> into <span dir=\"rtl\">מלאכיה</span> <span class=\"citation\">Dan. III, 25</span>; <span class=\"citation\">28</span>), i.e. had to suffer for it; v. <a href=\"#\" data-headword=\"*אִימּוּס\">אִימּוּס</a>. <span class=\"citation\">Cant. R. to VII, 9</span> <span dir=\"rtl\">פריטין משלו היו</span> read <span dir=\"rtl\">פרוטין</span>.</div>","alt":[]},"1564":{"h":"אִיפַּרְכָא","r":"A01564","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὕπαρχος, ἔπαρχος) <i>prefect of a province </i>or<i> town; governor, lieutenant</i>. <span class=\"citation\">Gen. R. s. 11</span>; a. v. fr.—Pl. <a href=\"#\" data-headword=\"אִיפַּרְכִי\">אִיפַּרְכִין</a>, <a href=\"#\" data-headword=\"אִיפַּרְכִי\">אִפַּ׳</a>; <a href=\"#\" data-headword=\"אֶפַּרְכִי\">אִפַּרְכֵי</a>, <a href=\"#\" data-headword=\"אִיפַּרְכִי\">אִיפַּרְכַיָּא</a>. <span class=\"citation\">Targ. Y. Num. XI, 28</span>. <span class=\"citation\">Targ. Esth. I, 3</span>; a. e.—<span class=\"citation\">Shebu. 6ᵇ</span>; a. fr.</div>","alt":["אִיפַּרְכָה","אֶפַּרְכָא","אֶפַּרְכוֹס"]},"1565":{"h":"אִיפַּרְכוֹס","r":"A01565","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיפַּרְכָא\">preced.</a></div>","alt":[]},"1566":{"h":"אִיפַּרְכוּסְיָא","r":"A01566","html":"<div class=\"sense\"> f. (deriv. of <a href=\"#\" data-headword=\"אִיפַּרְכוֹס\">preced.</a>) = <a href=\"#\" data-headword=\"אִיפַּרְכִי\">next w.</a></div>","alt":[]},"1567":{"h":"אִיפַּרְכִי","r":"A01567","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἐπαρχία) <i>prefecture, province, town-government</i>. <span class=\"citation\">Gen. R. s. 39</span>; a. fr. [In Targ. also <a href=\"#\" data-headword=\"אִיפַּרְכָיוּתָא\">אִיפַּרְכָיוּתָא</a>.]—Pl. <span dir=\"rtl\">אִיפַּרְכִיֹּות</span>, <a href=\"#\" data-headword=\"אִיפַּרְכִי\">אִפַּ׳</a>. <span class=\"citation\">Gen. R. s. 89</span>; a. e. [<span class=\"citation\">Targ. Lam. I, 1</span> <a href=\"#\" data-headword=\"אַפְרִיקִי II\">אַפְרִיכְיָא</a>, read <a href=\"#\" data-headword=\"אִיפַּרְכִי\">אִיפַּרְכַיָּיא</a>. <span class=\"citation\">Targ. Y. II, Deut. III, 11</span> <span dir=\"rtl\">אפרכיון</span>, read <span dir=\"rtl\">בֵּי אֵרְכִיוָן</span>.] [Midr. Sam. ch. VII, <span dir=\"rtl\">לא׳</span> (Var. <span dir=\"rtl\">לאפי</span>), v. <a href=\"#\" data-headword=\"אַפַּנְטֵי\">אַפַּנְטֵי</a>.]</div>","alt":["אִיפַּרְכְיָא","אִפַּ׳"]},"1568":{"h":"אִיפַּרְכָיוּתָא","r":"A01568","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיפַּרְכִי\">preced.</a></div>","alt":[]},"1569":{"h":"*אִיפַּרְסֵן","r":"A01569","html":"<div class=\"sense\"> (Ithpe. denom. of <a href=\"#\" data-headword=\"פּוּרְסָן\">פּוּרְסָן</a>) <i>he was taxed</i> (by Roman officials), i.e. his property was seized for taxes. <span class=\"citation\">Y. Kidd. III, 64ᵃ</span> top <span dir=\"rtl\">א׳ לוי</span></div>","alt":[]},"1570":{"h":"איפרפוס","r":"A01570","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפֹּופְסִין\">אַפֹּופְסִין</a></div>","alt":[]},"1571":{"h":"אֶיפֶשׁ","r":"A01571","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶפֶשׁ\">אֶפֶשׁ</a> a. <a href=\"#\" data-headword=\"אֶפְשַׁר\"><a href=\"#\" data-headword=\"אֶפְשַׁר\">אֶפְשַׁר</a>.</a></div>","alt":["אִיפְשַׁר"]},"1572":{"h":"איפתוסים","r":"A01572","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִיפֹּותוֹרוֹס\">אִיפֹּותוֹרוֹס</a></div>","alt":["איפתיסיס"]},"1573":{"h":"אִיצָא I","r":"A01573","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוּץ\">אוץ</a>) <i>ozier, prickly twigs</i>. <span class=\"citation\">Gitt. 69ᵇ</span> <span dir=\"rtl\">א׳ רטיבא וכ׳</span> (Ar. <a href=\"#\" data-headword=\"אִצָּא\">אִצָּא</a>) green twigs with which the river is dammed in (figur. for diarrhœa stopped). Cmp. <a href=\"#\" data-headword=\"הוּצָא I\">הוּצָא</a>.</div>","alt":[]},"1574":{"h":"אִיצָא II","r":"A01574","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוּץ\">אוץ</a>, <span dir=\"rtl\">אצץ</span>) </div><div class=\"sense\"><b>1)</b> <i>squeezing, pressure</i>. <span class=\"citation\">Yeb. 121ᵇ</span> top, <span dir=\"rtl\">אגב איצצא מזקי</span> (Ar. <a href=\"#\" data-headword=\"אִיצָא I\">איצא</a>) on account of the pressure (which the falling person exercises on the serpents in the pit) they injure him. <span class=\"citation\">Sabb. 144ᵇ</span> דאתי בתר איצצא Ar. (ed. <a href=\"#\" data-headword=\"אִיצָא II\">איצצתא</a>; Ms. M. <span dir=\"rtl\">אִיצִיצָא</span>) (the juice) which oozes out of the grapes through the pressure of their non weight. <span class=\"citation\">M. Kat. 11ᵃ</span> salted fish made fit for immediate use <span dir=\"rtl\">אגב א׳</span> by squeezing (and washing) out the salt.—Pl. <span dir=\"rtl\">אִיצְצֵי</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שיתין א׳</span> sixty times pressed and washed.</div><div class=\"sense\"><b>—2)</b>  trnsf. <i>depression, depreciation</i> in the market; [oth. opin. <i>deterioration</i> of quality]. <span class=\"citation\">Keth. 100ᵇ</span> <span dir=\"rtl\">אע&quot;ג דנפל ביה איצצתא</span> (read <span dir=\"rtl\">דנפלא</span>; Ar. <span dir=\"rtl\">דהוי ביה איצא</span>, Rashi <a href=\"#\" data-headword=\"אִיצָא II\">איצצא</a>) though there is a risk <i>of depreciation</i> (on account of large supply for the festive season) [or <i>of getting sour</i>].</div>","alt":["אִיצְצָא","אִיצַצְתָּא"]},"1575":{"h":"איצבתו","r":"A01575","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אֲצַבְתִּי\">אֲצַבְתִּי</a></div>","alt":["אִיצַבְתִּי"]},"1576":{"h":"אִיצְטַדְיָא","r":"A01576","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צדי\">צדי</a>, v. <a href=\"#\" data-headword=\"אִיצְטַדִּין\">next w.</a>) </div><div class=\"sense\"><b>1)</b> <i>destruction</i>.</div><div class=\"sense\"><b>—2)</b>  (cacophem.) <i>theatre;</i> v. <a href=\"#\" data-headword=\"אִצְטַדְיָא\">אִצְטַדְיָא</a>.</div>","alt":[]},"1577":{"h":"אִיצְטַדִּין","r":"A01577","html":"<div class=\"sense\"> f. (orig. m. pl., Ithp. of <a href=\"#\" data-headword=\"צדי\">צדי</a> q. v.; sub. <span dir=\"rtl\">שדה</span> &amp;c.) </div><div class=\"sense\"><b>1)</b> <i>a place full of ruins</i>. Y. Erub. II, 22ᵇ <span dir=\"rtl\">את רואה את הא׳ כילו וכ׳</span> you look upon the debris near Tiberias as &amp;c. (cmp. <a href=\"#\" data-headword=\"*אִלְסִיס\">אלסיס</a>).—*Pl. <a href=\"#\" data-headword=\"אִצְטַדִּין\">איצְטַדִּינִין</a>. <span class=\"citation\">B. Bath. 103ᵇ</span> <span dir=\"rtl\">א׳ מהו</span> if the stones in the field are debris, how is it? [Comment. diff.]</div><div class=\"sense\"><b>—2)</b>  cacophemism for <i>theatre</i> (a <i>place of destruction</i>). [The prevailing versions are <span dir=\"rtl\">אצטרין</span>, <span dir=\"rtl\">אסטרין</span> q. v.]</div>","alt":[]},"1578":{"h":"איצטיוראן","r":"A01578","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. B. Kam. VI, 28</span>, read <span dir=\"rtl\">אצטבא</span> or <span dir=\"rtl\">אצטווא</span>.</div>","alt":[]},"1579":{"h":"אִיצְטְנִיסִית","r":"A01579","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִסְטָנִית\">אִסְטָנִית</a></div>","alt":[]},"1580":{"h":"איצטרי","r":"A01580","html":"<div class=\"sense\"> <span class=\"citation\">Yeb. 17ᵃ</span>, v. <a href=\"#\" data-headword=\"צְרֵי I\">צרי</a></div>","alt":[]},"1581":{"h":"אִיצְיָיתָא","r":"A01581","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִצְיָיא\">אִצְיָיא</a></div>","alt":[]},"1582":{"h":"*אִיצְרָא","r":"A01582","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲצַר I\">אֲצַר</a> q. v.) <i>what is pressed out, juice</i>. <span class=\"citation\">Gitt. 69ᵇ</span> (Ar. <span dir=\"rtl\">עצרא</span>).</div>","alt":[]},"1583":{"h":"אִיצְרוֹלוֹגִין","r":"A01583","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַסְטְרוֹלוֹגוֹס\">אַסְטְרוֹלוֹגוֹס</a></div>","alt":[]},"1584":{"h":"*אִיקָא","r":"A01584","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אוק</span> = <span dir=\"rtl\">עוק</span>; cmp. Lat. ambire, b. h. <span dir=\"rtl\">סבב</span>) <i>stallion-goat, buck</i>. <span class=\"citation\">Sabb. 152ᵃ</span> א׳ שליפא וכ׳ Ar. (ed. <a href=\"#\" data-headword=\"עִיקָּר ²\">עיקרא</a>, <a href=\"#\" data-headword=\"עֲקִירָא\">עקירא</a>, Ms. Oxf. <span dir=\"rtl\">עיקר</span>, Ag. Hatt. <a href=\"#\" data-headword=\"עֲקַר I\">עקר</a>, v. Rabb. D. S. a. l. note 40) a goat, if castrated, sells for eight &amp;c. [V. Sachs Beitr. II, 131 sq.]</div>","alt":[]},"1585":{"h":"איקוביטון","r":"A01585","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אַק׳</span></div>","alt":[]},"1586":{"h":"*איקוטטא","r":"A01586","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 5</span>, v. <span dir=\"rtl\">דאיקוטטא</span>.</div>","alt":[]},"1587":{"h":"אִיקוֹמוֹנוֹס","r":"A01587","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אִיקוֹנוֹמוֹס\">אִיקוֹנוֹמוֹס</a>.</div>","alt":[]},"1588":{"h":"אִיקוּמֵינֵי","r":"A01588","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (οἰκουμένη) <i>the inhabited earth</i>. <span class=\"citation\">Koh. R. VI, 3</span> <span dir=\"rtl\">אוקו׳</span> (corr. acc.); <span class=\"citation\">Gen. R. s. 32</span> <span dir=\"rtl\">יקו׳</span> (corr. acc.) (play on <i>y’kum</i> <span class=\"citation\">Gen. VII, 4</span>).</div>","alt":[]},"1589":{"h":"איקומנוס","r":"A01589","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיקוֹנוֹמוֹס\">אִיקוֹנוֹמוֹס</a></div>","alt":[]},"1590":{"h":"אִיקוֹן","r":"A01590","html":"<div class=\"sense\"> c. (εἰκών) <i>likeness, portrait, iconic statue</i>. <span class=\"citation\">Targ. Y. Gen. V, 3</span>.—Pl. h. <a href=\"#\" data-headword=\"אִיקוֹנִין\">אִיקוֹנִין</a>, <span dir=\"rtl\">אִיקוֹנוֹת</span>; ch. <a href=\"#\" data-headword=\"*אִיקוֹנְיָא II\">אִיקוֹנַיָּא</a>, <span dir=\"rtl\">אִיקוֹנָתָא</span>. <span class=\"citation\">Ex. R. s. 30</span> <span dir=\"rtl\">(<span dir=\"rtl\">של מלך</span>) <a href=\"#\" data-headword=\"א׳\">א׳</a></span> emperor’s <i>statues;</i> a. fr.—Y. Ab. Zar. III, beg. 42ᵇ <span dir=\"rtl\">איקוניות</span>, <span dir=\"rtl\">איקינות</span> read <span dir=\"rtl\">אִיקוֹנוֹת</span>. Ib. 42ᶜ top; a. e. V. <a href=\"#\" data-headword=\"אִיקוֹנִין\">אִיקוֹנִין</a>. [<span class=\"citation\">Midr. Till. to Ps. XV</span>, XVII, v. <a href=\"#\" data-headword=\"*אִיקוֹנְיָא I\">אִיקוֹנְיָא</a>.]</div>","alt":["אִיקוּנָא","(אִק׳)"]},"1591":{"h":"אִיקוֹנוֹמוֹס","r":"A01591","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (οἰκόνομος) <i>steward, town-clerk</i> (a slave). Y. B. Mets. IX, beg. 12ᵃ. <span class=\"citation\">Y. B. Bath. IV, 14ᶜ</span> bot. <a href=\"#\" data-headword=\"איקומנוס\">איקומנוס</a> (corr. acc.). <span class=\"citation\">B. Bath. 68ᵇ</span> <span dir=\"rtl\">אינקלמוס</span>, <span dir=\"rtl\">אנקולמוס</span>, <span dir=\"rtl\">אנקל׳</span>, <a href=\"#\" data-headword=\"אֶנְקְלִיטוֹן\">אונק׳</a> (popul. corrupt.).</div>","alt":[]},"1592":{"h":"*אִיקוֹנְיָא I","r":"A01592","html":"<div class=\"sense\"> (pl. of εἰκόνιον) <i>statuary</i>. <span class=\"citation\">Midr. Till. to Ps. XV</span> (ref. to <span class=\"citation\">Is. XXXI, 9</span>, applied to the Roman empire or emperor) ‘his rock’ <span dir=\"rtl\">זה א׳</span> this means the statues with the likenesses of the emperors (v. Sm. Ant. s. v. Statuary).</div>","alt":[]},"1593":{"h":"*אִיקוֹנְיָא II","r":"A01593","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (pl. as a collect. noun) (denom. of <a href=\"#\" data-headword=\"אִיקוֹן\">אִיקוֹן</a>) <i>a procession in which portable images are carried</i>. <span class=\"citation\">Midr. Till. to Ps. XVII</span> <span dir=\"rtl\">א׳ של מלאכים וכ׳</span> a procession of angels passes before man and they cry, Make room <span dir=\"rtl\">לאיקוניה של וכ׳</span> (read <span dir=\"rtl\">לְאִקוֹנָיו</span> or <span dir=\"rtl\">לְאִיקוֹנוֹת</span>; <span class=\"citation\">Yalk. Ps. 670</span>; <span class=\"citation\">Deut. R. s. 4</span> <a href=\"#\" data-headword=\"לִיקוּנִין\">לאִיקוֹנִין</a>) for the images of the Lord (man being created in the image of God). Deut. R. l. c. <span dir=\"rtl\">או׳ מהלכת</span> (corr. acc.).</div>","alt":["אִיקוּנְיָא"]},"1594":{"h":"איקוניה","r":"A01594","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִיקוֹנְיָא II\">preced.</a></div>","alt":[]},"1595":{"h":"איקונים","r":"A01595","html":"<div class=\"sense\"> read <a href=\"#\" data-headword=\"אִיקוֹנִין\">אִיקוֹנִין</a>.</div>","alt":[]},"1596":{"h":"אִיקוֹנִין","r":"A01596","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (εἰκόνιον) <i>picture, image;</i> <span class=\"citation\">Targ. Y. Gen. IV, 5</span> <i>features</i> (pl.); a. fr.—<span class=\"citation\">Ex. R. s. 15</span>. <span class=\"citation\">Deut. R. s. 4</span>, v. <a href=\"#\" data-headword=\"*אִיקוֹנְיָא II\"><span dir=\"rtl\">אִיקוֹנְיָא</span> II</a>; a. fr.—Esp. <span dir=\"rtl\">זִיו א׳</span> the brightness of expression, <i>features</i>.—<span class=\"citation\">Gen. R. s. 53</span>; a. fr.—<span class=\"citation\">Ex. R. s. 35</span> <span dir=\"rtl\">א׳ נאה</span> (sub. <a href=\"#\" data-headword=\"זִיו\">זיו</a>) <i>fine appearance;</i> <span class=\"citation\">Cant. R. to III, 11</span> <a href=\"#\" data-headword=\"אותונין\">אותונין</a> (corr. acc.).—Pl. v. <a href=\"#\" data-headword=\"אִיקוֹן\">אִיקוֹן</a></div>","alt":["(אקונין)"]},"1597":{"h":"אֶיקְלִיטָא","r":"A01597","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אֶקְ׳</span></div>","alt":[]},"1598":{"h":"איקלין","r":"A01598","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ab. Zar. II, 41ᵈ</span>, read with some ed. <span dir=\"rtl\">איקרין</span>, v. <a href=\"#\" data-headword=\"אִיקָר\">אִיקָר</a></div>","alt":[]},"1599":{"h":"אִיקְלַס","r":"A01599","html":"<div class=\"sense\"> Ithpe. of <a href=\"#\" data-headword=\"קְלַס\">קְלַס</a>.</div>","alt":[]}};
